function AnimatedNumber({
  value,
  prefix = "",
  suffix = "",
  duration = 800,
  decimals = 0,
}) {
  const [display, setDisplay] = React.useState(0);
  const numVal =
    typeof value === "number"
      ? value
      : parseFloat(String(value).replace(/[^0-9.-]/g, "")) || 0;
  React.useEffect(() => {
    let start = 0;
    const startTime = Date.now();
    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setDisplay(numVal * eased);
      if (progress < 1) requestAnimationFrame(animate);
    };
    requestAnimationFrame(animate);
  }, [numVal, duration]);
  return React.createElement(
    "span",
    null,
    `${prefix}${display.toFixed(decimals)}${suffix}`,
  );
}

function ProgressRing({ value = 0, size = 48, strokeWidth = 4, color }) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (Math.min(value, 100) / 100) * circumference;
  const ringColor =
    color || (value >= 80 ? C.green : value >= 50 ? C.amber : C.red);
  return React.createElement(
    "svg",
    { width: size, height: size, style: { transform: "rotate(-90deg)" } },
    React.createElement("circle", {
      cx: size / 2,
      cy: size / 2,
      r: radius,
      fill: "none",
      stroke: `${alpha(C.border, 37.6)}`,
      strokeWidth,
    }),
    React.createElement("circle", {
      cx: size / 2,
      cy: size / 2,
      r: radius,
      fill: "none",
      stroke: ringColor,
      strokeWidth,
      strokeDasharray: circumference,
      strokeDashoffset: offset,
      strokeLinecap: "round",
      style: {
        transition: "stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1)",
      },
    }),
  );
}

function ValianceTooltip({ children, text, position = "top" }) {
  const [show, setShow] = React.useState(false);
  const posStyles = {
    top: {
      bottom: "calc(100% + 8px)",
      left: "50%",
      transform: "translateX(-50%)",
    },
    bottom: {
      top: "calc(100% + 8px)",
      left: "50%",
      transform: "translateX(-50%)",
    },
    left: {
      right: "calc(100% + 8px)",
      top: "50%",
      transform: "translateY(-50%)",
    },
    right: {
      left: "calc(100% + 8px)",
      top: "50%",
      transform: "translateY(-50%)",
    },
  };
  return React.createElement(
    "div",
    {
      onMouseEnter: () => setShow(true),
      onMouseLeave: () => setShow(false),
      style: { position: "relative", display: "inline-flex" },
    },
    children,
    show &&
      React.createElement(
        "div",
        {
          style: {
            position: "absolute",
            ...posStyles[position],
            background: "var(--ds-text-primary)",
            color: "var(--ds-bg)",
            padding: "6px 10px",
            borderRadius: 6,
            fontSize: 11,
            fontWeight: 500,
            whiteSpace: "nowrap",
            zIndex: 9999,
            pointerEvents: "none",
            animation: "fadeIn 0.15s ease",
            boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
          },
        },
        text,
      ),
  );
}

function Breadcrumb({ items = [], onNavigate }) {
  if (items.length <= 1) return null;
  return React.createElement(
    "div",
    {
      style: {
        display: "flex",
        alignItems: "center",
        gap: 6,
        padding: "8px 0",
        fontSize: 11,
        color: C.textSecondary,
        animation: "fadeIn 0.2s ease",
      },
    },
    items.map((item, i) =>
      React.createElement(
        React.Fragment,
        { key: i },
        i > 0 && React.createElement("span", { style: { opacity: 0.4 } }, "›"),
        i < items.length - 1
          ? React.createElement(
              "span",
              {
                onClick: () => onNavigate && onNavigate(item.key),
                style: {
                  cursor: "pointer",
                  transition: "color 0.2s",
                  color: C.textSecondary,
                },
                onMouseEnter: (e) => (e.target.style.color = C.accent),
                onMouseLeave: (e) => (e.target.style.color = C.textSecondary),
              },
              item.label,
            )
          : React.createElement(
              "span",
              { style: { color: C.textPrimary, fontWeight: 600 } },
              item.label,
            ),
      ),
    ),
  );
}

function StatusDot({ status = "active", size = 8 }) {
  const colors = {
    active: C.green,
    warning: C.amber,
    critical: C.red,
    inactive: C.textSecondary,
  };
  const color = colors[status] || colors.active;
  return React.createElement("div", {
    style: {
      width: size,
      height: size,
      borderRadius: "50%",
      background: color,
      boxShadow: status === "active" ? `0 0 0 3px ${color}20` : "none",
      animation: status === "critical" ? "pulse 2s infinite" : "none",
    },
  });
}

