const numOrNull = (v) => {
  const s = String(v ?? "").trim();
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const fmt = (n, prefix = "$", suffix = "") => {
  if (prefix === "$") {
    const body = formatCurrency(n);
    return body === EMPTY ? body : `${body}${suffix}`;
  }
  const body = formatNumber(n);
  return body === EMPTY ? body : `${prefix}${body}${suffix}`;
};

const fmtFull = (n, prefix = "$") => {
  if (prefix === "$") return formatCurrencyFull(n);
  const body = formatNumber(n);
  return body === EMPTY ? body : `${prefix}${body}`;
};

const fmtSF = (n) =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1)}M SF` : `${(n / 1e3).toFixed(0)}K SF`;

const fmtPct = (n) => {
  const v = typeof n === "number" ? n : Number(n);
  if (n === null || n === undefined || !Number.isFinite(v)) return EMPTY;
  return `${v >= 0 ? "+" : ""}${v.toFixed(1)}%`;
};

