const computeWaterfall = (
  grossDist,
  equityBasis,
  prefRate = 0.08,
  catchUpSplit = 0.8,
  promoteTiers = [{ threshold: Infinity, gpSplit: 0.2 }],
) => {
  const prefReturn = Math.min(grossDist, equityBasis * prefRate);
  let remaining = grossDist - prefReturn;
  const catchUpTarget = prefReturn * (1 / (1 - catchUpSplit)) - prefReturn;
  const catchUp = Math.min(remaining, catchUpTarget);
  remaining -= catchUp;
  let promote = 0;
  for (const tier of promoteTiers) {
    const tierAmount = Math.min(remaining, tier.threshold);
    promote += tierAmount * tier.gpSplit;
    remaining -= tierAmount;
    if (remaining <= 0) break;
  }
  const gpShare = catchUp * catchUpSplit + promote;
  const lpShare = grossDist - gpShare;
  return { grossDist, prefReturn, catchUp, promote, gpShare, lpShare };
};

const exportToCSV = (headers, rows, filename = "export.csv") => {
  const csvContent = [
    headers.join(","),
    ...rows.map((row) =>
      row
        .map((cell) => {
          const val =
            typeof cell === "object" ? cell?.props?.children || "" : cell;
          const str = String(val).replace(/"/g, '""');
          return `"${str}"`;
        })
        .join(","),
    ),
  ].join("\n");
  const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
  URL.revokeObjectURL(link.href);
};

