const LPPortal = ({ role }) => {
  const [selectedLP, setSelectedLP] = useState(null);
  const [view, setView] = useState("overview");
  const [fundPerf, setFundPerf] = useState(null);
  const [fundPerfLoading, setFundPerfLoading] = useState(false);

  React.useEffect(() => {
    setFundPerfLoading(true);
    getFundPerformanceSummary()
      .then((data) => {
        setFundPerf(data);
        setFundPerfLoading(false);
      })
      .catch((err) => {
        console.error("[LPPortal] Fund perf load failed:", err);
        setFundPerfLoading(false);
      });
  }, []);

  const lpInvestors = INVESTORS.filter((i) => i.type === "LP");
  const currentLP = selectedLP
    ? INVESTORS.find((i) => i.id === selectedLP)
    : null;
  const lpAccounts = selectedLP
    ? LP_CAPITAL_ACCOUNTS.filter((a) => a.investorId === selectedLP)
    : [];
  const lpInvestments = selectedLP
    ? INVESTOR_INVESTMENTS.filter((i) => i.investorId === selectedLP)
    : [];
  const lpComms = selectedLP
    ? INVESTOR_COMMS.filter((c) => c.investorId === selectedLP)
    : [];
  const lpDocs = DOCUMENT_VAULT.filter((d) => d.access === "LP + GP");

  const lpTotals = useMemo(() => {
    if (!lpAccounts.length) return null;
    return {
      committed: lpAccounts.reduce((s, a) => s + a.committed, 0),
      called: lpAccounts.reduce((s, a) => s + a.called, 0),
      distributed: lpAccounts.reduce((s, a) => s + a.distributed, 0),
      nav: lpAccounts.reduce((s, a) => s + a.nav, 0),
      unfunded: lpAccounts.reduce((s, a) => s + a.unfunded, 0),
    };
  }, [lpAccounts]);

  if (!selectedLP) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
          <KPI
            label="Total LPs"
            value={lpInvestors.length}
            sub="Active limited partners"
          />
          <KPI
            label="Total LP Capital"
            value={fmt(
              LP_CAPITAL_ACCOUNTS.reduce((s, a) => s + a.committed, 0),
            )}
            sub="Across all funds"
          />
          <KPI
            label="LP Distributions"
            value={fmt(
              LP_CAPITAL_ACCOUNTS.reduce((s, a) => s + a.distributed, 0),
            )}
            sub="Cumulative"
            color={C.green}
          />
          <KPI
            label="K-1s Outstanding"
            value={
              LP_CAPITAL_ACCOUNTS.filter((a) => a.k1Status !== "Issued").length
            }
            sub="Pending issuance"
            color={
              LP_CAPITAL_ACCOUNTS.filter((a) => a.k1Status !== "Issued")
                .length > 0
                ? C.amber
                : C.green
            }
          />
        </div>
        {fundPerf && fundPerf.funds && fundPerf.funds.length > 0 && (
          <SectionCard title="Fund Performance Summary (Live)">
            <MiniTable
              columns={[
                { key: "name", label: "Fund" },
                { key: "vintage", label: "Vintage" },
                { key: "deployed", label: "AUM", format: fmt },
                {
                  key: "irr",
                  label: "Net IRR",
                  format: (v) => (v != null ? `${(v * 100).toFixed(1)}%` : "—"),
                },
                {
                  key: "equity_multiple",
                  label: "Equity Multiple",
                  format: (v) => (v != null ? `${v.toFixed(2)}x` : "—"),
                },
                { key: "status", label: "Status" },
              ]}
              data={fundPerf.funds}
            />
          </SectionCard>
        )}
        <SectionCard title="Select an Investor">
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
              gap: 12,
            }}
          >
            {lpInvestors.map((lp) => {
              const accounts = LP_CAPITAL_ACCOUNTS.filter(
                (a) => a.investorId === lp.id,
              );
              const totalNav = accounts.reduce((s, a) => s + a.nav, 0);
              return (
                <button
                  key={lp.id}
                  onClick={() => setSelectedLP(lp.id)}
                  style={{
                    textAlign: "left",
                    padding: 16,
                    borderRadius: 10,
                    border: `1px solid ${C.border}`,
                    background: C.white,
                    cursor: "pointer",
                    transition: "all 0.2s",
                  }}
                >
                  <div
                    style={{
                      fontWeight: 700,
                      color: C.textPrimary,
                      fontSize: 14,
                    }}
                  >
                    {lp.name}
                  </div>
                  <div
                    style={{
                      fontSize: 11,
                      color: C.textSecondary,
                      marginTop: 2,
                    }}
                  >
                    {lp.entity}
                  </div>
                  <div
                    style={{
                      display: "flex",
                      gap: 12,
                      marginTop: 8,
                      fontSize: 12,
                    }}
                  >
                    <span>
                      <strong style={{ color: C.accent }}>
                        {fmt(totalNav)}
                      </strong>{" "}
                      NAV
                    </span>
                    <span>{accounts.length} fund(s)</span>
                    <Badge
                      text={lp.tier}
                      color={
                        lp.tier === "Institutional"
                          ? "blue"
                          : lp.tier === "Anchor"
                            ? "purple"
                            : "green"
                      }
                    />
                  </div>
                </button>
              );
            })}
          </div>
        </SectionCard>
      </div>
    );
  }

  const views = [
    { label: "Capital Account", key: "overview" },
    { label: "Distributions", key: "distributions" },
    { label: "Tax / K-1", key: "tax" },
    { label: "Documents", key: "documents" },
    { label: "Communications", key: "comms" },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <Breadcrumb
        items={[
          { label: "LP Portal", onClick: () => setSelectedLP(null) },
          { label: currentLP?.name || "" },
        ]}
      />
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {views.map((v) => (
          <button
            key={v.key}
            onClick={() => setView(v.key)}
            style={{
              padding: "8px 16px",
              borderRadius: 8,
              fontSize: 12,
              fontWeight: 600,
              cursor: "pointer",
              border:
                view === v.key
                  ? `2px solid ${C.accent}`
                  : `1px solid ${C.border}`,
              background: view === v.key ? "var(--ds-info-bg)" : C.white,
              color: view === v.key ? C.accent : C.textSecondary,
            }}
          >
            {v.label}
          </button>
        ))}
      </div>

      {view === "overview" && lpTotals && (
        <>
          <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
            <KPI
              label="Total Committed"
              value={fmt(lpTotals.committed)}
              sub={`Across ${lpAccounts.length} funds`}
            />
            <KPI
              label="Capital Called"
              value={fmt(lpTotals.called)}
              sub={`${(lpTotals.committed > 0 ? (lpTotals.called / lpTotals.committed) * 100 : 0).toFixed(0)}% called`}
            />
            <KPI
              label="Distributions"
              value={fmt(lpTotals.distributed)}
              sub="Cumulative"
              color={C.green}
            />
            <KPI
              label="Current NAV"
              value={fmt(lpTotals.nav)}
              sub={`TVPI: ${(lpTotals.called > 0 ? (lpTotals.distributed + lpTotals.nav) / lpTotals.called : 0).toFixed(2)}x`}
              color={C.accent}
            />
          </div>
          <SectionCard title="Capital Account by Fund">
            <MiniTable
              columns={[
                { key: "fund", label: "Fund" },
                { key: "committed", label: "Committed", format: fmt },
                { key: "called", label: "Called", format: fmt },
                { key: "distributed", label: "Distributed", format: fmt },
                { key: "nav", label: "NAV", format: fmt },
                { key: "unfunded", label: "Unfunded", format: fmt },
                {
                  key: "tvpi",
                  label: "TVPI",
                  format: (v) => `${v.toFixed(2)}x`,
                },
                {
                  key: "irr",
                  label: "Net IRR",
                  format: (v) => `${v.toFixed(1)}%`,
                },
              ]}
              data={lpAccounts}
            />
          </SectionCard>
          <SectionCard title="Investment Detail">
            <MiniTable
              columns={[
                { key: "fund", label: "Fund" },
                { key: "property", label: "Property" },
                { key: "contrib", label: "Contributed", format: fmt },
                { key: "dist", label: "Distributed", format: fmt },
                {
                  key: "unrealizedValue",
                  label: "Unrealized Value",
                  format: fmt,
                },
                {
                  key: "ownership",
                  label: "Ownership %",
                  format: (v) => `${v.toFixed(2)}%`,
                },
              ]}
              data={lpInvestments}
            />
          </SectionCard>
        </>
      )}

      {view === "distributions" && (
        <SectionCard title="Distribution History">
          <MiniTable
            columns={[
              { key: "quarter", label: "Quarter" },
              { key: "fund", label: "Fund" },
              { key: "type", label: "Type" },
              { key: "amount", label: "Fund Total", format: fmt },
              {
                key: "perUnit",
                label: "Per Unit ($)",
                format: (v) => `$${v.toFixed(2)}`,
              },
            ]}
            data={DISTRIBUTION_HISTORY.filter((d) =>
              lpAccounts.some((a) => a.fund === d.fund),
            ).sort((a, b) => b.quarter.localeCompare(a.quarter))}
          />
        </SectionCard>
      )}

      {view === "tax" && (
        <>
          <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
            <KPI
              label="K-1s Issued"
              value={lpAccounts.filter((a) => a.k1Status === "Issued").length}
              sub={`of ${lpAccounts.length} total`}
              color={C.green}
            />
            <KPI
              label="K-1s Pending"
              value={lpAccounts.filter((a) => a.k1Status !== "Issued").length}
              sub="Under review"
              color={
                lpAccounts.filter((a) => a.k1Status !== "Issued").length > 0
                  ? C.amber
                  : C.green
              }
            />
            <KPI
              label="Total Tax Loss"
              value={fmt(
                Math.abs(
                  lpInvestments.reduce((s, i) => s + (i.k1TaxLoss || 0), 0),
                ),
              )}
              sub="2025 passthrough loss"
            />
            <KPI
              label="Total Tax Income"
              value={fmt(
                lpInvestments.reduce((s, i) => s + (i.k1TaxIncome || 0), 0),
              )}
              sub="2025 passthrough income"
            />
          </div>
          <SectionCard title="K-1 Status by Fund">
            <MiniTable
              columns={[
                { key: "fund", label: "Fund" },
                { key: "k1Status", label: "Status" },
                { key: "k1Date", label: "Issue Date" },
                { key: "committed", label: "Committed", format: fmt },
              ]}
              data={lpAccounts.map((a) => ({
                ...a,
                k1Date: a.k1Date || "Pending",
              }))}
            />
          </SectionCard>
          <SectionCard title="Tax Impact by Investment">
            <MiniTable
              columns={[
                { key: "fund", label: "Fund" },
                { key: "property", label: "Property" },
                {
                  key: "k1TaxLoss",
                  label: "Tax Loss (K-1)",
                  format: (v) => (v < 0 ? `(${fmt(Math.abs(v))})` : fmt(v)),
                },
                { key: "k1TaxIncome", label: "Tax Income (K-1)", format: fmt },
              ]}
              data={lpInvestments}
            />
          </SectionCard>
        </>
      )}

      {view === "documents" && (
        <SectionCard title="Available Documents">
          <MiniTable
            columns={[
              { key: "name", label: "Document" },
              { key: "category", label: "Category" },
              { key: "fund", label: "Fund" },
              { key: "date", label: "Date" },
              { key: "size", label: "Size" },
            ]}
            data={lpDocs}
          />
        </SectionCard>
      )}

      {view === "comms" && (
        <SectionCard title="Recent Communications">
          <MiniTable
            columns={[
              { key: "date", label: "Date" },
              { key: "type", label: "Type" },
              { key: "direction", label: "Direction" },
              { key: "subject", label: "Subject" },
              { key: "priority", label: "Priority" },
            ]}
            data={lpComms.sort((a, b) => b.date.localeCompare(a.date))}
          />
        </SectionCard>
      )}
    </div>
  );
};

const DocumentManagementHub = ({ defaultTab = "library" }) => {
  const [activeTab, setActiveTab] = useState(defaultTab);

  const tabBarStyle = {
    display: "flex",
    gap: 0,
    marginBottom: 20,
    borderBottom: `1px solid ${C.border}`,
    paddingBottom: 0,
  };
  const tabBtnStyle = (active) => ({
    padding: "10px 16px",
    background: "transparent",
    color: active ? C.textPrimary : C.textSecondary,
    border: "none",
    cursor: "pointer",
    fontWeight: active ? 600 : 500,
    fontSize: 13,
    borderBottom: active ? `2px solid ${C.accent}` : "2px solid transparent",
    transition: "all 0.15s",
    marginBottom: -1,
  });

  return (
    <div style={{ display: "flex", flexDirection: "column" }}>
      <div style={tabBarStyle}>
        <button
          style={tabBtnStyle(activeTab === "library")}
          onClick={() => setActiveTab("library")}
        >
          Document Library
        </button>
        <button
          style={tabBtnStyle(activeTab === "generator")}
          onClick={() => setActiveTab("generator")}
        >
          Document Generator
        </button>
      </div>

      {activeTab === "library" && <DocumentVaultPageContent />}
      {activeTab === "generator" && <DocumentGeneratorPageContent />}
    </div>
  );
};

const DocumentVaultPage = () => {
  return <DocumentManagementHub defaultTab="library" />;
};

const DocumentVaultPageContent = () => {
  const [search, setSearch] = useState("");
  const [filterCategory, setFilterCategory] = useState("All");
  const [filterFund, setFilterFund] = useState("All");

  const [showUploadModal, setShowUploadModal] = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const [uploadSource, setUploadSource] = useState(
    SOURCE_TYPES.SUPABASE_STORAGE,
  );
  const [uploadCategory, setUploadCategory] = useState("other");
  const [uploadAccess, setUploadAccess] = useState("gp_only");
  const [uploadDescription, setUploadDescription] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState(null);

  const categories = ["All", ...new Set(DOCUMENT_VAULT.map((d) => d.category))];
  const funds = ["All", ...new Set(DOCUMENT_VAULT.map((d) => d.fund))];

  const filtered = useMemo(() => {
    return DOCUMENT_VAULT.filter((d) => {
      if (filterCategory !== "All" && d.category !== filterCategory)
        return false;
      if (filterFund !== "All" && d.fund !== filterFund) return false;
      if (search && !d.name.toLowerCase().includes(search.toLowerCase()))
        return false;
      return true;
    });
  }, [search, filterCategory, filterFund]);

  const byCategory = useMemo(() => {
    const cats = {};
    DOCUMENT_VAULT.forEach((d) => {
      cats[d.category] = (cats[d.category] || 0) + 1;
    });
    return Object.entries(cats).map(([name, value]) => ({
      name: name.length > 15 ? name.substring(0, 14) + "…" : name,
      fullName: name,
      value,
    }));
  }, []);

  const resetUploadForm = () => {
    setUploadFile(null);
    setUploadSource(SOURCE_TYPES.SUPABASE_STORAGE);
    setUploadCategory("other");
    setUploadAccess("gp_only");
    setUploadDescription("");
    setUploadMsg(null);
  };

  const handleUpload = async () => {
    if (!uploadFile) {
      setUploadMsg({ kind: "error", text: "Please pick a file first." });
      return;
    }
    setUploading(true);
    setUploadMsg(null);
    try {
      const { document, error } = await uploadDocument(uploadFile, {
        source: uploadSource,
        category: uploadCategory,
        accessLevel: uploadAccess,
        description: uploadDescription,
      });
      if (error) {
        setUploadMsg({ kind: "error", text: error.message || "Upload failed" });
      } else {
        setUploadMsg({
          kind: "success",
          text: `Uploaded “${document?.file_name}” to ${getSourceLabel(uploadSource)}.`,
        });
        setUploadFile(null);
        try {
          const { reloadAllData } = await import("./lib/supabaseClient.js");
          if (typeof reloadAllData === "function") reloadAllData();
        } catch (_) {
          if (isChunkLoadFailure(_)) reportChunkFailure();
        }
      }
    } catch (err) {
      setUploadMsg({ kind: "error", text: err?.message || String(err) });
    } finally {
      setUploading(false);
    }
  };

  const handleDownload = async (row) => {
    const srcRow = row._raw || row;
    const { url, error } = await getDocumentDownloadUrl(srcRow);
    if (error) {
      alert(`Could not open document: ${error.message || "Unknown error"}`);
      return;
    }
    if (url) window.open(url, "_blank", "noopener,noreferrer");
  };

  const msConnected = !sourceRequiresAuth(SOURCE_TYPES.MICROSOFT_GRAPH);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KPI
          label="Total Documents"
          value={DOCUMENT_VAULT.length}
          sub="In vault"
        />
        <KPI
          label="Categories"
          value={categories.length - 1}
          sub="Document types"
        />
        <KPI
          label="Drafts"
          value={DOCUMENT_VAULT.filter((d) => d.status === "Draft").length}
          sub="In progress"
          color={C.amber}
        />
        <KPI
          label="GP-Only Docs"
          value={DOCUMENT_VAULT.filter((d) => d.access === "GP Only").length}
          sub="Restricted access"
        />
      </div>

      <SectionCard title="Documents by Category">
        <ResponsiveContainer width="100%" height={200}>
          <BarChart data={byCategory} layout="vertical">
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
            <XAxis type="number" tick={{ fontSize: 11 }} />
            <YAxis
              dataKey="name"
              type="category"
              tick={{ fontSize: 10 }}
              width={110}
            />
            <Tooltip
              labelFormatter={(v) =>
                byCategory.find((c) => c.name === v)?.fullName || v
              }
            />
            <Bar dataKey="value" fill={C.accent} radius={[0, 4, 4, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </SectionCard>

      <SectionCard
        title="Document Library"
        action={
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <input
              type="text"
              placeholder="Search documents..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{
                padding: "6px 12px",
                borderRadius: 6,
                border: `1px solid ${C.border}`,
                fontSize: 12,
                width: 200,
                color: C.textPrimary,
                background: C.white,
              }}
            />
            <Select
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
              size="sm"
              style={{ fontSize: 11, color: C.textSecondary }}
            >
              {categories.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </Select>
            <Select
              value={filterFund}
              onChange={(e) => setFilterFund(e.target.value)}
              size="sm"
              style={{ fontSize: 11, color: C.textSecondary }}
            >
              {funds.map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </Select>
            <button
              onClick={() => {
                resetUploadForm();
                setShowUploadModal(true);
              }}
              style={{
                padding: "6px 14px",
                borderRadius: 6,
                border: "none",
                background: C.accent,
                color: C.white,
                cursor: "pointer",
                fontSize: 12,
                fontWeight: 600,
              }}
            >
              + Upload Document
            </button>
          </div>
        }
      >
        <MiniTable
          columns={[
            { key: "name", label: "Document Name" },
            { key: "category", label: "Category" },
            { key: "fund", label: "Fund" },
            { key: "type", label: "Type" },
            { key: "date", label: "Date" },
            { key: "size", label: "Size" },
            { key: "status", label: "Status" },
            { key: "access", label: "Access" },
            {
              key: "_download",
              label: "",
              render: (_val, row) => (
                <button
                  onClick={() => handleDownload(row)}
                  style={{
                    padding: "4px 10px",
                    borderRadius: 4,
                    border: `1px solid ${C.border}`,
                    background: C.white,
                    color: C.textPrimary,
                    cursor: "pointer",
                    fontSize: 11,
                  }}
                  title={`Open from ${getSourceLabel(row.source_type || "supabase_storage")}`}
                >
                  Open
                </button>
              ),
            },
          ]}
          data={filtered}
        />
      </SectionCard>

      {showUploadModal && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.5)",
            zIndex: 1000,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
          onClick={() => !uploading && setShowUploadModal(false)}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              background: C.white,
              borderRadius: 12,
              padding: 24,
              width: 520,
              maxWidth: "90vw",
              maxHeight: "90vh",
              overflow: "auto",
              boxShadow: "0 20px 60px rgba(0,0,0,0.3)",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "flex-start",
                marginBottom: 16,
              }}
            >
              <div>
                <div
                  style={{
                    fontSize: 18,
                    fontWeight: 700,
                    color: C.textPrimary,
                  }}
                >
                  Upload Document
                </div>
                <div
                  style={{ fontSize: 12, color: C.textSecondary, marginTop: 4 }}
                >
                  File will be indexed in the document vault and stored in the
                  backend you choose.
                </div>
              </div>
              <button
                onClick={() => !uploading && setShowUploadModal(false)}
                style={{
                  background: "transparent",
                  border: "none",
                  fontSize: 22,
                  cursor: "pointer",
                  color: C.textSecondary,
                  lineHeight: 1,
                }}
              >
                ×
              </button>
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <div>
                <label
                  style={{
                    fontSize: 12,
                    fontWeight: 600,
                    color: C.textPrimary,
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  Destination
                </label>
                <div style={{ display: "flex", gap: 8 }}>
                  <button
                    onClick={() =>
                      setUploadSource(SOURCE_TYPES.SUPABASE_STORAGE)
                    }
                    style={{
                      flex: 1,
                      padding: "10px 12px",
                      borderRadius: 8,
                      border: `2px solid ${uploadSource === SOURCE_TYPES.SUPABASE_STORAGE ? C.accent : C.border}`,
                      background:
                        uploadSource === SOURCE_TYPES.SUPABASE_STORAGE
                          ? C.subtleBg
                          : C.white,
                      cursor: "pointer",
                      textAlign: "left",
                    }}
                  >
                    <div
                      style={{
                        fontSize: 12,
                        fontWeight: 600,
                        color: C.textPrimary,
                      }}
                    >
                      🗄️ Supabase Storage
                    </div>
                    <div
                      style={{
                        fontSize: 10,
                        color: C.textSecondary,
                        marginTop: 2,
                      }}
                    >
                      Platform-hosted, LP-accessible
                    </div>
                  </button>
                  <button
                    onClick={() =>
                      setUploadSource(SOURCE_TYPES.MICROSOFT_GRAPH)
                    }
                    disabled={!msConnected}
                    style={{
                      flex: 1,
                      padding: "10px 12px",
                      borderRadius: 8,
                      border: `2px solid ${uploadSource === SOURCE_TYPES.MICROSOFT_GRAPH ? C.accent : C.border}`,
                      background:
                        uploadSource === SOURCE_TYPES.MICROSOFT_GRAPH
                          ? C.subtleBg
                          : C.white,
                      cursor: msConnected ? "pointer" : "not-allowed",
                      textAlign: "left",
                      opacity: msConnected ? 1 : 0.5,
                    }}
                  >
                    <div
                      style={{
                        fontSize: 12,
                        fontWeight: 600,
                        color: C.textPrimary,
                      }}
                    >
                      📁 Microsoft 365 {!msConnected && "(not connected)"}
                    </div>
                    <div
                      style={{
                        fontSize: 10,
                        color: C.textSecondary,
                        marginTop: 2,
                      }}
                    >
                      OneDrive / SharePoint
                    </div>
                  </button>
                </div>
              </div>

              <div>
                <label
                  style={{
                    fontSize: 12,
                    fontWeight: 600,
                    color: C.textPrimary,
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  File
                </label>
                <input
                  type="file"
                  onChange={(e) => {
                    setUploadFile(e.target.files?.[0] || null);
                    setUploadMsg(null);
                  }}
                  style={{ fontSize: 12, width: "100%" }}
                />
                {uploadFile && (
                  <div
                    style={{
                      fontSize: 11,
                      color: C.textSecondary,
                      marginTop: 4,
                    }}
                  >
                    {uploadFile.name} · {(uploadFile.size / 1024).toFixed(1)} KB
                  </div>
                )}
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "1fr 1fr",
                  gap: 12,
                }}
              >
                <div>
                  <label
                    style={{
                      fontSize: 12,
                      fontWeight: 600,
                      color: C.textPrimary,
                      display: "block",
                      marginBottom: 6,
                    }}
                  >
                    Category
                  </label>
                  <Select
                    value={uploadCategory}
                    onChange={(e) => setUploadCategory(e.target.value)}
                    fullWidth
                    size="sm"
                    style={{ padding: "8px 10px" }}
                  >
                    <option value="other">Other</option>
                    <option value="fund_documents">Fund Documents</option>
                    <option value="property_documents">
                      Property Documents
                    </option>
                    <option value="tax_documents">Tax Documents</option>
                    <option value="debt_documents">Debt Documents</option>
                    <option value="investor_communications">
                      Investor Communications
                    </option>
                    <option value="legal">Legal</option>
                    <option value="due_diligence">Due Diligence</option>
                  </Select>
                </div>
                <div>
                  <label
                    style={{
                      fontSize: 12,
                      fontWeight: 600,
                      color: C.textPrimary,
                      display: "block",
                      marginBottom: 6,
                    }}
                  >
                    Access Level
                  </label>
                  <Select
                    value={uploadAccess}
                    onChange={(e) => setUploadAccess(e.target.value)}
                    fullWidth
                    size="sm"
                    style={{ padding: "8px 10px" }}
                  >
                    <option value="gp_only">GP Only</option>
                    <option value="lp_gp">LP + GP</option>
                  </Select>
                </div>
              </div>

              <div>
                <label
                  style={{
                    fontSize: 12,
                    fontWeight: 600,
                    color: C.textPrimary,
                    display: "block",
                    marginBottom: 6,
                  }}
                >
                  Description (optional)
                </label>
                <textarea
                  value={uploadDescription}
                  onChange={(e) => setUploadDescription(e.target.value)}
                  rows={2}
                  style={{
                    padding: "8px 10px",
                    borderRadius: 6,
                    border: `1px solid ${C.border}`,
                    fontSize: 12,
                    width: "100%",
                    color: C.textPrimary,
                    background: C.white,
                    resize: "vertical",
                    fontFamily: "inherit",
                  }}
                  placeholder="Brief note about this document..."
                />
              </div>

              {uploadMsg && (
                <div
                  style={{
                    padding: "8px 12px",
                    borderRadius: 6,
                    background:
                      uploadMsg.kind === "success"
                        ? "var(--ds-success-bg)"
                        : "var(--ds-danger-bg)",
                    color:
                      uploadMsg.kind === "success"
                        ? "var(--ds-success-text)"
                        : "var(--ds-danger-text)",
                    fontSize: 12,
                  }}
                >
                  {uploadMsg.text}
                </div>
              )}

              <div
                style={{
                  display: "flex",
                  gap: 8,
                  justifyContent: "flex-end",
                  marginTop: 6,
                }}
              >
                <button
                  onClick={() => !uploading && setShowUploadModal(false)}
                  disabled={uploading}
                  style={{
                    padding: "8px 16px",
                    borderRadius: 6,
                    border: `1px solid ${C.border}`,
                    background: C.white,
                    color: C.textPrimary,
                    cursor: uploading ? "not-allowed" : "pointer",
                    fontSize: 12,
                  }}
                >
                  Close
                </button>
                <button
                  onClick={handleUpload}
                  disabled={uploading || !uploadFile}
                  style={{
                    padding: "8px 20px",
                    borderRadius: 6,
                    border: "none",
                    background: uploading || !uploadFile ? C.border : C.accent,
                    color: C.white,
                    cursor:
                      uploading || !uploadFile ? "not-allowed" : "pointer",
                    fontSize: 12,
                    fontWeight: 600,
                  }}
                >
                  {uploading ? "Uploading..." : "Upload"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const WaterfallModeler = ({ filterProperty }) => {
  const [exitPrice, setExitPrice] = useState(WATERFALL_EXAMPLE_SEED.exitPrice);
  const [equityBasis, setEquityBasis] = useState(
    WATERFALL_EXAMPLE_SEED.equityBasis,
  );
  const [prefRate, setPrefRate] = useState(WATERFALL_EXAMPLE_SEED.prefRatePct);
  const [catchUpSplit, setCatchUpSplit] = useState(
    WATERFALL_EXAMPLE_SEED.catchUpSplitPct,
  );
  const [promoteRate, setPromoteRate] = useState(
    WATERFALL_EXAMPLE_SEED.promoteRatePct,
  );
  const [holdYears, setHoldYears] = useState(WATERFALL_EXAMPLE_SEED.holdYears);

  const sliderState = {
    exitPrice,
    equityBasis,
    prefRatePct: prefRate,
    catchUpSplitPct: catchUpSplit,
    promoteRatePct: promoteRate,
    holdYears,
  };
  const untouchedExample = isWaterfallExampleState(sliderState);

  const result = useMemo(() => {
    return computeWaterfall(
      exitPrice,
      equityBasis,
      prefRate / 100,
      catchUpSplit / 100,
      [{ threshold: Infinity, gpSplit: promoteRate / 100 }],
    );
  }, [exitPrice, equityBasis, prefRate, catchUpSplit, promoteRate]);

  const lpIRR = useMemo(() => {
    if (holdYears <= 0 || result.lpShare <= 0 || equityBasis <= 0) return 0;
    return (Math.pow(result.lpShare / equityBasis, 1 / holdYears) - 1) * 100;
  }, [result, equityBasis, holdYears]);

  const gpIRR = useMemo(() => {
    const gpEquity = equityBasis * GP_EQUITY_SHARE_OF_BASIS;
    if (holdYears <= 0 || result.gpShare <= 0 || gpEquity <= 0) return 0;
    return (Math.pow(result.gpShare / gpEquity, 1 / holdYears) - 1) * 100;
  }, [result, equityBasis, holdYears]);

  const waterfallBars = [
    { name: "Pref Return", lp: result.prefReturn, gp: 0 },
    { name: "GP Catch-Up", lp: 0, gp: result.catchUp * (catchUpSplit / 100) },
    {
      name: "Promote",
      lp:
        exitPrice - equityBasis * (prefRate / 100) - result.catchUp > 0
          ? result.lpShare - result.prefReturn
          : 0,
      gp: result.promote,
    },
  ];

  const scenarios = useMemo(() => {
    const exits = [
      exitPrice * 0.8,
      exitPrice * 0.9,
      exitPrice,
      exitPrice * 1.1,
      exitPrice * 1.2,
    ];
    return exits.map((ep) => {
      const r = computeWaterfall(
        ep,
        equityBasis,
        prefRate / 100,
        catchUpSplit / 100,
        [{ threshold: Infinity, gpSplit: promoteRate / 100 }],
      );
      return {
        exitPrice: ep,
        grossDist: r.grossDist,
        lpShare: r.lpShare,
        gpShare: r.gpShare,
        lpEM: equityBasis > 0 ? (r.lpShare / equityBasis).toFixed(2) : "0",
        gpEM:
          equityBasis > 0
            ? (r.gpShare / (equityBasis * GP_EQUITY_SHARE_OF_BASIS)).toFixed(2)
            : "0",
      };
    });
  }, [exitPrice, equityBasis, prefRate, catchUpSplit, promoteRate]);

  const SliderInput = ({
    label,
    value,
    onChange,
    min,
    max,
    step,
    format: fmtFn,
  }) => (
    <div style={{ marginBottom: 16 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: 4,
        }}
      >
        <span style={{ fontSize: 12, fontWeight: 600, color: C.textSecondary }}>
          {label}
        </span>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.accent }}>
          {fmtFn ? fmtFn(value) : value}
        </span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        style={{ width: "100%", accentColor: C.accent }}
      />
    </div>
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div
        data-testid="waterfall-example-banner"
        style={{
          display: "flex",
          alignItems: "flex-start",
          gap: 10,
          background: alpha(C.gold, 10),
          border: `1px solid ${alpha(C.gold, 45)}`,
          borderRadius: 10,
          padding: "12px 14px",
        }}
      >
        <span
          style={{
            background: C.gold,
            color: C.white,
            borderRadius: 4,
            padding: "2px 6px",
            fontSize: 10,
            fontWeight: 800,
            letterSpacing: 0.6,
            flexShrink: 0,
          }}
        >
          {untouchedExample ? WATERFALL_EXAMPLE_TAG : "HYPOTHETICAL"}
        </span>
        <div style={{ fontSize: 12, lineHeight: 1.5, color: C.textSecondary }}>
          {waterfallBannerCopy(sliderState)}
          <div style={{ marginTop: 4 }}>{WATERFALL_ASSUMPTION_NOTE}</div>
        </div>
      </div>

      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KPI
          label="LP Share"
          value={fmt(result.lpShare)}
          sub={`${(result.grossDist > 0 ? (result.lpShare / result.grossDist) * 100 : 0).toFixed(1)}% of total`}
          color={C.accent}
        />
        <KPI
          label="GP Share"
          value={fmt(result.gpShare)}
          sub={`${(result.grossDist > 0 ? (result.gpShare / result.grossDist) * 100 : 0).toFixed(1)}% of total`}
          color={C.green}
        />
        <KPI
          label="LP Multiple"
          value={`${equityBasis > 0 ? (result.lpShare / equityBasis).toFixed(2) : "0"}x`}
          sub={`IRR: ${lpIRR.toFixed(1)}%`}
        />
        <KPI
          label="GP Multiple"
          value={`${equityBasis > 0 ? (result.gpShare / (equityBasis * GP_EQUITY_SHARE_OF_BASIS)).toFixed(2) : "0"}x`}
          sub={`IRR: ${gpIRR.toFixed(1)}%`}
        />
      </div>

      <div
        style={{ display: "grid", gridTemplateColumns: "320px 1fr", gap: 20 }}
      >
        <SectionCard title="Scenario Inputs">
          <SliderInput
            label="Exit Proceeds"
            value={exitPrice}
            onChange={setExitPrice}
            min={20000000}
            max={300000000}
            step={5000000}
            format={fmt}
          />
          <SliderInput
            label="Equity Basis"
            value={equityBasis}
            onChange={setEquityBasis}
            min={5000000}
            max={100000000}
            step={1000000}
            format={fmt}
          />
          <SliderInput
            label="Preferred Return"
            value={prefRate}
            onChange={setPrefRate}
            min={4}
            max={12}
            step={0.5}
            format={(v) => `${v}%`}
          />
          <SliderInput
            label="GP Catch-Up"
            value={catchUpSplit}
            onChange={setCatchUpSplit}
            min={0}
            max={100}
            step={5}
            format={(v) => `${v}%`}
          />
          <SliderInput
            label="GP Promote"
            value={promoteRate}
            onChange={setPromoteRate}
            min={10}
            max={40}
            step={5}
            format={(v) => `${v}%`}
          />
          <SliderInput
            label="Hold Period"
            value={holdYears}
            onChange={setHoldYears}
            min={1}
            max={10}
            step={1}
            format={(v) => `${v} yrs`}
          />
        </SectionCard>

        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <SectionCard title="Waterfall Distribution">
            <ResponsiveContainer width="100%" height={250}>
              <BarChart data={waterfallBars}>
                <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tickFormatter={(v) => fmt(v)} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(v) => fmt(v)}
                  contentStyle={{
                    background: C.cardBg,
                    border: `1px solid ${C.border}`,
                    borderRadius: 8,
                    fontSize: 12,
                  }}
                  labelStyle={{ fontWeight: 600, color: C.textPrimary }}
                />
                <Legend />
                <Bar
                  dataKey="lp"
                  name="LP"
                  fill={C.accent}
                  stackId="a"
                  radius={[0, 0, 0, 0]}
                />
                <Bar
                  dataKey="gp"
                  name="GP"
                  fill={C.green}
                  stackId="a"
                  radius={[4, 4, 0, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </SectionCard>

          <SectionCard title="Sensitivity Analysis — Exit Price × Hold Period">
            {(() => {
              const exitPrices = [
                exitPrice * 0.8,
                exitPrice * 0.9,
                exitPrice,
                exitPrice * 1.1,
                exitPrice * 1.2,
              ];
              const holdPeriods = [3, 5, 7, 10];
              const matrix = exitPrices.map((ep) => {
                const r = computeWaterfall(
                  ep,
                  equityBasis,
                  prefRate / 100,
                  catchUpSplit / 100,
                  [{ threshold: Infinity, gpSplit: promoteRate / 100 }],
                );
                return holdPeriods.map((hp) => {
                  const irr =
                    hp > 0 && r.lpShare > 0 && equityBasis > 0
                      ? (Math.pow(r.lpShare / equityBasis, 1 / hp) - 1) * 100
                      : 0;
                  const em = equityBasis > 0 ? r.lpShare / equityBasis : 0;
                  return { irr: irr.toFixed(1), em: em.toFixed(2) };
                });
              });
              return (
                <div style={{ overflowX: "auto" }}>
                  <div
                    style={{
                      fontSize: 11,
                      fontWeight: 600,
                      color: C.textSecondary,
                      marginBottom: 8,
                    }}
                  >
                    LP IRR by Exit Price × Hold Period
                  </div>
                  <table
                    style={{
                      width: "100%",
                      borderCollapse: "collapse",
                      fontSize: 12,
                    }}
                  >
                    <thead>
                      <tr>
                        <th
                          style={{
                            padding: "8px 10px",
                            textAlign: "left",
                            borderBottom: `2px solid ${C.border}`,
                            fontSize: 11,
                            color: C.textSecondary,
                            fontWeight: 600,
                          }}
                        >
                          Exit Price ↓ / Hold →
                        </th>
                        {holdPeriods.map((hp) => (
                          <th
                            key={hp}
                            style={{
                              padding: "8px 10px",
                              textAlign: "center",
                              borderBottom: `2px solid ${C.border}`,
                              fontSize: 11,
                              color: C.textSecondary,
                              fontWeight: 600,
                            }}
                          >
                            {hp} Years
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {exitPrices.map((ep, ei) => (
                        <tr
                          key={ei}
                          style={{
                            background:
                              ep === exitPrice
                                ? `${alpha(C.gold, 6.3)}`
                                : "transparent",
                          }}
                        >
                          <td
                            style={{
                              padding: "8px 10px",
                              borderBottom: `1px solid ${C.border}`,
                              fontWeight: ep === exitPrice ? 700 : 500,
                              color: C.textPrimary,
                            }}
                          >
                            {fmt(ep)} {ep === exitPrice ? " ◆" : ""}
                          </td>
                          {matrix[ei].map((cell, ci) => {
                            const irr = parseFloat(cell.irr);
                            const irrColor =
                              irr >= 20
                                ? C.green
                                : irr >= 12
                                  ? C.accent
                                  : irr >= 8
                                    ? C.gold
                                    : C.red;
                            return (
                              <td
                                key={ci}
                                style={{
                                  padding: "8px 10px",
                                  textAlign: "center",
                                  borderBottom: `1px solid ${C.border}`,
                                  fontWeight: 600,
                                  color: irrColor,
                                  background:
                                    ep === exitPrice &&
                                    holdPeriods[ci] === holdYears
                                      ? `${alpha(C.gold, 12.5)}`
                                      : "transparent",
                                }}
                              >
                                {cell.irr}%{" "}
                                <span
                                  style={{
                                    fontSize: 10,
                                    opacity: 0.6,
                                    fontWeight: 400,
                                  }}
                                >
                                  ({cell.em}x)
                                </span>
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <div
                    style={{
                      display: "flex",
                      gap: 16,
                      marginTop: 10,
                      fontSize: 10,
                      color: C.textSecondary,
                    }}
                  >
                    <span>
                      <span style={{ color: C.green, fontWeight: 700 }}>■</span>{" "}
                      IRR ≥ 20%
                    </span>
                    <span>
                      <span style={{ color: C.accent, fontWeight: 700 }}>
                        ■
                      </span>{" "}
                      12-20%
                    </span>
                    <span>
                      <span style={{ color: C.gold, fontWeight: 700 }}>■</span>{" "}
                      8-12%
                    </span>
                    <span>
                      <span style={{ color: C.red, fontWeight: 700 }}>■</span>{" "}
                      {"<"} 8%
                    </span>
                    <span>◆ = Base Case</span>
                  </div>
                </div>
              );
            })()}
          </SectionCard>
        </div>
      </div>
    </div>
  );
};

const ESGDashboard = ({ filterProperty }) => {
  const filteredESG = filterProperty
    ? ESG_DATA.filter((d) => d.property === filterProperty)
    : ESG_DATA;
  const avgEnergyStar = meanOrDash(
    filteredESG,
    (d) => d.energyStar,
    (n) => n.toFixed(0),
  );
  const avgCarbon = meanOrDash(
    filteredESG,
    (d) => d.carbonIntensity,
    (n) => n.toFixed(1),
  );
  const certCount = filteredESG.filter((d) => d.greenCert).length;
  const avgWasteDiv = meanOrDash(
    filteredESG,
    (d) => d.wasteDiv,
    (n) => n.toFixed(0),
  );

  const esgScores = filteredESG.map((d) => ({
    name:
      d.property.length > 18 ? d.property.substring(0, 16) + "…" : d.property,
    Environmental: d.envScore,
    Social: d.socialScore,
    Governance: d.govScore,
  }));

  const carbonData = filteredESG.map((d) => ({
    name:
      d.property.length > 18 ? d.property.substring(0, 16) + "…" : d.property,
    intensity: d.carbonIntensity,
    yoy: d.yoyCarbon,
  }));

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KPI
          label="Avg Energy Star"
          value={avgEnergyStar}
          sub="Portfolio-wide"
          color={
            avgEnergyStar === EMPTY_METRIC
              ? C.textSecondary
              : Number(avgEnergyStar) >= 75
                ? C.green
                : C.amber
          }
        />
        <KPI
          label="Avg Carbon Intensity"
          value={
            avgCarbon === EMPTY_METRIC ? EMPTY_METRIC : `${avgCarbon} kgCO₂/SF`
          }
          sub="Scope 1 + 2"
        />
        <KPI
          label="Green Certifications"
          value={
            filteredESG.length
              ? `${certCount} of ${filteredESG.length}`
              : EMPTY_METRIC
          }
          sub="LEED / Energy Star"
          color={filteredESG.length ? C.green : C.textSecondary}
        />
        <KPI
          label="Avg Waste Diversion"
          value={
            avgWasteDiv === EMPTY_METRIC ? EMPTY_METRIC : `${avgWasteDiv}%`
          }
          sub="Recycling + composting"
        />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <SectionCard title="ESG Scores by Property">
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={esgScores} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
              <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 11 }} />
              <YAxis
                dataKey="name"
                type="category"
                tick={{ fontSize: 10 }}
                width={130}
              />
              <Tooltip />
              <Legend />
              <Bar dataKey="Environmental" fill="var(--ds-success-dot)" />
              <Bar dataKey="Social" fill="var(--ds-info-text)" />
              <Bar dataKey="Governance" fill="var(--ds-ai)" />
            </BarChart>
          </ResponsiveContainer>
        </SectionCard>

        <SectionCard title="Carbon Intensity by Property">
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={carbonData} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
              <XAxis type="number" tick={{ fontSize: 11 }} />
              <YAxis
                dataKey="name"
                type="category"
                tick={{ fontSize: 10 }}
                width={130}
              />
              <Tooltip
                formatter={(v, name) =>
                  name === "yoy"
                    ? `${v.toFixed(1)}%`
                    : `${v.toFixed(1)} kgCO₂/SF`
                }
                contentStyle={{
                  background: C.cardBg,
                  border: `1px solid ${C.border}`,
                  borderRadius: 8,
                  fontSize: 12,
                }}
                labelStyle={{ fontWeight: 600, color: C.textPrimary }}
              />
              <Bar
                dataKey="intensity"
                name="kgCO₂/SF"
                fill={C.amber}
                radius={[0, 4, 4, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </SectionCard>
      </div>

      <SectionCard title="Property Sustainability Scorecard">
        <MiniTable
          columns={[
            { key: "property", label: "Property" },
            { key: "energyStar", label: "Energy Star" },
            { key: "greenCert", label: "Certification" },
            {
              key: "energyUse",
              label: "Energy (kBTU/SF)",
              format: (v) => v.toFixed(1),
            },
            {
              key: "carbonIntensity",
              label: "Carbon (kgCO₂/SF)",
              format: (v) => v.toFixed(1),
            },
            { key: "wasteDiv", label: "Waste Div %", format: (v) => `${v}%` },
            {
              key: "renewablePct",
              label: "Renewable %",
              format: (v) => `${v}%`,
            },
            {
              key: "yoyEnergy",
              label: "Energy YoY",
              format: (v) => `${v > 0 ? "+" : ""}${v.toFixed(1)}%`,
            },
            {
              key: "yoyCarbon",
              label: "Carbon YoY",
              format: (v) => `${v > 0 ? "+" : ""}${v.toFixed(1)}%`,
            },
          ]}
          data={filteredESG}
        />
      </SectionCard>
    </div>
  );
};

const CapitalMarketsMonitor = ({ filterProperty }) => {
  if (
    !CAPITAL_MARKETS_RATES.length ||
    !CAP_RATE_TRENDS.length ||
    !CRE_TRANSACTION_VOLUME.length
  ) {
    return React.createElement(FixtureEmptyState, {
      title: "Rate and cap-rate history not connected",
      body: "Treasury and SOFR benchmarks, CMBS and life-co spreads, cap-rate trends and CRE transaction volume come from a market-data subscription that is not yet wired. Deal-level rate assumptions you can act on today live in each property's Underwriting Model (Quarterly Reporting → Underwriting Model), and executed loan terms in Capital Stack → Debt.",
    });
  }
  const latest = CAPITAL_MARKETS_RATES[CAPITAL_MARKETS_RATES.length - 1];
  const prior =
    CAPITAL_MARKETS_RATES.length >= 2
      ? CAPITAL_MARKETS_RATES[CAPITAL_MARKETS_RATES.length - 2]
      : null;
  const treasuryMoM = prior
    ? `${((latest.treasury10Y - prior.treasury10Y) * 100).toFixed(0)} bps MoM`
    : `${EMPTY} MoM — one month of history`;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <KPI
          label="10Y Treasury"
          value={`${latest.treasury10Y}%`}
          sub={treasuryMoM}
          trend={
            prior ? (latest.treasury10Y < prior.treasury10Y ? 1 : -1) : null
          }
        />
        <KPI
          label="SOFR"
          value={`${latest.sofr}%`}
          sub="Current overnight rate"
        />
        <KPI
          label="5Y CMBS Spread"
          value={`${latest.cmbs5Y}%`}
          sub={`${latest.lifeCoSpread} bps life co spread`}
        />
        <KPI
          label="CRE Volume (Q1 '26)"
          value={`$${CRE_TRANSACTION_VOLUME[CRE_TRANSACTION_VOLUME.length - 1].volume}B`}
          sub={`${CRE_TRANSACTION_VOLUME[CRE_TRANSACTION_VOLUME.length - 1].deals} deals`}
          color={C.green}
        />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <SectionCard title="Interest Rate Trends">
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={CAPITAL_MARKETS_RATES}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
              <XAxis dataKey="month" tick={{ fontSize: 10 }} />
              <YAxis tick={{ fontSize: 11 }} domain={["auto", "auto"]} />
              <Tooltip />
              <Legend />
              <Line
                type="monotone"
                dataKey="treasury10Y"
                name="10Y Treasury"
                stroke="var(--ds-info-text)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
              <Line
                type="monotone"
                dataKey="sofr"
                name="SOFR"
                stroke="var(--ds-success-dot)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
              <Line
                type="monotone"
                dataKey="cmbs5Y"
                name="5Y CMBS"
                stroke="var(--ds-warning-dot)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </SectionCard>

        <SectionCard title="Cap Rate Trends by Sector">
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={CAP_RATE_TRENDS}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
              <XAxis dataKey="quarter" tick={{ fontSize: 10 }} />
              <YAxis tick={{ fontSize: 11 }} domain={["auto", "auto"]} />
              <Tooltip />
              <Legend />
              <Line
                type="monotone"
                dataKey="office"
                name="Office"
                stroke="var(--ds-danger-dot)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
              <Line
                type="monotone"
                dataKey="industrial"
                name="Industrial"
                stroke="var(--ds-success-dot)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
              <Line
                type="monotone"
                dataKey="multifamily"
                name="Multifamily"
                stroke="var(--ds-info-text)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
              <Line
                type="monotone"
                dataKey="retail"
                name="Retail"
                stroke="var(--ds-warning-dot)"
                strokeWidth={2}
                dot={{ r: 3 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </SectionCard>
      </div>

      <SectionCard title="CRE Transaction Volume">
        <ResponsiveContainer width="100%" height={240}>
          <ComposedChart data={CRE_TRANSACTION_VOLUME}>
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
            <XAxis dataKey="quarter" tick={{ fontSize: 11 }} />
            <YAxis yAxisId="left" tick={{ fontSize: 11 }} />
            <YAxis
              yAxisId="right"
              orientation="right"
              tick={{ fontSize: 11 }}
            />
            <Tooltip />
            <Legend />
            <Bar
              yAxisId="left"
              dataKey="volume"
              name="Volume ($B)"
              fill={C.accent}
              radius={[4, 4, 0, 0]}
            />
            <Line
              yAxisId="right"
              type="monotone"
              dataKey="deals"
              name="# Deals"
              stroke={C.green}
              strokeWidth={2}
              dot={{ r: 4 }}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </SectionCard>

      <SectionCard title="Lending Spreads (bps over Treasury)">
        <MiniTable
          headers={[
            "Month",
            "10Y Treasury",
            "Life Co",
            "Bank",
            "Agency",
            "CMBS 5Y",
          ]}
          rows={CAPITAL_MARKETS_RATES.map((r) => [
            r.month,
            `${r.treasury10Y}%`,
            `${r.lifeCoSpread} bps`,
            `${r.bankSpread} bps`,
            `${r.agencySpread} bps`,
            `${r.cmbs5Y}%`,
          ])}
        />
      </SectionCard>
    </div>
  );
};

