const ConstructionDrawPage = ({ filterProperty }) => {
  const data = CONSTRUCTION_DRAWS;
  const defaultProject = filterProperty
    ? data.findIndex((p) => p.property === filterProperty)
    : 0;
  const [selectedProject, setSelectedProject] = useState(defaultProject);
  const project = data[selectedProject];

  if (
    selectConstructionDrawState(project) ===
    CONSTRUCTION_DRAW_GUARD_STATES.INITIALIZING
  ) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        <SectionCard title="Construction Draws">
          <div
            style={{
              padding: 32,
              textAlign: "center",
              color: C.textSecondary,
              fontSize: 13,
              lineHeight: 1.6,
            }}
          >
            No construction draws are available for this property yet. Draws
            appear here once the project's loan-commitment schedule and lender /
            inspector approvals have been recorded.
          </div>
        </SectionCard>
      </div>
    );
  }

  const projectDraws = safeProjectDraws(project);
  const totalDrawn = projectDraws.reduce(
    (sum, d) => sum + (d.lenderApproval && d.inspectorApproval ? d.amount : 0),
    0,
  );
  const totalRetainage = projectDraws.reduce((sum, d) => sum + d.retainage, 0);
  const remainingBudget = project.totalBudget - totalDrawn;
  const drawnPct = (
    project.loanCommitment > 0 ? (totalDrawn / project.loanCommitment) * 100 : 0
  ).toFixed(1);

  const drawRows = projectDraws.map((d) => [
    `Draw ${d.drawNumber}`,
    d.date,
    fmt(d.amount),
    d.category,
    d.inspectionDate,
    <Badge
      text={d.inspectorApproval ? "Approved" : "Pending"}
      color={d.inspectorApproval ? "green" : "amber"}
    />,
    <Badge
      text={d.lenderApproval ? "Approved" : "Pending"}
      color={d.lenderApproval ? "green" : "amber"}
    />,
    fmt(d.retainage),
    fmt(d.netDisbursement),
  ]);

  const cumulativeData = projectDraws.map((d) => ({
    draw: `Draw ${d.drawNumber}`,
    Cumulative: d.cumulativeDrawn,
    Remaining: d.remainingCommitment,
  }));

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {!filterProperty && (
        <SectionCard title="Project Selector">
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {data.map((p, i) => (
              <button
                key={i}
                onClick={() => setSelectedProject(i)}
                style={{
                  padding: "6px 14px",
                  borderRadius: 6,
                  border: `1px solid ${C.border}`,
                  background: selectedProject === i ? C.accent : C.subtleBg,
                  color: selectedProject === i ? "white" : C.textPrimary,
                  cursor: "pointer",
                  fontWeight: 600,
                  fontSize: 12,
                }}
              >
                {p.project}
              </button>
            ))}
          </div>
        </SectionCard>
      )}

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
        <KPI
          label="Total Budget"
          value={fmt(project.totalBudget)}
          color={C.navy}
        />
        <KPI label="Total Drawn" value={fmt(totalDrawn)} color={C.green} />
        <KPI
          label="Retainage Withheld"
          value={fmt(totalRetainage)}
          color={C.amber}
        />
        <KPI
          label="Completion %"
          value={`${project.completionPct}%`}
          color={C.accent}
        />
      </div>

      <SectionCard title="Project Overview">
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
            gap: 16,
          }}
        >
          <div>
            <div
              style={{
                fontSize: 11,
                color: C.textSecondary,
                fontWeight: 600,
                textTransform: "uppercase",
                marginBottom: 4,
              }}
            >
              Loan Commitment
            </div>
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                color: C.textPrimary,
                marginBottom: 8,
              }}
            >
              {fmt(project.loanCommitment)}
            </div>
          </div>
          <div>
            <div
              style={{
                fontSize: 11,
                color: C.textSecondary,
                fontWeight: 600,
                textTransform: "uppercase",
                marginBottom: 4,
              }}
            >
              Drawn %
            </div>
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                color: C.textPrimary,
                marginBottom: 8,
              }}
            >
              {drawnPct}%
            </div>
          </div>
          <div>
            <div
              style={{
                fontSize: 11,
                color: C.textSecondary,
                fontWeight: 600,
                textTransform: "uppercase",
                marginBottom: 4,
              }}
            >
              Retainage Balance
            </div>
            <div
              style={{
                fontSize: 14,
                fontWeight: 600,
                color: C.textPrimary,
                marginBottom: 8,
              }}
            >
              {fmt(project.retainageBalance)}
            </div>
          </div>
        </div>
      </SectionCard>

      <SectionCard title="Draw Progress">
        <div style={{ marginBottom: 12 }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginBottom: 8,
            }}
          >
            <span
              style={{ fontSize: 12, color: C.textPrimary, fontWeight: 600 }}
            >
              Drawn: {fmt(totalDrawn)}
            </span>
            <span style={{ fontSize: 12, color: C.textSecondary }}>
              Commitment: {fmt(project.loanCommitment)}
            </span>
          </div>
          <div
            style={{
              background: C.subtleBg,
              borderRadius: 6,
              height: 24,
              position: "relative",
            }}
          >
            <div
              style={{
                height: "100%",
                background: C.green,
                borderRadius: 6,
                width: `${project.loanCommitment > 0 ? (totalDrawn / project.loanCommitment) * 100 : 0}%`,
              }}
            />
          </div>
        </div>
      </SectionCard>

      <SectionCard title="Cumulative Draw Chart">
        <ResponsiveContainer width="100%" height={300}>
          <LineChart
            data={cumulativeData}
            margin={{ top: 20, right: 30, left: 0, bottom: 20 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
            <XAxis
              dataKey="draw"
              stroke={C.textSecondary}
              style={{ fontSize: 11 }}
            />
            <YAxis stroke={C.textSecondary} style={{ fontSize: 11 }} />
            <Tooltip
              contentStyle={{
                background: C.cardBg,
                border: `1px solid ${C.border}`,
                borderRadius: 6,
              }}
              formatter={(value) => fmt(value)}
            />
            <Legend />
            <Line
              type="monotone"
              dataKey="Cumulative"
              stroke={C.green}
              strokeWidth={2}
            />
            <Line
              type="monotone"
              dataKey="Remaining"
              stroke={C.red}
              strokeWidth={2}
            />
          </LineChart>
        </ResponsiveContainer>
      </SectionCard>

      <SectionCard title="Draw Schedule & Approvals">
        <MiniTable
          headers={[
            "Draw",
            "Date",
            "Amount",
            "Category",
            "Inspection",
            "Inspector",
            "Lender",
            "Retainage",
            "Net Disburse",
          ]}
          rows={drawRows}
        />
      </SectionCard>
    </div>
  );
};

const ChartOfAccountsPage = () => {
  const data = CHART_OF_ACCOUNTS;
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedType, setSelectedType] = useState("All");

  const accountTypes = ["All", ...new Set(data.map((a) => a.type))];

  const filtered = data.filter((a) => {
    const matchesType = selectedType === "All" || a.type === selectedType;
    const matchesSearch =
      searchQuery === "" ||
      a.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
      a.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      a.category.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesType && matchesSearch;
  });

  const grouped = filtered.reduce((acc, account) => {
    const typeGroup = acc.find((g) => g.type === account.type);
    if (!typeGroup) {
      acc.push({
        type: account.type,
        categories: [{ category: account.category, accounts: [account] }],
      });
    } else {
      const catGroup = typeGroup.categories.find(
        (c) => c.category === account.category,
      );
      if (!catGroup) {
        typeGroup.categories.push({
          category: account.category,
          accounts: [account],
        });
      } else {
        catGroup.accounts.push(account);
      }
    }
    return acc;
  }, []);

  const typeColor = (type) =>
    type === "Asset"
      ? "blue"
      : type === "Liability"
        ? "red"
        : type === "Equity"
          ? "green"
          : type === "Revenue"
            ? "emerald"
            : "purple";

  const accountStats = accountTypes.slice(1).map((type) => ({
    type,
    count: data.filter((a) => a.type === type).length,
  }));

  const accountRows = grouped.flatMap((group) => [
    [group.type, "", ""],
    ...group.categories.flatMap((cat) => [
      [`  ${cat.category}`, "", ""],
      ...cat.accounts.map((acc) => [`    ${acc.code}`, acc.name, acc.type]),
    ]),
  ]);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <SectionCard title="Account Statistics">
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
          {accountStats.map((stat, i) => (
            <KPI
              key={i}
              label={stat.type}
              value={stat.count.toString()}
              color={C.accent}
            />
          ))}
          <KPI
            label="Total Accounts"
            value={data.length.toString()}
            color={C.navy}
          />
        </div>
      </SectionCard>

      <SectionCard title="Search & Filter">
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          <div>
            <input
              type="text"
              placeholder="Search by code, name, or category..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 14px",
                borderRadius: 6,
                border: `1px solid ${C.border}`,
                background: C.white,
                color: C.textPrimary,
                fontSize: 13,
                outline: "none",
              }}
            />
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {accountTypes.map((type) => (
              <button
                key={type}
                onClick={() => setSelectedType(type)}
                style={{
                  padding: "6px 14px",
                  borderRadius: 6,
                  border: `1px solid ${C.border}`,
                  background: selectedType === type ? C.accent : C.subtleBg,
                  color: selectedType === type ? "white" : C.textPrimary,
                  cursor: "pointer",
                  fontWeight: 600,
                  fontSize: 12,
                }}
              >
                {type}
              </button>
            ))}
          </div>
        </div>
      </SectionCard>

      <SectionCard title="Chart of Accounts">
        <StatementStickyGrid
          theme={{ border: C.border, subtle: C.subtleBg }}
          maxHeight={560}
          style={{ background: C.cardBg }}
        >
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              fontSize: 12.5,
              fontFeatureSettings: "'tnum'",
            }}
          >
            <thead data-statement-header="">
              <tr>
                {["Code", "Account Name", "Type"].map((label) => (
                  <th
                    key={label}
                    style={{
                      textAlign: "left",
                      padding: "8px 12px",
                      color: C.textSecondary,
                      fontWeight: 600,
                      fontSize: 10.5,
                      textTransform: "uppercase",
                      letterSpacing: 0.6,
                      ...statementHeaderCellStyle(C, { row: 0 }),
                    }}
                  >
                    {label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {grouped.map((group, gi) => (
                <React.Fragment key={gi}>
                  <tr
                    data-statement-heading={`coa-type-${group.type}`}
                    data-statement-depth={0}
                    data-statement-label={`${group.type} (${group.categories.reduce((sum, c) => sum + c.accounts.length, 0)})`}
                    style={{
                      background: C.subtleBg,
                      borderBottom: `1px solid ${C.border}`,
                    }}
                  >
                    <td
                      colSpan={3}
                      style={{
                        padding: "10px 12px",
                        color: C.textPrimary,
                        fontWeight: 700,
                        fontSize: 12,
                      }}
                    >
                      <Badge text={group.type} color={typeColor(group.type)} />{" "}
                      {group.type} (
                      {group.categories.reduce(
                        (sum, c) => sum + c.accounts.length,
                        0,
                      )}
                      )
                    </td>
                  </tr>
                  {group.categories.map((cat, ci) => (
                    <React.Fragment key={ci}>
                      <tr
                        data-statement-heading={`coa-cat-${group.type}-${cat.category}`}
                        data-statement-depth={1}
                        data-statement-label={cat.category}
                        style={{
                          borderBottom: `1px solid ${C.border}`,
                          background: C.light,
                        }}
                      >
                        <td
                          colSpan={3}
                          style={{
                            padding: "8px 12px",
                            color: C.textSecondary,
                            fontWeight: 600,
                            fontSize: 11,
                            paddingLeft: 24,
                          }}
                        >
                          {cat.category}
                        </td>
                      </tr>
                      {cat.accounts.map((acc, ai) => (
                        <tr
                          key={ai}
                          style={{ borderBottom: `1px solid ${C.border}` }}
                        >
                          <td
                            style={{
                              padding: "8px 12px",
                              color: C.textPrimary,
                              fontWeight: 600,
                              paddingLeft: 36,
                            }}
                          >
                            {acc.code}
                          </td>
                          <td
                            style={{
                              padding: "8px 12px",
                              color: C.textPrimary,
                              fontWeight: 400,
                            }}
                          >
                            {acc.name}
                          </td>
                          <td
                            style={{
                              padding: "8px 12px",
                              color: C.textSecondary,
                              fontWeight: 400,
                            }}
                          >
                            {acc.type}
                          </td>
                        </tr>
                      ))}
                    </React.Fragment>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </StatementStickyGrid>
      </SectionCard>
    </div>
  );
};

