const PipelineContent = ({
  selectedStage,
  setSelectedStage,
  selectedType,
  setSelectedType,
  selectedPriority,
  setSelectedPriority,
  selectedPerson,
  setSelectedPerson,
}) => {
  const stages = [
    "Sourced",
    "Initial Screen",
    "LOI Submitted",
    "Under DD",
    "IC Approval",
    "Closing",
    "Closed",
  ];
  const types = ["Office", "Industrial", "Multifamily", "Retail", "Mixed-Use"];
  const priorities = ["High", "Medium", "Low"];
  const people = [...new Set(DEAL_PIPELINE_CRM.map((d) => d.assignedTo))];

  const filtered = DEAL_PIPELINE_CRM.filter((d) => {
    if (selectedStage && d.stage !== selectedStage) return false;
    if (selectedType && d.type !== selectedType) return false;
    if (selectedPriority && d.priority !== selectedPriority) return false;
    if (selectedPerson && d.assignedTo !== selectedPerson) return false;
    return true;
  });

  const totalPipeline = filtered.reduce((sum, d) => sum + d.askingPrice, 0);
  const activeDealCount = filtered.filter(
    (d) => !["Closed"].includes(d.stage),
  ).length;
  const avgDaysToClose = Math.round(
    filtered
      .filter((d) => d.stage === "Closed")
      .reduce((sum, d) => sum + d.daysInStage, 0) /
      Math.max(filtered.filter((d) => d.stage === "Closed").length, 1),
  );
  const winRate =
    filtered.length > 0
      ? Math.round(
          (filtered.filter((d) => d.stage === "Closed").length /
            filtered.length) *
            100,
        )
      : 0;

  const stageData = stages.map((stage) => ({
    stage: stage.split(" ")[0],
    count: DEAL_PIPELINE_CRM.filter((d) => d.stage === stage).length,
    value: DEAL_PIPELINE_CRM.filter((d) => d.stage === stage).reduce(
      (sum, d) => sum + d.askingPrice,
      0,
    ),
  }));

  const getTypeColor = (type) => {
    const colors = {
      Office: "var(--ds-accent)",
      Industrial: "var(--ds-success-dot)",
      Multifamily: "var(--ds-warning-dot)",
      Retail: "var(--ds-danger-dot)",
      "Mixed-Use": "var(--ds-ai)",
    };
    return colors[type] || "var(--ds-text-secondary)";
  };

  return (
    <div style={{ padding: "24px", backgroundColor: C.bg }}>
      <div style={{ marginBottom: "24px" }}>
        <h1
          style={{
            fontSize: "28px",
            fontWeight: "600",
            color: C.textPrimary,
            marginBottom: "4px",
          }}
        >
          Deal Pipeline
        </h1>
        <p style={{ color: C.textSecondary, fontSize: "14px" }}>
          Manage and track acquisitions across all stages
        </p>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "12px",
          marginBottom: "24px",
        }}
      >
        <KPI
          label="Total Pipeline Value"
          value={fmt(totalPipeline)}
          sub={`${filtered.length} deals`}
        />
        <KPI
          label="Active Deals"
          value={activeDealCount}
          sub={shareOrDash(
            activeDealCount,
            filtered.length,
            (p) => `${Math.round(p)}% of pipeline`,
          )}
        />
        <KPI
          label="Avg Days to Close"
          value={avgDaysToClose}
          sub="Last 12 months"
        />
        <KPI
          label="Win Rate"
          value={`${winRate}%`}
          sub={`${filtered.filter((d) => d.stage === "Closed").length} closed`}
        />
      </div>

      <SectionCard title="Pipeline Funnel" style={{ marginBottom: "24px" }}>
        <ResponsiveContainer width="100%" height={250}>
          <BarChart data={stageData}>
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
            <XAxis dataKey="stage" stroke={C.textSecondary} />
            <YAxis stroke={C.textSecondary} />
            <Tooltip
              contentStyle={{
                backgroundColor: C.subtleBg,
                border: `1px solid ${C.border}`,
              }}
            />
            <Bar dataKey="count" fill="var(--ds-accent)" name="Deal Count" />
          </BarChart>
        </ResponsiveContainer>
      </SectionCard>

      <SectionCard title="Stage Filters" style={{ marginBottom: "24px" }}>
        <div
          style={{
            display: "flex",
            gap: "8px",
            flexWrap: "wrap",
            marginBottom: "12px",
          }}
        >
          {stages.map((stage) => (
            <button
              key={stage}
              onClick={() =>
                setSelectedStage(selectedStage === stage ? null : stage)
              }
              style={{
                padding: "8px 12px",
                borderRadius: "6px",
                border: "none",
                cursor: "pointer",
                backgroundColor:
                  selectedStage === stage ? "var(--ds-accent)" : C.subtleBg,
                color: selectedStage === stage ? "white" : C.textPrimary,
                fontSize: "13px",
                fontWeight: "500",
              }}
            >
              {stage}
            </button>
          ))}
        </div>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: "12px",
          }}
        >
          <div>
            <label
              style={{
                display: "block",
                fontSize: "12px",
                color: C.textSecondary,
                marginBottom: "6px",
              }}
            >
              Type
            </label>
            <Select
              value={selectedType || ""}
              onChange={(e) => setSelectedType(e.target.value || null)}
              fullWidth
              size="md"
              style={{
                padding: "8px",
                borderRadius: "4px",
                background: C.subtleBg,
              }}
            >
              <option value="">All Types</option>
              {types.map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </Select>
          </div>
          <div>
            <label
              style={{
                display: "block",
                fontSize: "12px",
                color: C.textSecondary,
                marginBottom: "6px",
              }}
            >
              Priority
            </label>
            <Select
              value={selectedPriority || ""}
              onChange={(e) => setSelectedPriority(e.target.value || null)}
              fullWidth
              size="md"
              style={{
                padding: "8px",
                borderRadius: "4px",
                background: C.subtleBg,
              }}
            >
              <option value="">All Priorities</option>
              {priorities.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </Select>
          </div>
          <div>
            <label
              style={{
                display: "block",
                fontSize: "12px",
                color: C.textSecondary,
                marginBottom: "6px",
              }}
            >
              Assigned To
            </label>
            <Select
              value={selectedPerson || ""}
              onChange={(e) => setSelectedPerson(e.target.value || null)}
              fullWidth
              size="md"
              style={{
                padding: "8px",
                borderRadius: "4px",
                background: C.subtleBg,
              }}
            >
              <option value="">All People</option>
              {people.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </Select>
          </div>
          <div style={{ display: "flex", alignItems: "flex-end" }}>
            <button
              onClick={() => {
                setSelectedStage(null);
                setSelectedType(null);
                setSelectedPriority(null);
                setSelectedPerson(null);
              }}
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: `1px solid ${C.border}`,
                backgroundColor: C.subtleBg,
                color: C.textPrimary,
                cursor: "pointer",
                fontSize: "13px",
              }}
            >
              Clear Filters
            </button>
          </div>
        </div>
      </SectionCard>

      <SectionCard title="Deal Summary" style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
          }}
        >
          <thead>
            <tr style={{ borderBottom: `1px solid ${C.border}` }}>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Property
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Type
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Market
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Asking Price
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Target IRR
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Stage
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Days
              </th>
              <th
                style={{
                  padding: "12px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Assigned
              </th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((deal, idx) => (
              <tr
                key={deal.id}
                style={{
                  borderBottom: `1px solid ${C.border}`,
                  backgroundColor: idx % 2 === 0 ? C.cardBg : C.tableBgAlt,
                }}
              >
                <td
                  style={{
                    padding: "12px",
                    color: C.textPrimary,
                    fontWeight: "500",
                  }}
                >
                  {deal.name}
                </td>
                <td style={{ padding: "12px" }}>
                  <Badge
                    text={deal.type}
                    color={
                      getTypeColor(deal.type).toLowerCase().includes("3b82")
                        ? "blue"
                        : getTypeColor(deal.type).toLowerCase().includes("10b9")
                          ? "green"
                          : getTypeColor(deal.type)
                                .toLowerCase()
                                .includes("f59e")
                            ? "amber"
                            : getTypeColor(deal.type)
                                  .toLowerCase()
                                  .includes("ef44")
                              ? "red"
                              : "purple"
                    }
                  />
                </td>
                <td style={{ padding: "12px", color: C.textSecondary }}>
                  {deal.market}
                </td>
                <td
                  style={{
                    padding: "12px",
                    color: C.textPrimary,
                    fontWeight: "500",
                  }}
                >
                  {fmt(deal.askingPrice)}
                </td>
                <td
                  style={{
                    padding: "12px",
                    color: C.textPrimary,
                    fontWeight: "500",
                  }}
                >
                  {deal.targetReturn.toFixed(1)}%
                </td>
                <td style={{ padding: "12px" }}>
                  <Badge text={deal.stage} color="gray" />
                </td>
                <td style={{ padding: "12px", color: C.textSecondary }}>
                  {deal.daysInStage}d
                </td>
                <td style={{ padding: "12px", color: C.textSecondary }}>
                  {deal.assignedTo}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </SectionCard>
    </div>
  );
};

const UnifiedPipelineHub = ({ defaultTab = "pipeline" }) => {
  const [activeTab, setActiveTab] = useState(defaultTab);
  const [selectedStage, setSelectedStage] = useState(null);
  const [selectedType, setSelectedType] = useState(null);
  const [selectedPriority, setSelectedPriority] = useState(null);
  const [selectedPerson, setSelectedPerson] = useState(null);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div
        style={{
          display: "flex",
          gap: 8,
          borderBottom: `1px solid ${C.border}`,
          paddingBottom: 0,
        }}
      >
        <button
          onClick={() => setActiveTab("pipeline")}
          style={{
            padding: "12px 20px",
            borderBottom:
              activeTab === "pipeline"
                ? `3px solid ${C.accent}`
                : "3px solid transparent",
            background: "none",
            border: "none",
            cursor: "pointer",
            color: activeTab === "pipeline" ? C.accent : C.textSecondary,
            fontWeight: activeTab === "pipeline" ? 600 : 500,
            fontSize: 13,
            transition: "all 0.2s",
          }}
        >
          Pipeline CRM
        </button>
        <button
          onClick={() => setActiveTab("analytics")}
          style={{
            padding: "12px 20px",
            borderBottom:
              activeTab === "analytics"
                ? `3px solid ${C.accent}`
                : "3px solid transparent",
            background: "none",
            border: "none",
            cursor: "pointer",
            color: activeTab === "analytics" ? C.accent : C.textSecondary,
            fontWeight: activeTab === "analytics" ? 600 : 500,
            fontSize: 13,
            transition: "all 0.2s",
          }}
        >
          Analytics
        </button>
      </div>

      {activeTab === "pipeline" && (
        <PipelineContent
          selectedStage={selectedStage}
          setSelectedStage={setSelectedStage}
          selectedType={selectedType}
          setSelectedType={setSelectedType}
          selectedPriority={selectedPriority}
          setSelectedPriority={setSelectedPriority}
          selectedPerson={selectedPerson}
          setSelectedPerson={setSelectedPerson}
        />
      )}

      {activeTab === "analytics" && <PipelineAnalyticsPageContent />}
    </div>
  );
};

const DealPipelineCRM = () => <UnifiedPipelineHub defaultTab="pipeline" />;

