const InvestorCRM = () => {
  const [selectedStatus, setSelectedStatus] = useState(null);
  const [selectedType, setSelectedType] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");

  const filtered = INVESTOR_CRM_DATA.filter((inv) => {
    if (selectedStatus && inv.status !== selectedStatus) return false;
    if (selectedType && inv.type !== selectedType) return false;
    if (
      searchTerm &&
      !inv.name.toLowerCase().includes(searchTerm.toLowerCase())
    )
      return false;
    return true;
  });

  const activeInvestors = INVESTOR_CRM_DATA.filter(
    (i) => i.status === "Active",
  ).length;
  const totalAUM = INVESTOR_CRM_DATA.reduce(
    (sum, i) => sum + i.totalInvested,
    0,
  );
  const npsRespondents = INVESTOR_CRM_DATA.filter((i) => i.nps);
  const avgNPS = meanOrDash(
    npsRespondents,
    (i) => i.nps,
    (n) => n.toFixed(1),
  );
  const highReup = INVESTOR_CRM_DATA.filter(
    (i) => i.reupProbability === "High",
  ).length;
  const reupRate = shareOrDash(highReup, activeInvestors);

  const investorType = [
    {
      name: "Institutional",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "Institutional").length,
    },
    {
      name: "Family Office",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "Family Office").length,
    },
    {
      name: "Pension",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "Pension").length,
    },
    {
      name: "Endowment",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "Endowment").length,
    },
    {
      name: "Fund of Funds",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "Fund of Funds").length,
    },
    {
      name: "HNWI",
      value: INVESTOR_CRM_DATA.filter((i) => i.type === "HNWI").length,
    },
  ];

  const daysSinceTouch = INVESTOR_CRM_DATA.map((inv) => ({
    ...inv,
    daysSince: Math.round(
      (new Date() - new Date(inv.lastTouchpoint)) / (24 * 60 * 60 * 1000),
    ),
    touchStatus:
      Math.round(
        (new Date() - new Date(inv.lastTouchpoint)) / (24 * 60 * 60 * 1000),
      ) <= 30
        ? "green"
        : Math.round(
              (new Date() - new Date(inv.lastTouchpoint)) /
                (24 * 60 * 60 * 1000),
            ) <= 60
          ? "amber"
          : "red",
  }));

  const upcomingMeetings = INVESTOR_CRM_DATA.filter((i) => i.nextMeeting)
    .sort((a, b) => new Date(a.nextMeeting) - new Date(b.nextMeeting))
    .slice(0, 5);

  return (
    <div style={{ padding: "24px", backgroundColor: C.bg }}>
      <div style={{ marginBottom: "24px" }}>
        <h1
          style={{
            fontSize: "28px",
            fontWeight: "600",
            color: C.textPrimary,
            marginBottom: "4px",
          }}
        >
          Investor CRM
        </h1>
        <p style={{ color: C.textSecondary, fontSize: "14px" }}>
          LP relationship management and pipeline tracking
        </p>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "12px",
          marginBottom: "24px",
        }}
      >
        <KPI
          label="Total AUM from LPs"
          value={fmt(totalAUM)}
          sub={`${INVESTOR_CRM_DATA.length} investors`}
        />
        <KPI
          label="Active Investors"
          value={activeInvestors}
          sub={shareOrDash(
            activeInvestors,
            INVESTOR_CRM_DATA.length,
            (p) => `${Math.round(p)}% of base`,
          )}
        />
        <KPI
          label="Avg NPS"
          value={avgNPS}
          sub={`${INVESTOR_CRM_DATA.filter((i) => i.nps).length} responses`}
        />
        <KPI
          label="High Re-up Probability"
          value={reupRate}
          sub={`${highReup} investors`}
        />
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "12px",
          marginBottom: "24px",
        }}
      >
        <SectionCard title="Investor Segmentation">
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={investorType}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, value }) => `${name} ${value}`}
                outerRadius={80}
                dataKey="value"
              >
                {investorType.map((entry, idx) => (
                  <Cell key={idx} fill={PIE_COLORS[idx % PIE_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{
                  backgroundColor: C.subtleBg,
                  border: `1px solid ${C.border}`,
                }}
              />
            </PieChart>
          </ResponsiveContainer>
        </SectionCard>

        <SectionCard title="Relationship Health">
          <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
            {[
              {
                label: "High NPS + High Re-up",
                count: INVESTOR_CRM_DATA.filter(
                  (i) => i.nps >= 8 && i.reupProbability === "High",
                ).length,
                color: "var(--ds-success-dot)",
              },
              {
                label: "Medium NPS or Medium Re-up",
                count: INVESTOR_CRM_DATA.filter(
                  (i) =>
                    (i.nps >= 6 && i.nps < 8) || i.reupProbability === "Medium",
                ).length,
                color: "var(--ds-warning-dot)",
              },
              {
                label: "Low NPS or Low Re-up",
                count: INVESTOR_CRM_DATA.filter(
                  (i) => i.nps < 6 || i.reupProbability === "Low",
                ).length,
                color: "var(--ds-danger-dot)",
              },
              {
                label: "Prospects",
                count: INVESTOR_CRM_DATA.filter((i) => i.status === "Prospect")
                  .length,
                color: "var(--ds-accent)",
              },
            ].map((segment, idx) => (
              <div
                key={idx}
                style={{
                  padding: "8px",
                  backgroundColor: C.subtleBg,
                  borderRadius: "4px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div
                  style={{ display: "flex", alignItems: "center", gap: "8px" }}
                >
                  <div
                    style={{
                      width: 12,
                      height: 12,
                      borderRadius: "2px",
                      backgroundColor: segment.color,
                    }}
                  />
                  <span style={{ color: C.textSecondary, fontSize: "13px" }}>
                    {segment.label}
                  </span>
                </div>
                <span style={{ fontWeight: "600", color: C.textPrimary }}>
                  {segment.count}
                </span>
              </div>
            ))}
          </div>
        </SectionCard>
      </div>

      {upcomingMeetings.length > 0 && (
        <SectionCard
          title={`Upcoming Meetings (${upcomingMeetings.length})`}
          style={{ marginBottom: "24px" }}
        >
          <div style={{ display: "grid", gap: "12px" }}>
            {upcomingMeetings.map((inv) => (
              <div
                key={inv.id}
                style={{
                  padding: "12px",
                  backgroundColor: C.subtleBg,
                  borderRadius: "6px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <h4
                    style={{
                      margin: 0,
                      color: C.textPrimary,
                      fontWeight: "600",
                    }}
                  >
                    {inv.name}
                  </h4>
                  <p
                    style={{
                      margin: "4px 0 0 0",
                      fontSize: "12px",
                      color: C.textSecondary,
                    }}
                  >
                    {inv.contactName} • {inv.type}
                  </p>
                </div>
                <div style={{ textAlign: "right" }}>
                  <p
                    style={{
                      margin: 0,
                      color: C.textPrimary,
                      fontWeight: "600",
                    }}
                  >
                    {formatCalendarDate(inv.nextMeeting, { style: "numeric" })}
                  </p>
                  <p
                    style={{
                      margin: "4px 0 0 0",
                      fontSize: "12px",
                      color: C.textSecondary,
                    }}
                  >
                    RM: {inv.relationshipOwner}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </SectionCard>
      )}

      <SectionCard title="Investor Directory" style={{ marginBottom: "24px" }}>
        <div
          style={{
            marginBottom: "12px",
            display: "grid",
            gridTemplateColumns: "1fr 1fr 1fr 1fr",
            gap: "12px",
          }}
        >
          <input
            type="text"
            placeholder="Search investors..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{
              padding: "8px 12px",
              borderRadius: "4px",
              border: `1px solid ${C.border}`,
              backgroundColor: C.subtleBg,
              color: C.textPrimary,
              fontSize: "13px",
              gridColumn: "1 / 2",
            }}
          />
          <Select
            value={selectedStatus || ""}
            onChange={(e) => setSelectedStatus(e.target.value || null)}
            fullWidth
            size="md"
            style={{
              padding: "8px",
              borderRadius: "4px",
              background: C.subtleBg,
            }}
          >
            <option value="">All Status</option>
            <option value="Active">Active</option>
            <option value="Prospect">Prospect</option>
            <option value="Dormant">Dormant</option>
          </Select>
          <Select
            value={selectedType || ""}
            onChange={(e) => setSelectedType(e.target.value || null)}
            fullWidth
            size="md"
            style={{
              padding: "8px",
              borderRadius: "4px",
              background: C.subtleBg,
            }}
          >
            <option value="">All Types</option>
            {[
              "Institutional",
              "Family Office",
              "Pension",
              "Endowment",
              "Fund of Funds",
              "HNWI",
            ].map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </Select>
          <button
            onClick={() => {
              setSearchTerm("");
              setSelectedStatus(null);
              setSelectedType(null);
            }}
            style={{
              padding: "8px",
              borderRadius: "4px",
              border: `1px solid ${C.border}`,
              backgroundColor: C.subtleBg,
              color: C.textPrimary,
              cursor: "pointer",
              fontSize: "13px",
            }}
          >
            Clear Filters
          </button>
        </div>
      </SectionCard>

      <SectionCard title="Investor Database" style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "12px",
          }}
        >
          <thead>
            <tr style={{ borderBottom: `1px solid ${C.border}` }}>
              <th
                style={{
                  padding: "10px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Investor
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Type
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "right",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                AUM
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "left",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Contact
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "center",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                NPS
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "center",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Re-up
              </th>
              <th
                style={{
                  padding: "10px",
                  textAlign: "center",
                  color: C.textSecondary,
                  fontWeight: "600",
                }}
              >
                Last Touch
              </th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((inv, idx) => (
              <tr
                key={inv.id}
                style={{
                  borderBottom: `1px solid ${C.border}`,
                  backgroundColor: idx % 2 === 0 ? C.cardBg : C.tableBgAlt,
                }}
              >
                <td
                  style={{
                    padding: "10px",
                    color: C.textPrimary,
                    fontWeight: "500",
                  }}
                >
                  {inv.name}
                </td>
                <td style={{ padding: "10px" }}>
                  <Badge text={inv.type} color="gray" />
                </td>
                <td
                  style={{
                    padding: "10px",
                    textAlign: "right",
                    color: C.textPrimary,
                    fontWeight: "500",
                  }}
                >
                  {fmt(inv.totalInvested)}
                </td>
                <td
                  style={{
                    padding: "10px",
                    color: C.textSecondary,
                    fontSize: "11px",
                  }}
                >
                  {inv.contactName}
                </td>
                <td
                  style={{
                    padding: "10px",
                    textAlign: "center",
                    color: inv.nps
                      ? inv.nps >= 8
                        ? "var(--ds-success-dot)"
                        : inv.nps >= 6
                          ? "var(--ds-warning-dot)"
                          : "var(--ds-danger-dot)"
                      : C.textSecondary,
                  }}
                >
                  {inv.nps ? inv.nps : "—"}
                </td>
                <td style={{ padding: "10px", textAlign: "center" }}>
                  <Badge
                    text={inv.reupProbability}
                    color={
                      inv.reupProbability === "High"
                        ? "green"
                        : inv.reupProbability === "Medium"
                          ? "amber"
                          : inv.reupProbability === "Low"
                            ? "red"
                            : "gray"
                    }
                  />
                </td>
                <td
                  style={{
                    padding: "10px",
                    textAlign: "center",
                    color:
                      daysSinceTouch.find((d) => d.id === inv.id)
                        .touchStatus === "green"
                        ? "var(--ds-success-dot)"
                        : daysSinceTouch.find((d) => d.id === inv.id)
                              .touchStatus === "amber"
                          ? "var(--ds-warning-dot)"
                          : "var(--ds-danger-dot)",
                    fontSize: "11px",
                  }}
                >
                  {daysSinceTouch.find((d) => d.id === inv.id).daysSince}d
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </SectionCard>
    </div>
  );
};

const BucketReportPage = ({ bucketName, reports }) => {
  const [selectedReportId, setSelectedReportId] = React.useState(
    reports?.[0]?.id || null,
  );
  const [generating, setGenerating] = React.useState(false);
  const [exporting, setExporting] = React.useState(false);
  const [generatingText, setGeneratingText] = React.useState("");
  const [exportingText, setExportingText] = React.useState("");
  const selectedReport = reports?.find((r) => r.id === selectedReportId);

  const handleGenerateReport = () => {
    setGenerating(true);
    setGeneratingText("Generating...");
    try {
      if (selectedReport) {
        const sections = [];
        if (
          selectedReport.metricCards &&
          selectedReport.metricCards.length > 0
        ) {
          sections.push({
            type: "metrics",
            title: "Key Metrics",
            items: selectedReport.metricCards.map((m) => ({
              label: m.label,
              value: String(m.value != null ? m.value : "—"),
            })),
          });
        }
        if (selectedReport.tableHeaders && selectedReport.tableRows) {
          sections.push({
            type: "table",
            title: selectedReport.name,
            headers: selectedReport.tableHeaders,
            rows: selectedReport.tableRows,
          });
        }
        if (sections.length > 0) {
          generateHTMLReport({
            title: selectedReport.name,
            subtitle: selectedReport.description || bucketName,
            sections,
          });
        } else {
          downloadCSV(
            `${(selectedReport.name || bucketName).replace(/\s+/g, "_")}_${new Date().toISOString().slice(0, 10)}.csv`,
            ["Report", "Category", "Frequency", "Status"],
            [
              [
                selectedReport.name,
                selectedReport.category || bucketName,
                selectedReport.frequency,
                selectedReport.status,
              ],
            ],
          );
        }
      }
    } catch (err) {
      console.error("BucketReport generate error:", err);
    }
    setGeneratingText("Report Generated ✓");
    setTimeout(() => {
      setGenerating(false);
      setGeneratingText("");
    }, 2000);
  };

  const handleExportPDF = () => {
    setExporting(true);
    setExportingText("Exporting...");
    try {
      if (selectedReport) {
        const sections = [];
        if (
          selectedReport.metricCards &&
          selectedReport.metricCards.length > 0
        ) {
          sections.push({
            type: "metrics",
            title: "Key Metrics",
            items: selectedReport.metricCards.map((m) => ({
              label: m.label,
              value: String(m.value != null ? m.value : "—"),
            })),
          });
        }
        if (selectedReport.tableHeaders && selectedReport.tableRows) {
          sections.push({
            type: "table",
            title: "Detailed Data",
            headers: selectedReport.tableHeaders,
            rows: selectedReport.tableRows,
          });
        }
        generateHTMLReport({
          title: `${selectedReport.name} — PDF Export`,
          subtitle: `${bucketName} • Generated ${new Date().toLocaleDateString()}`,
          sections:
            sections.length > 0
              ? sections
              : [
                  {
                    type: "text",
                    title: selectedReport.name,
                    content:
                      selectedReport.description ||
                      "No tabular data available for this report.",
                  },
                ],
        });
      }
    } catch (err) {
      console.error("BucketReport PDF export error:", err);
    }
    setExportingText("Exported ✓");
    setTimeout(() => {
      setExporting(false);
      setExportingText("");
    }, 2000);
  };

  if (!reports || reports.length === 0) {
    return (
      <div style={{ padding: 24, color: C.textSecondary }}>
        <p>No reports available for {bucketName}</p>
      </div>
    );
  }

  return (
    <div
      style={{
        display: "flex",
        gap: 24,
        height: "calc(100vh - 180px)",
        padding: 0,
      }}
    >
      <div
        style={{
          width: 280,
          background: C.cardBg,
          border: `1px solid ${C.border}`,
          borderRadius: 10,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          boxShadow: C.cardShadow,
        }}
      >
        <div
          style={{
            padding: "16px 20px",
            borderBottom: `1px solid ${C.border}`,
            background: C.subtleBg,
          }}
        >
          <div
            style={{
              fontSize: 11,
              fontWeight: 700,
              color: C.textSecondary,
              textTransform: "uppercase",
              letterSpacing: 0.5,
              marginBottom: 8,
            }}
          >
            Available Reports
          </div>
          <div style={{ fontSize: 14, fontWeight: 600, color: C.textPrimary }}>
            {reports.length} {reports.length === 1 ? "Report" : "Reports"}
          </div>
        </div>

        <div style={{ flex: 1, overflowY: "auto" }}>
          {reports.map((report) => (
            <div
              key={report.id}
              onClick={() => setSelectedReportId(report.id)}
              style={{
                padding: "12px 16px",
                borderLeft:
                  selectedReportId === report.id
                    ? `3px solid ${C.gold}`
                    : `3px solid transparent`,
                background:
                  selectedReportId === report.id ? C.subtleBg : "transparent",
                cursor: "pointer",
                borderBottom: `1px solid ${C.border}`,
                transition: "all 0.2s ease",
              }}
              onMouseEnter={(e) => {
                if (selectedReportId !== report.id) {
                  e.currentTarget.style.background =
                    "rgba(180, 165, 120, 0.04)";
                }
              }}
              onMouseLeave={(e) => {
                if (selectedReportId !== report.id) {
                  e.currentTarget.style.background = "transparent";
                }
              }}
            >
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 500,
                  color: C.textPrimary,
                  marginBottom: 4,
                }}
              >
                {report.name}
              </div>
              <div
                style={{
                  fontSize: 11,
                  color: C.textSecondary,
                  marginBottom: 6,
                }}
              >
                {report.category}
              </div>
              <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
                <Badge
                  text={report.frequency}
                  color={report.frequency === "Weekly" ? "blue" : "amber"}
                />
                <Badge
                  text={report.status}
                  color={report.status === "Ready" ? "green" : "amber"}
                />
              </div>
            </div>
          ))}
        </div>
      </div>

      {selectedReport && (
        <div
          style={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            gap: 20,
            overflowY: "auto",
          }}
        >
          <SectionCard
            title={selectedReport.name}
            subtitle={selectedReport.description}
            action={
              <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                <Badge
                  text={selectedReport.status}
                  color={selectedReport.status === "Ready" ? "green" : "amber"}
                />
                <div style={{ fontSize: 12, color: C.textSecondary }}>
                  Last generated: {selectedReport.lastGenerated}
                </div>
              </div>
            }
          >
            <div style={{ display: "flex", gap: 20 }}>
              <div>
                <div
                  style={{
                    fontSize: 11,
                    color: C.textSecondary,
                    textTransform: "uppercase",
                    fontWeight: 600,
                    marginBottom: 6,
                  }}
                >
                  Frequency
                </div>
                <div
                  style={{
                    fontSize: 14,
                    fontWeight: 500,
                    color: C.textPrimary,
                  }}
                >
                  {selectedReport.frequency}
                </div>
              </div>
              <div>
                <div
                  style={{
                    fontSize: 11,
                    color: C.textSecondary,
                    textTransform: "uppercase",
                    fontWeight: 600,
                    marginBottom: 6,
                  }}
                >
                  Last Generated
                </div>
                <div
                  style={{
                    fontSize: 14,
                    fontWeight: 500,
                    color: C.textPrimary,
                  }}
                >
                  {selectedReport.lastGenerated}
                </div>
              </div>
            </div>
          </SectionCard>

          <div style={{ display: "flex", gap: 16 }}>
            {selectedReport.kpis?.map((kpi, idx) => (
              <KPI
                key={idx}
                label={kpi.label}
                value={kpi.value}
                sub={kpi.sub}
                color={kpi.color || C.gold}
                trend={kpi.trend}
              />
            ))}
          </div>

          {selectedReport.chartData && (
            <SectionCard
              title="Performance Trend"
              subtitle={selectedReport.chartSubtitle || ""}
            >
              <ResponsiveContainer width="100%" height={300}>
                {selectedReport.chartType === "bar" && (
                  <BarChart data={selectedReport.chartData}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
                    <XAxis
                      dataKey="name"
                      stroke={C.textSecondary}
                      fontSize={12}
                    />
                    <YAxis stroke={C.textSecondary} fontSize={12} />
                    <Tooltip
                      contentStyle={{
                        background: C.cardBg,
                        border: `1px solid ${C.border}`,
                        borderRadius: 6,
                      }}
                      labelStyle={{ color: C.textPrimary }}
                    />
                    <Bar dataKey="value" fill={C.gold} radius={[6, 6, 0, 0]} />
                  </BarChart>
                )}
                {selectedReport.chartType === "line" && (
                  <LineChart data={selectedReport.chartData}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
                    <XAxis
                      dataKey="name"
                      stroke={C.textSecondary}
                      fontSize={12}
                    />
                    <YAxis stroke={C.textSecondary} fontSize={12} />
                    <Tooltip
                      contentStyle={{
                        background: C.cardBg,
                        border: `1px solid ${C.border}`,
                        borderRadius: 6,
                      }}
                      labelStyle={{ color: C.textPrimary }}
                    />
                    <Line
                      type="monotone"
                      dataKey="value"
                      stroke={C.gold}
                      strokeWidth={2}
                      dot={{ fill: C.gold, r: 4 }}
                    />
                  </LineChart>
                )}
                {selectedReport.chartType === "area" && (
                  <AreaChart data={selectedReport.chartData}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
                    <XAxis
                      dataKey="name"
                      stroke={C.textSecondary}
                      fontSize={12}
                    />
                    <YAxis stroke={C.textSecondary} fontSize={12} />
                    <Tooltip
                      contentStyle={{
                        background: C.cardBg,
                        border: `1px solid ${C.border}`,
                        borderRadius: 6,
                      }}
                      labelStyle={{ color: C.textPrimary }}
                    />
                    <Area
                      type="monotone"
                      dataKey="value"
                      fill={C.goldLight}
                      stroke={C.gold}
                    />
                  </AreaChart>
                )}
              </ResponsiveContainer>
            </SectionCard>
          )}

          {selectedReport.tableHeaders && selectedReport.tableRows && (
            <SectionCard title="Detailed Data" subtitle="">
              <MiniTable
                headers={selectedReport.tableHeaders}
                rows={selectedReport.tableRows}
              />
            </SectionCard>
          )}

          <div style={{ display: "flex", gap: 12, paddingBottom: 20 }}>
            <button
              onClick={handleGenerateReport}
              disabled={generating}
              style={{
                padding: "12px 20px",
                background: C.gold,
                color: "#000",
                border: "none",
                borderRadius: 6,
                fontWeight: 600,
                cursor: generating ? "not-allowed" : "pointer",
                fontSize: 14,
                transition: "all 0.2s ease",
                opacity: generating ? 0.7 : 1,
              }}
              onMouseEnter={(e) =>
                !generating && (e.currentTarget.style.opacity = 0.9)
              }
              onMouseLeave={(e) =>
                !generating && (e.currentTarget.style.opacity = 1)
              }
            >
              {generatingText || "Generate Report"}
            </button>
            <button
              onClick={handleExportPDF}
              disabled={exporting}
              style={{
                padding: "12px 20px",
                background: "transparent",
                color: C.gold,
                border: `1px solid ${C.gold}`,
                borderRadius: 6,
                fontWeight: 600,
                cursor: exporting ? "not-allowed" : "pointer",
                fontSize: 14,
                transition: "all 0.2s ease",
                opacity: exporting ? 0.7 : 1,
              }}
              onMouseEnter={(e) =>
                !exporting &&
                (e.currentTarget.style.background = "rgba(180, 165, 120, 0.08)")
              }
              onMouseLeave={(e) =>
                !exporting && (e.currentTarget.style.background = "transparent")
              }
            >
              {exportingText || "Export PDF"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

