function CanonicalFieldsPreview({
  discoverResult,
  confidenceReport,
  formulaAuditFindings,
  selectedProperty,
}) {
  const [drillDown, setDrillDown] = React.useState(null);

  if (!discoverResult) return null;
  const allFields = Object.keys(discoverResult.mapping || {});
  const inputFields = allFields
    .filter((f) => (discoverResult.mapping[f]?.role || "input") === "input")
    .sort();
  const refFields = allFields
    .filter((f) => discoverResult.mapping[f]?.role === "reference")
    .sort();
  const graphId = discoverResult.workbook_summary?.graph_id;

  const chipStyle = (level) => {
    if (level === "HIGH")
      return {
        label: "high",
        color: "var(--ds-success-text)",
        bg: "var(--ds-success-bg)",
      };
    if (level === "MEDIUM")
      return {
        label: "med",
        color: "var(--ds-warning-text)",
        bg: "var(--ds-warning-bg)",
      };
    if (level === "LOW")
      return {
        label: "low",
        color: "var(--ds-danger-text)",
        bg: "var(--ds-danger-bg)",
      };
    return null;
  };

  const renderSection = (title, description, fields, headerBg) => (
    <div
      style={{
        marginTop: 16,
        border: `1px solid ${C.border}`,
        borderRadius: 8,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          padding: "8px 14px",
          background: headerBg,
          borderBottom: `1px solid ${C.border}`,
          fontSize: 12,
          fontWeight: 700,
          color: C.textPrimary,
        }}
      >
        {title}
        <span
          style={{
            marginLeft: 8,
            fontWeight: 500,
            color: C.textSecondary,
            fontSize: 11,
          }}
        >
          ({fields.length}) — {description} · click any row to drill into the
          formula chain
        </span>
      </div>
      <div style={{ maxHeight: "35vh", overflowY: "auto" }}>
        <table
          style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}
        >
          <thead>
            <tr
              style={{
                background: C.tableHeaderBg,
                borderBottom: `2px solid ${C.border}`,
                position: "sticky",
                top: 0,
              }}
            >
              <th
                style={{
                  padding: "8px 10px",
                  textAlign: "left",
                  fontWeight: 700,
                }}
              >
                Field
              </th>
              <th
                style={{
                  padding: "8px 10px",
                  textAlign: "left",
                  fontWeight: 700,
                }}
              >
                Sheet!Cell
              </th>
              <th
                style={{
                  padding: "8px 10px",
                  textAlign: "left",
                  fontWeight: 700,
                }}
              >
                Label
              </th>
              <th
                style={{
                  padding: "8px 10px",
                  textAlign: "right",
                  fontWeight: 700,
                }}
              >
                Value
              </th>
              <th
                style={{
                  padding: "8px 10px",
                  textAlign: "center",
                  fontWeight: 700,
                  width: 80,
                }}
              >
                Confidence
              </th>
            </tr>
          </thead>
          <tbody>
            {fields.map((field) => {
              const spec = discoverResult.mapping[field];
              const value = discoverResult.preview_values?.[field];
              const notFound = !spec;
              const conf = confidenceReport?.perField?.[field];
              const chip = conf ? chipStyle(conf.level) : null;
              const tooltip = conf
                ? conf.reasons?.length
                  ? conf.reasons.join("\n")
                  : `${conf.level} confidence`
                : "";
              return (
                <tr
                  key={field}
                  onClick={
                    spec
                      ? () =>
                          setDrillDown({
                            sheet: spec.sheet,
                            cell: spec.cell,
                            label: spec.label || field,
                            value,
                          })
                      : undefined
                  }
                  style={{
                    borderBottom: `1px solid ${C.border}`,
                    opacity: notFound ? 0.4 : 1,
                    cursor: spec ? "pointer" : "default",
                  }}
                  title={spec ? "Click to drill into the formula chain" : ""}
                >
                  <td
                    style={{
                      padding: "6px 10px",
                      fontFamily: "monospace",
                      color: C.textPrimary,
                    }}
                  >
                    {field}
                  </td>
                  <td
                    style={{
                      padding: "6px 10px",
                      fontSize: 11,
                      color: spec ? C.accent : C.textSecondary,
                      textDecoration: spec ? "underline" : "none",
                    }}
                  >
                    {spec ? `${spec.sheet}!${spec.cell}` : "—"}
                  </td>
                  <td
                    style={{
                      padding: "6px 10px",
                      fontSize: 11,
                      color: C.textSecondary,
                    }}
                  >
                    {spec?.label || "—"}
                  </td>
                  <td
                    style={{
                      padding: "6px 10px",
                      textAlign: "right",
                      fontWeight: 600,
                      color: value == null ? C.textSecondary : C.textPrimary,
                    }}
                  >
                    {value == null
                      ? "—"
                      : typeof value === "number"
                        ? value.toLocaleString(undefined, {
                            maximumFractionDigits: 4,
                          })
                        : String(value).slice(0, 60)}
                  </td>
                  <td style={{ padding: "6px 10px", textAlign: "center" }}>
                    {chip ? (
                      <span
                        title={tooltip}
                        style={{
                          fontSize: 10,
                          fontWeight: 700,
                          textTransform: "uppercase",
                          padding: "2px 8px",
                          borderRadius: 10,
                          background: chip.bg,
                          color: chip.color,
                          cursor: "help",
                        }}
                      >
                        {chip.label}
                      </span>
                    ) : (
                      <span style={{ fontSize: 10, color: C.textSecondary }}>
                        —
                      </span>
                    )}
                  </td>
                </tr>
              );
            })}
            {!fields.length && (
              <tr>
                <td
                  colSpan={5}
                  style={{
                    padding: "14px",
                    textAlign: "center",
                    color: C.textSecondary,
                    fontSize: 12,
                  }}
                >
                  No fields in this tier.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <>
      {renderSection(
        "Primary inputs",
        "static, analyst-entered values — authoritative inputs to the platform's compute engine",
        inputFields,
        `${alpha(C.accent, 6.3)}`,
      )}
      {renderSection(
        "Reference values (model-computed)",
        "IRR / EM / NOI / cap rates etc. — stored for reconciliation vs. platform-computed outputs",
        refFields,
        "var(--ds-warning-bg)",
      )}
      <UnderwritingTabularPreview
        graphId={graphId}
        propertyId={selectedProperty?.id}
      />
      {drillDown && graphId && (
        <CellDrillDown
          graphId={graphId}
          root={drillDown}
          formulaAuditFindings={formulaAuditFindings}
          onClose={() => setDrillDown(null)}
        />
      )}
    </>
  );
}

function CellDrillDown({ graphId, root, formulaAuditFindings, onClose }) {
  const [nodeCache, setNodeCache] = React.useState({});
  const [loading, setLoading] = React.useState({});
  const [expanded, setExpanded] = React.useState({});
  const [error, setError] = React.useState(null);

  const auditByKey = React.useMemo(() => {
    const m = {};
    for (const f of formulaAuditFindings || []) {
      m[`${f.sheet}\x00${String(f.cell).toUpperCase()}`] = f;
    }
    return m;
  }, [formulaAuditFindings]);

  const fetchCell = React.useCallback(
    async (sheet, cell) => {
      const cellUpper = String(cell).toUpperCase();
      const k = `${sheet}\x00${cellUpper}`;
      if (nodeCache[k] || loading[k]) return;
      setLoading((prev) => ({ ...prev, [k]: true }));
      try {
        const { data, error } = await supabase
          .from("property_underwriting_model_nodes")
          .select(
            "sheet,cell,formula,value_num,value_text,value_date,label_hint",
          )
          .eq("graph_id", graphId)
          .eq("sheet", sheet)
          .eq("cell", cellUpper)
          .maybeSingle();
        if (error) throw error;
        setNodeCache((prev) => ({ ...prev, [k]: data || null }));
      } catch (e) {
        setError(`Failed to fetch ${sheet}!${cellUpper}: ${e.message || e}`);
      } finally {
        setLoading((prev) => ({ ...prev, [k]: false }));
      }
    },
    [graphId, nodeCache, loading],
  );

  React.useEffect(() => {
    if (root?.sheet && root?.cell) fetchCell(root.sheet, root.cell);
  }, [root?.sheet, root?.cell, fetchCell]);

  if (!root) return null;

  const fmt = (v) => {
    if (v == null || v === "")
      return <span style={{ color: C.textSecondary }}>—</span>;
    if (typeof v === "number")
      return v.toLocaleString(undefined, { maximumFractionDigits: 6 });
    return String(v);
  };

  const StatusBadge = ({ cellKey, hasFormula }) => {
    const f = auditByKey[cellKey];
    let bg = "var(--ds-border)",
      color = "var(--ds-text-primary)",
      label = hasFormula ? "no audit" : "input";
    if (f) {
      if (f.status === "verified") {
        bg = "var(--ds-success-bg)";
        color = "var(--ds-success-text)";
        label = "verified";
      } else if (f.status === "mismatch") {
        bg = "var(--ds-danger-bg)";
        color = "var(--ds-danger-text)";
        label = `${(f.relativeDrift * 100).toFixed(2)}% off`;
      } else if (f.status === "error") {
        bg = "var(--ds-danger-bg)";
        color = "var(--ds-danger-text)";
        label = "error";
      } else if (f.status === "skip") {
        bg = "var(--ds-warning-bg)";
        color = "var(--ds-warning-text)";
        label = "skip";
      }
    }
    return (
      <span
        style={{
          fontSize: 9,
          fontWeight: 700,
          textTransform: "uppercase",
          padding: "2px 6px",
          borderRadius: 8,
          background: bg,
          color,
        }}
      >
        {label}
      </span>
    );
  };

  const renderCell = (sheet, cell, depth = 0) => {
    const cellUpper = String(cell).toUpperCase();
    const k = `${sheet}\x00${cellUpper}`;
    const node = nodeCache[k];
    const isLoading = loading[k];
    const isExpanded = expanded[k];
    const isRange = cell.includes(":");

    if (isRange) {
      return (
        <div
          key={k + depth}
          style={{
            marginLeft: depth * 18,
            padding: "4px 0",
            borderLeft: depth > 0 ? `1px solid ${C.border}` : "none",
            paddingLeft: depth > 0 ? 10 : 0,
          }}
        >
          <span
            style={{
              fontFamily: "monospace",
              fontSize: 11,
              color: C.textSecondary,
            }}
          >
            {sheet}!{cell}{" "}
            <span style={{ fontStyle: "italic" }}>
              (range, drill-down not shown)
            </span>
          </span>
        </div>
      );
    }

    const refs = node?.formula ? extractCellRefs(node.formula, sheet) : [];
    const value =
      node?.value_num != null
        ? node.value_num
        : node?.value_text || node?.value_date;
    const auditFinding = auditByKey[k];

    return (
      <div
        key={k + depth}
        style={{
          marginLeft: depth * 18,
          padding: "4px 0",
          borderLeft: depth > 0 ? `1px solid ${C.border}` : "none",
          paddingLeft: depth > 0 ? 10 : 0,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            fontSize: 12,
          }}
        >
          {refs.length > 0 ? (
            <button
              onClick={() => {
                setExpanded((prev) => ({ ...prev, [k]: !prev[k] }));
                if (!isExpanded)
                  for (const r of refs) fetchCell(r.sheet, r.cell);
              }}
              style={{
                background: "transparent",
                border: "none",
                cursor: "pointer",
                padding: 0,
                fontSize: 10,
                color: C.textSecondary,
                width: 12,
              }}
              title={isExpanded ? "Collapse" : "Expand refs"}
            >
              {isExpanded ? "▼" : "▶"}
            </button>
          ) : (
            <span style={{ width: 12 }} />
          )}
          <span
            style={{
              fontFamily: "monospace",
              fontWeight: 600,
              color: C.textPrimary,
            }}
          >
            {sheet}!{cellUpper}
          </span>
          {node?.label_hint && (
            <span style={{ fontSize: 11, color: C.textSecondary }}>
              · {String(node.label_hint).slice(0, 40)}
            </span>
          )}
          <span
            style={{
              marginLeft: "auto",
              fontFamily: "monospace",
              fontSize: 12,
            }}
          >
            = {fmt(value)}
          </span>
          <StatusBadge cellKey={k} hasFormula={!!node?.formula} />
        </div>
        {node?.formula && (
          <div
            style={{
              marginLeft: 18,
              fontSize: 11,
              fontFamily: "monospace",
              color: C.textSecondary,
              wordBreak: "break-all",
            }}
          >
            {node.formula}
          </div>
        )}
        {auditFinding?.status === "mismatch" && (
          <div
            style={{
              marginLeft: 18,
              fontSize: 11,
              color: "var(--ds-danger-text)",
              marginTop: 2,
            }}
          >
            Model = {fmt(auditFinding.modelValue)} · Platform ={" "}
            {fmt(auditFinding.platformValue)} (
            {auditFinding.absoluteDrift?.toLocaleString?.() ||
              auditFinding.absoluteDrift}{" "}
            drift)
          </div>
        )}
        {isLoading && (
          <div
            style={{
              marginLeft: 18,
              fontSize: 11,
              color: C.textSecondary,
              fontStyle: "italic",
            }}
          >
            loading…
          </div>
        )}
        {!node && !isLoading && (
          <div
            style={{
              marginLeft: 18,
              fontSize: 11,
              color: C.textSecondary,
              fontStyle: "italic",
            }}
          >
            (cell not in graph)
          </div>
        )}
        {isExpanded && refs.map((r) => renderCell(r.sheet, r.cell, depth + 1))}
      </div>
    );
  };

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.4)",
        zIndex: 1000,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
      }}
      onClick={onClose}
    >
      <div
        style={{
          background: C.white,
          borderRadius: 8,
          maxWidth: 800,
          width: "100%",
          maxHeight: "85vh",
          display: "flex",
          flexDirection: "column",
          boxShadow: "0 10px 40px rgba(0,0,0,0.2)",
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div
          style={{
            padding: "12px 16px",
            borderBottom: `1px solid ${C.border}`,
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          <strong style={{ fontSize: 14 }}>
            Formula chain · {root.sheet}!{root.cell}
          </strong>
          {root.label && (
            <span style={{ fontSize: 12, color: C.textSecondary }}>
              · {root.label}
            </span>
          )}
          <button
            onClick={onClose}
            style={{
              marginLeft: "auto",
              background: "transparent",
              border: "none",
              fontSize: 18,
              cursor: "pointer",
              color: C.textSecondary,
            }}
          >
            ×
          </button>
        </div>
        <div style={{ padding: 16, overflowY: "auto", flex: 1 }}>
          {error && (
            <div
              style={{
                color: "var(--ds-danger-text)",
                marginBottom: 8,
                fontSize: 12,
              }}
            >
              {error}
            </div>
          )}
          {renderCell(root.sheet, root.cell, 0)}
        </div>
        <div
          style={{
            padding: "8px 16px",
            borderTop: `1px solid ${C.border}`,
            fontSize: 11,
            color: C.textSecondary,
          }}
        >
          Click ▶ on any cell to expand its references. Status badges show audit
          findings: ✓ verified, ✗ mismatch, ⚠ skip.
        </div>
      </div>
    </div>
  );
}

