function renderBudgetAccountRow({
  keyPrefix,
  account,
  axis,
  valueByMonth,
  totalValue,
  isActualByMonth,
  activityByMonth,
  activityPresentByMonth,
  absentByMonth,
  unbudgeted,
  rowIndex,
  depth = 0,
  onOpen = null,
  isOpen = false,
  exclusionNote = null,
}) {
  const rowBg = bandedCellBackground(rowIndex, C);
  const accountNameText = account.account_name || "\u2014";
  const accountNameNode = exclusionNote
    ? React.createElement(
        "span",
        {
          title: exclusionNote,
          style: {
            borderBottom: `1px dotted ${C.textSecondary}`,
            cursor: "help",
          },
        },
        accountNameText,
      )
    : accountNameText;
  return React.createElement(
    "tr",
    {
      key: `${keyPrefix}-${account.account_number}`,
      style: { borderTop: `1px solid ${C.border}`, background: rowBg },
    },
    React.createElement(
      "td",
      {
        style: {
          ...BUDGET_CELL_BASE,
          ...budgetStickyAcctStyle(rowBg, 1),
          textAlign: "left",
          fontFamily: "monospace",
          color: C.textPrimary,
        },
      },
      account.account_number || "",
    ),
    React.createElement(
      "td",
      {
        style: {
          ...BUDGET_CELL_BASE,
          ...budgetStickyNameStyle(rowBg, 1),
          textAlign: "left",
          paddingLeft: statementRowPresentation({ kind: "account", depth })
            .paddingLeft,
          color: C.textPrimary,
          overflow: "hidden",
          textOverflow: "ellipsis",
        },
        title: account.account_name || "",
      },
      onOpen
        ? React.createElement(
            "button",
            {
              type: "button",
              onClick: onOpen,
              "aria-expanded": isOpen,
              title: isOpen
                ? "Close this account\u2019s card"
                : "Open this account in a card \u2014 one card for the account, over the lines the workbook stores one per month",
              style: {
                background: "transparent",
                border: "none",
                padding: 0,
                marginRight: 6,
                cursor: "pointer",
                font: "inherit",
                color: C.textPrimary,
                textAlign: "left",
              },
            },
            React.createElement(
              "span",
              { style: { color: C.textSecondary, marginRight: 5 } },
              isOpen ? "\u25be" : "\u25b8",
            ),
            accountNameNode,
          )
        : accountNameNode,
      unbudgeted
        ? React.createElement(
            "span",
            {
              title: COA_ABSENCE_LEGEND.unbudgetedChipTitle,
              style: {
                marginLeft: 6,
                fontSize: 10,
                fontWeight: 700,
                letterSpacing: 0.3,
                textTransform: "uppercase",
                color: C.textSecondary,
                border: `1px solid ${C.border}`,
                borderRadius: 3,
                padding: "0 4px",
                whiteSpace: "nowrap",
              },
            },
            COA_ABSENCE_LEGEND.unbudgetedChip,
          )
        : null,
    ),
    ...axis.map((m, i) => {
      const isActual = isActualByMonth ? isActualByMonth[i] : false;
      const absent = !!(absentByMonth && absentByMonth[i]);
      const activityPresence = activityPresentByMonth
        ? activityPresentByMonth[i]
        : true;
      return React.createElement(
        "td",
        {
          key: `${keyPrefix}-${account.account_number}-${m.month_index}`,
          title:
            activityByMonth && activityPresence === false
              ? BALANCE_ACTIVITY_ABSENT_TITLE
              : coaAbsenceCellTitle({
                  absent,
                  value: activityByMonth ? null : valueByMonth[i],
                }),
          style: {
            ...BUDGET_CELL_BASE,
            color: isActual ? C.textSecondary : C.textPrimary,
          },
        },
        absent
          ? ""
          : activityByMonth
            ? balanceCellContent({
                change: activityByMonth[i],
                balance: valueByMonth[i],
                changePresent: activityPresence,
                fmtCell: fmtBudgetCell,
              })
            : fmtBudgetCell(valueByMonth[i]),
      );
    }),
    React.createElement(
      "td",
      {
        title: coaAbsenceCellTitle({
          absent: totalValue === null,
          value: null,
        }),
        style: {
          ...BUDGET_CELL_BASE,
          fontWeight: 700,
          color: C.textPrimary,
          borderLeft: `1px solid ${C.border}`,
        },
      },
      totalValue === null ? "" : fmtBudgetTotal(totalValue),
    ),
  );
}

function renderNoiTemplateRow(
  row,
  axis,
  debtOverlayMap,
  rowIndex,
  debtMetricsFailed,
) {
  const lineType = row.line_type || "detail";
  const indent = Number(row.indent_level || 0);
  const lineId = row.line_id;

  if (lineType === "section_header") {
    const p = statementRowPresentation({
      kind: "header",
      headerKind: "section",
      depth: 0,
    });
    return React.createElement(
      "tr",
      {
        key: `noi-line-${lineId}`,
        "data-statement-heading": `noi-${lineId}`,
        "data-statement-depth": 0,
        "data-statement-label": row.line_label,
      },
      React.createElement(
        "td",
        {
          colSpan: axis.length + 3,
          style: {
            padding: "10px 12px",
            paddingLeft: p.paddingLeft,
            background: C.subtleBg,
            color: C.textPrimary,
            fontSize: 12,
            fontWeight: p.fontWeight,
            textTransform: p.textTransform,
            letterSpacing: p.letterSpacing,
            borderTop: `1px solid ${C.border}`,
            borderBottom: `1px solid ${C.border}`,
          },
        },
        renderBandLabel(row.line_label, p.paddingLeft),
      ),
    );
  }
  if (lineType === "subgroup_header") {
    const p = statementRowPresentation({
      kind: "header",
      headerKind: "group",
      depth: indent,
    });
    return React.createElement(
      "tr",
      {
        key: `noi-line-${lineId}`,
        "data-statement-heading": `noi-${lineId}`,
        "data-statement-depth": indent,
        "data-statement-label": row.line_label,
      },
      React.createElement(
        "td",
        {
          colSpan: axis.length + 3,
          style: {
            padding: `6px 12px 6px ${p.paddingLeft}px`,
            background: "transparent",
            color: C.textSecondary,
            fontSize: 11,
            fontWeight: p.fontWeight,
            textTransform: p.textTransform,
            letterSpacing: p.letterSpacing,
            borderTop: `1px solid ${C.border}`,
          },
        },
        renderBandLabel(row.line_label, p.paddingLeft),
      ),
    );
  }
  if (lineType === "spacer") {
    return React.createElement(
      "tr",
      { key: `noi-line-${lineId}` },
      React.createElement(
        "td",
        {
          colSpan: axis.length + 3,
          style: { padding: "4px 0", background: C.cardBg },
        },
        "",
      ),
    );
  }

  const isTotal = lineType === "total";
  const isSubtotal = lineType === "subtotal";
  const isPlaceholder =
    lineType === "placeholder_uwpf" || lineType === "derived_placeholder";

  const lid = Number(lineId);
  const isMetricLine = lid === 700 || lid === 710;
  const isWiredDebtLine =
    isPlaceholder &&
    (lid === 601 ||
      lid === 602 ||
      lid === 603 ||
      lid === 609 ||
      lid === 619 ||
      isMetricLine);
  const overlayByPos =
    isWiredDebtLine && debtOverlayMap
      ? axis.map((m) => {
          const ov = debtOverlayMap.get(`${lid}:${m.month_index}`);
          return ov == null ? null : ov;
        })
      : null;
  const rowLit = !!(overlayByPos && overlayByPos.some((v) => v != null));
  const metricLoadFailed = isMetricLine && !rowLit && !!debtMetricsFailed;
  const overlayTotal = rowLit
    ? overlayByPos.reduce((s, v) => s + (v == null ? 0 : v), 0)
    : null;
  const showAsPlaceholder = isPlaceholder && !rowLit;

  const rowBg = isTotal
    ? "#F0F4FA"
    : isSubtotal
      ? C.subtleBg
      : bandedCellBackground(rowIndex, C);
  const borderTop = isTotal ? `2px solid ${C.accent}` : `1px solid ${C.border}`;
  const borderBottom = isTotal ? `1px solid ${C.border}` : undefined;
  const labelColor = showAsPlaceholder ? C.textSecondary : C.textPrimary;
  const labelWeight = isTotal
    ? 800
    : isSubtotal
      ? 700
      : showAsPlaceholder
        ? 500
        : 500;
  const cellWeight = isTotal ? 700 : isSubtotal ? 700 : 400;
  const totalWeight = isTotal ? 800 : isSubtotal ? 700 : 500;
  const tooltip = rowLit
    ? isMetricLine
      ? lid === 700
        ? "DSCR — trailing-12 NOI ÷ debt service (UW pro-forma; stabilized + per-year below the grid)"
        : "LTV — senior loan ÷ (trailing-12 NOI ÷ 5.25% cap) (UW pro-forma; stabilized + per-year below the grid)"
      : "UW pro-forma loan model"
    : isPlaceholder && row.placeholder_tooltip
      ? row.placeholder_tooltip
      : undefined;
  const metricFailureTitle = metricLoadFailed
    ? `${row.line_label} could not be loaded — see the notice above the grid. This is a failed load, not a zero.`
    : undefined;
  const labelStyle = {
    ...BUDGET_CELL_BASE,
    ...budgetStickyNameStyle(rowBg, 1),
    textAlign: "left",
    paddingLeft: statementIndent(indent),
    fontWeight: labelWeight,
    color: labelColor,
    fontStyle: showAsPlaceholder ? "italic" : "normal",
  };

  return React.createElement(
    "tr",
    {
      key: `noi-line-${lineId}`,
      style: { borderTop, borderBottom, background: rowBg },
      ...(isTotal || isSubtotal
        ? {
            "data-statement-total": `noi-${lineId}`,
            "data-statement-depth": indent,
          }
        : null),
    },
    React.createElement(
      "td",
      {
        style: {
          ...BUDGET_CELL_BASE,
          ...budgetStickyAcctStyle(rowBg, 1),
          textAlign: "left",
        },
      },
      "",
    ),
    React.createElement(
      "td",
      { style: labelStyle, title: tooltip || row.line_label },
      row.line_label,
    ),
    ...axis.map((m, i) => {
      const ov = overlayByPos ? overlayByPos[i] : null;
      const v = row.monthly ? row.monthly[i] : null;
      const display =
        ov != null
          ? isMetricLine
            ? fmtDebtMetric(lid, ov)
            : fmtBudgetCell(ov)
          : metricLoadFailed
            ? "⚠"
            : showAsPlaceholder
              ? "—"
              : v == null
                ? "—"
                : fmtBudgetCell(v);
      return React.createElement(
        "td",
        {
          key: `noi-line-${lineId}-${m.month_index}`,
          style: {
            ...BUDGET_CELL_BASE,
            fontWeight: metricLoadFailed ? 700 : cellWeight,
            color: metricLoadFailed ? "var(--ds-danger-text)" : labelColor,
          },
          title: metricLoadFailed ? metricFailureTitle : tooltip,
        },
        display,
      );
    }),
    React.createElement(
      "td",
      {
        style: {
          ...BUDGET_CELL_BASE,
          fontWeight: totalWeight,
          color: labelColor,
          borderLeft: `1px solid ${C.border}`,
        },
        title: tooltip,
      },
      isMetricLine
        ? metricLoadFailed
          ? "⚠"
          : "—"
        : rowLit
          ? fmtBudgetTotal(overlayTotal)
          : isPlaceholder || row.total == null
            ? "—"
            : fmtBudgetTotal(row.total),
    ),
  );
}

