function renderBudgetPanelChrome({
  state,
  hasData,
  emptyCopy,
  propertyCode,
  onRetry,
  content,
}) {
  if (state.loading) {
    return React.createElement(
      "div",
      { style: { padding: 16 } },
      React.createElement(SkeletonContent, { C, kpis: 0, rows: 8, cols: 6 }),
    );
  }
  if (state.error) {
    return React.createElement(
      "div",
      {
        style: {
          padding: 12,
          background: "var(--ds-danger-bg)",
          border:
            "1px solid color-mix(in srgb, var(--ds-danger-dot) 34.9%, transparent)",
          borderRadius: 6,
          fontSize: 13,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
        },
      },
      React.createElement(
        "div",
        { style: { color: "var(--ds-danger-text)" } },
        `Could not load budget for ${propertyCode}: ${state.error.message || String(state.error)}`,
      ),
      React.createElement(
        "button",
        {
          type: "button",
          onClick: onRetry,
          style: {
            padding: "6px 12px",
            background: "#fff",
            color: "var(--ds-danger-text)",
            border:
              "1px solid color-mix(in srgb, var(--ds-danger-dot) 34.9%, transparent)",
            borderRadius: 6,
            cursor: "pointer",
            fontSize: 12,
            fontWeight: 700,
          },
        },
        "Retry",
      ),
    );
  }
  if (!hasData) {
    return React.createElement(
      "div",
      {
        style: {
          padding: 16,
          background: C.cardBg,
          border: `1px solid ${C.border}`,
          borderRadius: 8,
          color: C.textSecondary,
          fontSize: 13,
        },
      },
      emptyCopy,
    );
  }
  return content;
}

function BudgetNoiBuildPanel({
  state,
  propertyCode,
  onRetry,
  debtOverlayMap,
  debtMetricsRows,
  debtMetricsError,
}) {
  const view = useMemo(
    () => synthesizeNoiBuildHierarchy(state.data),
    [state.data],
  );
  const debtMetricsFailed = !!debtMetricsError;
  const rows = view.rows.map((row, i) =>
    renderNoiTemplateRow(row, view.axis, debtOverlayMap, i, debtMetricsFailed),
  );

  const debtMetricsNotice = debtMetricsFailed
    ? React.createElement(
        "div",
        {
          role: "status",
          style: {
            padding: "8px 12px",
            background: "var(--ds-danger-bg)",
            border:
              "1px solid color-mix(in srgb, var(--ds-danger-dot) 34.9%, transparent)",
            borderRadius: 6,
            fontSize: 12,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            marginBottom: 8,
          },
        },
        React.createElement(
          "div",
          { style: { color: "var(--ds-danger-text)" } },
          `DSCR and LTV could not be loaded: ${debtMetricsError.message || String(debtMetricsError)}. The ⚠ cells on those two rows are a failed load, not a zero — every other row on this grid loaded normally.`,
        ),
        React.createElement(
          "button",
          {
            type: "button",
            onClick: onRetry,
            style: {
              padding: "5px 10px",
              background: "#fff",
              color: "var(--ds-danger-text)",
              border:
                "1px solid color-mix(in srgb, var(--ds-danger-dot) 34.9%, transparent)",
              borderRadius: 6,
              cursor: "pointer",
              fontSize: 12,
              fontWeight: 700,
              whiteSpace: "nowrap",
            },
          },
          "Retry",
        ),
      )
    : null;

  const content = React.createElement(
    "div",
    { style: { display: "flex", flexDirection: "column" } },
    debtMetricsNotice,
    React.createElement(
      StatementStickyGrid,
      {
        theme: { border: C.border, subtle: C.subtleBg, cardBg: C.cardBg },
        maxHeight: 600,
        style: { background: C.cardBg },
      },
      React.createElement(
        "table",
        {
          style: {
            borderCollapse: "separate",
            borderSpacing: 0,
            fontSize: 12,
            width: "max-content",
            minWidth: "100%",
          },
        },
        renderBudgetGridHeader(view.axis, "", "NOI Build line"),
        React.createElement("tbody", null, ...rows),
      ),
    ),
    React.createElement(DebtMetricsSummary, {
      rows: debtMetricsRows,
      theme: {
        text: C.textPrimary,
        sub: C.textSecondary,
        border: C.border,
        card: C.cardBg,
        subtle: C.subtleBg,
      },
    }),
  );

  return renderBudgetPanelChrome({
    state,
    hasData: view.hasData,
    emptyCopy: `No budget data yet for ${propertyCode}. Load the v26 workbook on the Budget Workbook section above to populate the raw layer.`,
    propertyCode,
    onRetry,
    content,
  });
}

const COA_HIDE_ZERO_LABEL = "Hide zero balance accounts";

