function EntrataBudgetWritebackView({ propertyCode, userProfile }) {
  const [tab, setTab] = useState("preview");
  const [coa, setCoa] = useState({ data: [], loading: true, error: null });
  const [itemized, setItemized] = useState({
    data: [],
    loading: true,
    error: null,
  });
  const [history, setHistory] = useState({
    data: [],
    loading: true,
    error: null,
  });
  const [includePriorMonths, setIncludePriorMonths] = useState(false);

  const reloadCoa = useCallback(() => {
    if (!propertyCode) return;
    setCoa({ data: [], loading: true, error: null });
    fetchBudgetCoaMonthly(propertyCode, {
      forwardOnly: true,
      bypassCache: true,
    }).then(({ data, error }) => {
      setCoa({
        data: Array.isArray(data) ? data : [],
        loading: false,
        error: error || null,
      });
    });
  }, [propertyCode]);

  const reloadItemized = useCallback(() => {
    if (!propertyCode) return;
    setItemized({ data: [], loading: true, error: null });
    fetchBudgetItemizedMonthly(propertyCode).then(({ data, error }) => {
      setItemized({
        data: Array.isArray(data) ? data : [],
        loading: false,
        error: error || null,
      });
    });
  }, [propertyCode]);

  const reloadHistory = useCallback(() => {
    if (!propertyCode) return;
    setHistory({ data: [], loading: true, error: null });
    fetchEntrataBudgetWritebackHistory(propertyCode).then(({ data, error }) => {
      setHistory({
        data: Array.isArray(data) ? data : [],
        loading: false,
        error: error || null,
      });
    });
  }, [propertyCode]);

  useEffect(() => {
    reloadCoa();
  }, [reloadCoa]);
  useEffect(() => {
    reloadItemized();
  }, [reloadItemized]);
  useEffect(() => {
    reloadHistory();
  }, [reloadHistory]);

  useEffect(() => {
    setIncludePriorMonths(false);
  }, [propertyCode]);

  const tabStrip = React.createElement(
    "div",
    {
      style: { display: "flex", gap: 0, borderBottom: `1px solid ${C.border}` },
    },
    ENTRATA_WB_TABS.map((t) =>
      React.createElement(
        "button",
        {
          key: t.key,
          type: "button",
          onClick: () => setTab(t.key),
          style: {
            padding: "10px 16px",
            background: "transparent",
            color: tab === t.key ? C.textPrimary : C.textSecondary,
            border: "none",
            borderBottom:
              tab === t.key ? `2px solid ${C.accent}` : "2px solid transparent",
            cursor: "pointer",
            fontSize: 13,
            fontWeight: tab === t.key ? 700 : 600,
            marginBottom: -1,
          },
        },
        t.label,
      ),
    ),
  );

  let panel;
  if (tab === "history") {
    panel = React.createElement(EntrataBudgetWritebackHistoryPanel, {
      state: history,
      propertyCode,
      onRetry: reloadHistory,
    });
  } else {
    panel = React.createElement(EntrataBudgetWritebackPreviewPanel, {
      state: coa,
      itemized,
      propertyCode,
      userProfile,
      includePriorMonths,
      onToggleIncludePriorMonths: setIncludePriorMonths,
      onPushResult: () => {
        reloadHistory();
      },
    });
  }

  return React.createElement(
    "div",
    { style: { display: "flex", flexDirection: "column", gap: 12 } },
    tabStrip,
    panel,
  );
}

