function ForcedPasswordChangeScreen({ userEmail, onComplete, onSignOut }) {
  const [newPw, setNewPw] = useState("");
  const [confirmPw, setConfirmPw] = useState("");
  const [status, setStatus] = useState("idle");
  const [msg, setMsg] = useState("");
  const [minPasswordLength, setMinPasswordLength] = useState(12);

  const signOutAction = useSignOutAction(onSignOut, { idleLabel: "Sign out" });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { policy } = await fetchSessionPolicy();
        if (cancelled) return;
        const n = Number(policy?.password_min_length);
        if (Number.isFinite(n) && n >= 8 && n <= 128) setMinPasswordLength(n);
      } catch {}
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const strength = React.useMemo(() => {
    if (!newPw) return { score: 0, label: "" };
    let s = 0;
    if (newPw.length >= 12) s++;
    if (/[A-Z]/.test(newPw)) s++;
    if (/[a-z]/.test(newPw)) s++;
    if (/[0-9]/.test(newPw)) s++;
    if (/[^A-Za-z0-9]/.test(newPw)) s++;
    return { score: s, label: s >= 5 ? "Strong" : s >= 3 ? "Medium" : "Weak" };
  }, [newPw]);

  const submit = async (e) => {
    e.preventDefault();
    setMsg("");
    if (newPw.length < minPasswordLength) {
      setStatus("error");
      setMsg(`Password must be at least ${minPasswordLength} characters.`);
      return;
    }
    if (newPw !== confirmPw) {
      setStatus("error");
      setMsg("Passwords don't match.");
      return;
    }
    setStatus("submitting");
    const { error } = await updatePassword({
      currentPassword: "",
      newPassword: newPw,
    });
    if (error) {
      setStatus("error");
      setMsg(error.message || "Failed to set password.");
      auditLog({
        action: AUDIT.auth.PASSWORD_CHANGED,
        outcome: "failure",
        metadata: { phase: "forced_temp_password_change" },
        errorMessage: error.message,
      }).catch(() => {});
      return;
    }
    auditLog({
      action: AUDIT.auth.PASSWORD_CHANGED,
      outcome: "success",
      metadata: { phase: "forced_temp_password_change" },
    }).catch(() => {});
    setStatus("success");
    setMsg("Password set. Loading your dashboard…");
    onComplete?.();
  };

  const bg = {
    minHeight: "100vh",
    background: C.bg,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: 24,
    fontFamily: "'Inter', -apple-system, sans-serif",
  };
  const card = {
    width: "100%",
    maxWidth: 440,
    background: C.cardBg,
    border: `1px solid ${C.border}`,
    borderRadius: 16,
    padding: "40px 36px",
    boxShadow: "var(--ds-shadow-modal)",
  };
  const label = {
    fontSize: 11,
    fontWeight: 700,
    color: C.textSecondary,
    textTransform: "uppercase",
    letterSpacing: 0.5,
    marginBottom: 6,
  };
  const input = {
    width: "100%",
    padding: "12px 14px",
    border: `1px solid ${C.inputBorder}`,
    borderRadius: 8,
    fontSize: 14,
    background: C.inputBg,
    color: C.textPrimary,
    outline: "none",
    boxSizing: "border-box",
  };
  const btn = {
    width: "100%",
    padding: "12px 16px",
    background:
      status === "submitting"
        ? alpha("var(--ds-accent-fill)", 50)
        : "var(--ds-accent-fill)",
    color: "var(--ds-accent-fill-text)",
    border: "none",
    borderRadius: 8,
    cursor: status === "submitting" ? "wait" : "pointer",
    fontWeight: 700,
    fontSize: 14,
    marginTop: 8,
  };
  const strengthColor =
    strength.score >= 5
      ? C.green
      : strength.score >= 3
        ? "var(--ds-warning-text)"
        : C.red;

  return React.createElement(
    "div",
    { style: bg },
    React.createElement(
      "form",
      { style: card, onSubmit: submit },
      React.createElement(
        "div",
        {
          style: {
            fontSize: 11,
            fontWeight: 700,
            color: C.accent,
            textTransform: "uppercase",
            letterSpacing: 0.8,
            marginBottom: 8,
          },
        },
        "One step left",
      ),
      React.createElement(
        "h1",
        {
          style: {
            fontSize: 22,
            fontWeight: 800,
            color: C.textPrimary,
            margin: "0 0 10px 0",
          },
        },
        "Choose your password",
      ),
      React.createElement(
        "p",
        {
          style: {
            fontSize: 14,
            color: C.textSecondary,
            lineHeight: 1.6,
            marginBottom: 20,
          },
        },
        "You signed in with a temporary password that someone on your team issued for you. " +
          "Set a password only you know to finish setting up your account.",
      ),
      userEmail &&
        React.createElement(
          "div",
          {
            style: {
              fontSize: 12,
              color: "var(--ds-text-tertiary)",
              marginBottom: 20,
            },
          },
          "Signed in as ",
          React.createElement(
            "span",
            { style: { color: C.textPrimary, fontWeight: 600 } },
            userEmail,
          ),
        ),
      React.createElement(
        "div",
        { style: { marginBottom: 14 } },
        React.createElement("div", { style: label }, "New password"),
        React.createElement("input", {
          type: "password",
          value: newPw,
          autoFocus: true,
          autoComplete: "new-password",
          onChange: (e) => setNewPw(e.target.value),
          placeholder: `At least ${minPasswordLength} characters`,
          style: input,
        }),
        newPw &&
          React.createElement(
            "div",
            {
              style: {
                marginTop: 6,
                fontSize: 11,
                fontWeight: 600,
                color: strengthColor,
              },
            },
            strength.label,
          ),
      ),
      React.createElement(
        "div",
        { style: { marginBottom: 6 } },
        React.createElement("div", { style: label }, "Confirm new password"),
        React.createElement("input", {
          type: "password",
          value: confirmPw,
          autoComplete: "new-password",
          onChange: (e) => setConfirmPw(e.target.value),
          placeholder: "Type it again",
          style: input,
        }),
      ),
      msg &&
        React.createElement(
          "div",
          {
            role: status === "error" ? "alert" : undefined,
            style: {
              marginTop: 10,
              fontSize: 13,
              color: status === "error" ? C.red : C.textSecondary,
              lineHeight: 1.5,
            },
          },
          msg,
        ),
      signOutAction.isFailed &&
        React.createElement(
          "div",
          {
            role: "alert",
            style: {
              marginTop: 10,
              fontSize: 12,
              color: C.red,
              lineHeight: 1.5,
            },
          },
          SIGN_OUT_FAILED_COPY,
        ),
      React.createElement(
        "button",
        {
          type: "submit",
          style: btn,
          disabled: status === "submitting" || status === "success",
        },
        status === "submitting"
          ? "Saving…"
          : status === "success"
            ? "Saved"
            : "Set password and continue",
      ),
      React.createElement(
        "button",
        {
          type: "button",
          style: {
            width: "100%",
            marginTop: 10,
            padding: "10px 16px",
            background: "transparent",
            color: C.textSecondary,
            border: "none",
            borderRadius: 8,
            cursor: "pointer",
            fontWeight: 600,
            fontSize: 13,
          },
          onClick: signOutAction.run,
          disabled: status === "submitting" || signOutAction.isPending,
        },
        signOutAction.label,
      ),
    ),
  );
}

function MfaStepUpModal({
  open,
  factorId,
  actionLabel,
  description,
  onVerified,
  onCancel,
}) {
  const [code, setCode] = useState("");
  const [status, setStatus] = useState("idle");
  const [msg, setMsg] = useState("");

  useEffect(() => {
    if (open) {
      setCode("");
      setStatus("idle");
      setMsg("");
    }
  }, [open]);

  if (!open) return null;

  async function handleVerify(e) {
    e?.preventDefault?.();
    if (!/^\d{6}$/.test(code)) {
      setStatus("error");
      setMsg("Enter the 6-digit code from your authenticator app.");
      return;
    }
    setStatus("submitting");
    setMsg("");
    const { ok, error } = await verifyStepUp({ factorId, code, actionLabel });
    if (!ok) {
      setStatus("error");
      setMsg(error?.message || "Code did not verify. Try again.");
      return;
    }
    setStatus("idle");
    onVerified?.();
  }

  const overlay = {
    position: "fixed",
    inset: 0,
    background: "var(--ds-scrim)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: 16,
    zIndex: 2100,
  };
  const panel = {
    width: "100%",
    maxWidth: 420,
    background: C.cardBg,
    border: `1px solid ${C.border}`,
    borderRadius: 12,
    padding: 24,
    boxShadow: "var(--ds-shadow-modal)",
    fontFamily: "'Inter', sans-serif",
  };
  const verifyDisabled = status === "submitting" || code.length !== 6;

  return (
    <div style={overlay}>
      <div style={panel}>
        <div style={{ marginBottom: 14 }}>
          <div
            style={{
              fontSize: 11,
              textTransform: "uppercase",
              letterSpacing: 1,
              color: "var(--ds-warning-text)",
              fontWeight: 600,
              marginBottom: 4,
            }}
          >
            Verification required
          </div>
          <h2
            style={{
              fontSize: 18,
              fontWeight: 700,
              color: C.textPrimary,
              margin: 0,
            }}
          >
            Confirm it's you
          </h2>
        </div>
        <p style={{ fontSize: 13, color: C.textSecondary, margin: "0 0 16px" }}>
          {description ||
            "This is a privileged action. Enter the 6-digit code from your authenticator app to continue."}
        </p>
        <form onSubmit={handleVerify}>
          <input
            type="text"
            inputMode="numeric"
            pattern="\d{6}"
            maxLength={6}
            autoFocus
            value={code}
            onChange={(e) =>
              setCode(e.target.value.replace(/\D/g, "").slice(0, 6))
            }
            placeholder="000000"
            style={{
              width: "100%",
              boxSizing: "border-box",
              padding: "8px 10px",
              background: C.inputBg,
              border: `1px solid ${C.inputBorder}`,
              color: C.textPrimary,
              borderRadius: 6,
              fontSize: 16,
              textAlign: "center",
              letterSpacing: "0.4em",
              fontFamily: "ui-monospace, monospace",
              outline: "none",
            }}
          />
          {msg && (
            <p
              style={{
                marginTop: 10,
                marginBottom: 0,
                fontSize: 12,
                color: status === "error" ? C.red : C.textSecondary,
              }}
            >
              {msg}
            </p>
          )}
          <div
            style={{
              marginTop: 18,
              display: "flex",
              gap: 8,
              justifyContent: "flex-end",
            }}
          >
            <button
              type="button"
              onClick={onCancel}
              disabled={status === "submitting"}
              style={{
                background: "transparent",
                border: `1px solid ${C.border}`,
                color: C.textSecondary,
                borderRadius: 6,
                padding: "7px 14px",
                fontSize: 13,
                cursor: status === "submitting" ? "default" : "pointer",
                opacity: status === "submitting" ? 0.5 : 1,
              }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={verifyDisabled}
              style={{
                background: verifyDisabled
                  ? alpha("var(--ds-accent-fill)", 50)
                  : "var(--ds-accent-fill)",
                color: "var(--ds-accent-fill-text)",
                border: "none",
                borderRadius: 6,
                padding: "7px 14px",
                fontWeight: 600,
                fontSize: 13,
                cursor: verifyDisabled ? "default" : "pointer",
              }}
            >
              {status === "submitting" ? "Verifying…" : "Verify & continue"}
            </button>
          </div>
        </form>
        <p
          style={{
            marginTop: 16,
            marginBottom: 0,
            fontSize: 11,
            color: "var(--ds-text-tertiary)",
            textAlign: "center",
          }}
        >
          Once verified, you won't be prompted again for 15 minutes.
        </p>
      </div>
    </div>
  );
}

function useStepUp() {
  const [modalState, setModalState] = useState({
    open: false,
    factorId: null,
    actionLabel: "",
    description: "",
  });
  const resolverRef = React.useRef(null);

  const requireStepUp = React.useCallback(
    async ({ actionLabel, description } = {}) => {
      const { required, factorId } = await stepUpRequired();
      if (!required) return true;
      return new Promise((resolve) => {
        resolverRef.current = resolve;
        setModalState({ open: true, factorId, actionLabel, description });
      });
    },
    [],
  );

  const onVerified = React.useCallback(() => {
    setModalState((s) => ({ ...s, open: false }));
    const r = resolverRef.current;
    resolverRef.current = null;
    r?.(true);
  }, []);

  const onCancel = React.useCallback(() => {
    setModalState((s) => ({ ...s, open: false }));
    const r = resolverRef.current;
    resolverRef.current = null;
    r?.(false);
  }, []);

  const modal = (
    <MfaStepUpModal
      open={modalState.open}
      factorId={modalState.factorId}
      actionLabel={modalState.actionLabel}
      description={modalState.description}
      onVerified={onVerified}
      onCancel={onCancel}
    />
  );

  return { requireStepUp, modal };
}

function ChangePasswordModal({ onClose }) {
  const stepUp = useStepUp();
  const [currentPw, setCurrentPw] = useState("");
  const [newPw, setNewPw] = useState("");
  const [confirmPw, setConfirmPw] = useState("");
  const [status, setStatus] = useState("idle");
  const [msg, setMsg] = useState("");
  const [minPasswordLength, setMinPasswordLength] = useState(12);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { policy } = await fetchSessionPolicy();
        if (cancelled) return;
        const n = Number(policy?.password_min_length);
        if (Number.isFinite(n) && n >= 8 && n <= 128) setMinPasswordLength(n);
      } catch {}
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const strength = React.useMemo(() => {
    if (!newPw) return { score: 0, label: "" };
    let score = 0;
    if (newPw.length >= 12) score++;
    if (/[A-Z]/.test(newPw)) score++;
    if (/[a-z]/.test(newPw)) score++;
    if (/[0-9]/.test(newPw)) score++;
    if (/[^A-Za-z0-9]/.test(newPw)) score++;
    const label = score >= 5 ? "Strong" : score >= 3 ? "Medium" : "Weak";
    return { score, label };
  }, [newPw]);

  const submit = async (e) => {
    e.preventDefault();
    setMsg("");
    if (newPw !== confirmPw) {
      setStatus("error");
      setMsg("New passwords don't match.");
      return;
    }
    if (newPw.length < minPasswordLength) {
      setStatus("error");
      setMsg(`Password must be at least ${minPasswordLength} characters.`);
      return;
    }
    if (newPw === currentPw) {
      setStatus("error");
      setMsg("New password must differ from current.");
      return;
    }
    const ok = await stepUp.requireStepUp({
      actionLabel: "auth.password.changed",
      description:
        "You're about to change your account password. Confirm with your 6-digit code.",
    });
    if (!ok) return;
    setStatus("submitting");
    const { error } = await updatePassword({
      currentPassword: currentPw,
      newPassword: newPw,
    });
    if (error) {
      setStatus("error");
      setMsg(error.message || "Failed to update password.");
      return;
    }
    setStatus("success");
    setMsg("Password updated. You can continue working.");
  };

  const overlay = {
    position: "fixed",
    inset: 0,
    background: "var(--ds-scrim)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    zIndex: 2000,
  };
  const card = {
    width: 440,
    background: C.cardBg,
    borderRadius: 14,
    border: `1px solid ${C.border}`,
    boxShadow: "var(--ds-shadow-modal)",
    padding: 28,
    fontFamily: "'Inter', sans-serif",
  };
  const input = {
    width: "100%",
    padding: "10px 12px",
    border: `1px solid ${C.inputBorder}`,
    borderRadius: 8,
    fontSize: 14,
    fontFamily: "inherit",
    background: C.inputBg,
    color: C.textPrimary,
    outline: "none",
    marginTop: 6,
    boxSizing: "border-box",
  };
  const label = {
    fontSize: 12,
    fontWeight: 600,
    color: C.textSecondary,
    textTransform: "uppercase",
    letterSpacing: 0.4,
  };
  const btnPrimary = {
    flex: 1,
    padding: "10px 16px",
    background: "var(--ds-accent-fill)",
    color: "var(--ds-accent-fill-text)",
    border: "none",
    borderRadius: 8,
    cursor: status === "submitting" ? "wait" : "pointer",
    fontWeight: 600,
    fontSize: 14,
  };
  const btnGhost = {
    padding: "10px 16px",
    background: C.subtleBg,
    color: C.textSecondary,
    border: `1px solid ${C.border}`,
    borderRadius: 8,
    cursor: "pointer",
    fontWeight: 600,
    fontSize: 14,
  };
  const strengthColor =
    strength.score >= 5
      ? C.green
      : strength.score >= 3
        ? "var(--ds-warning-text)"
        : C.red;

  return React.createElement(
    React.Fragment,
    null,
    stepUp.modal,
    React.createElement(
      "div",
      { style: overlay, onClick: onClose },
      React.createElement(
        "div",
        { style: card, onClick: (e) => e.stopPropagation() },
        React.createElement(
          "div",
          {
            style: {
              fontSize: 18,
              fontWeight: 700,
              color: C.textPrimary,
              marginBottom: 4,
            },
          },
          "Change Password",
        ),
        React.createElement(
          "div",
          { style: { fontSize: 13, color: C.textSecondary, marginBottom: 20 } },
          "For security, you'll need to re-enter your current password.",
        ),
        status === "success"
          ? React.createElement(
              "div",
              null,
              React.createElement(
                "div",
                {
                  style: {
                    padding: "12px 14px",
                    background: "var(--ds-success-bg)",
                    border: `1px solid ${C.green}`,
                    borderRadius: 8,
                    color: "var(--ds-success-text)",
                    fontSize: 13,
                    marginBottom: 16,
                  },
                },
                msg,
              ),
              React.createElement(
                "button",
                { style: btnPrimary, onClick: onClose },
                "Done",
              ),
            )
          : React.createElement(
              "form",
              { onSubmit: submit },
              React.createElement(
                "div",
                { style: { marginBottom: 14 } },
                React.createElement(
                  "div",
                  { style: label },
                  "Current password",
                ),
                React.createElement("input", {
                  type: "password",
                  value: currentPw,
                  onChange: (e) => setCurrentPw(e.target.value),
                  style: input,
                  autoFocus: true,
                  autoComplete: "current-password",
                }),
              ),
              React.createElement(
                "div",
                { style: { marginBottom: 6 } },
                React.createElement("div", { style: label }, "New password"),
                React.createElement("input", {
                  type: "password",
                  value: newPw,
                  onChange: (e) => setNewPw(e.target.value),
                  style: input,
                  autoComplete: "new-password",
                }),
              ),
              newPw &&
                React.createElement(
                  "div",
                  {
                    style: {
                      fontSize: 11,
                      color: strengthColor,
                      marginBottom: 14,
                      fontWeight: 600,
                    },
                  },
                  `Strength: ${strength.label} — needs ≥12 chars, upper/lower/number/symbol`,
                ),
              React.createElement(
                "div",
                { style: { marginBottom: 18 } },
                React.createElement(
                  "div",
                  { style: label },
                  "Confirm new password",
                ),
                React.createElement("input", {
                  type: "password",
                  value: confirmPw,
                  onChange: (e) => setConfirmPw(e.target.value),
                  style: input,
                  autoComplete: "new-password",
                }),
              ),
              status === "error" &&
                msg &&
                React.createElement(
                  "div",
                  {
                    style: {
                      padding: "10px 12px",
                      background: alpha(C.red, 10),
                      border: `1px solid ${alpha(C.red, 30)}`,
                      borderRadius: 8,
                      color: C.red,
                      fontSize: 13,
                      marginBottom: 14,
                    },
                  },
                  msg,
                ),
              React.createElement(
                "div",
                { style: { display: "flex", gap: 10 } },
                React.createElement(
                  "button",
                  {
                    type: "button",
                    style: btnGhost,
                    onClick: onClose,
                    disabled: status === "submitting",
                  },
                  "Cancel",
                ),
                React.createElement(
                  "button",
                  {
                    type: "submit",
                    style: btnPrimary,
                    disabled: status === "submitting",
                  },
                  status === "submitting" ? "Updating…" : "Update Password",
                ),
              ),
            ),
      ),
    ),
  );
}

