function AdminArchitecturePage() {
  const [selectedNode, setSelectedNode] = useState(null);
  const [viewMode, setViewMode] = useState("map");
  const [filterCategory, setFilterCategory] = useState("all");
  const [hoveredNode, setHoveredNode] = useState(null);
  const [hoveredFlow, setHoveredFlow] = useState(null);

  const categories = ["all", "source", "data", "module", "output"];
  const categoryLabels = {
    all: "All Layers",
    source: "Data Sources",
    data: "Core Data",
    module: "Platform Modules",
    output: "Outputs & Deliverables",
  };

  const selectedModule = PLATFORM_MODULES.find((m) => m.id === selectedNode);
  const nodeFlows = selectedNode
    ? {
        inbound: DATA_FLOWS.filter((f) => f.to === selectedNode),
        outbound: DATA_FLOWS.filter((f) => f.from === selectedNode),
      }
    : null;

  const getTypeColor = (type) => {
    switch (type) {
      case "source":
        return {
          bg: "color-mix(in srgb, var(--ds-accent) 12.5%, transparent)",
          border: "var(--ds-accent)",
          text: "var(--ds-accent)",
        };
      case "data":
        return {
          bg: "color-mix(in srgb, var(--ds-neutral-text) 12.5%, transparent)",
          border: "var(--ds-neutral-text)",
          text: "var(--ds-neutral-text)",
        };
      case "module":
        return {
          bg: "color-mix(in srgb, var(--ds-success-text) 12.5%, transparent)",
          border: "var(--ds-success-text)",
          text: "var(--ds-success-text)",
        };
      case "output":
        return {
          bg: "color-mix(in srgb, var(--ds-ai) 12.5%, transparent)",
          border: "var(--ds-ai)",
          text: "var(--ds-ai)",
        };
      default:
        return { bg: C.subtleBg, border: C.border, text: C.textPrimary };
    }
  };

  const getFlowColor = (type) => {
    switch (type) {
      case "ingest":
        return "var(--ds-accent)";
      case "process":
        return "var(--ds-neutral-text)";
      case "cross":
        return "var(--ds-success-text)";
      case "output":
        return "var(--ds-ai)";
      default:
        return C.textSecondary;
    }
  };

  const filteredModules =
    filterCategory === "all"
      ? PLATFORM_MODULES
      : PLATFORM_MODULES.filter((m) => m.type === filterCategory);

  const sourceNodes = PLATFORM_MODULES.filter((m) => m.type === "source");
  const dataNodes = PLATFORM_MODULES.filter((m) => m.type === "data");
  const moduleNodes = PLATFORM_MODULES.filter((m) => m.type === "module");
  const outputNodes = PLATFORM_MODULES.filter((m) => m.type === "output");

  const renderNodeCard = (node, size = "normal") => {
    const colors = getTypeColor(node.type);
    const isSelected = selectedNode === node.id;
    const isHovered = hoveredNode === node.id;
    const isHighlighted =
      hoveredFlow &&
      (hoveredFlow.from === node.id || hoveredFlow.to === node.id);
    const inboundCount = DATA_FLOWS.filter((f) => f.to === node.id).length;
    const outboundCount = DATA_FLOWS.filter((f) => f.from === node.id).length;

    return (
      <div
        key={node.id}
        onClick={() => setSelectedNode(isSelected ? null : node.id)}
        onMouseEnter={() => setHoveredNode(node.id)}
        onMouseLeave={() => setHoveredNode(null)}
        style={{
          padding: size === "compact" ? "10px 12px" : "14px 16px",
          borderRadius: 10,
          border: `2px solid ${isSelected ? colors.border : isHighlighted ? colors.border : C.border}`,
          background: isSelected
            ? colors.bg
            : isHovered
              ? `${colors.border}08`
              : C.cardBg,
          cursor: "pointer",
          transition: "all 0.2s",
          boxShadow: isSelected ? `0 4px 16px ${colors.border}20` : "none",
          position: "relative",
          minWidth: size === "compact" ? 120 : 150,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            marginBottom: 4,
          }}
        >
          <div
            style={{
              width: 8,
              height: 8,
              borderRadius: "50%",
              background:
                node.status === "connected"
                  ? "var(--ds-success-text)"
                  : node.status === "active"
                    ? "var(--ds-accent)"
                    : C.textSecondary,
            }}
          />
          <span
            style={{
              fontSize: size === "compact" ? 11 : 12,
              fontWeight: 700,
              color: colors.text,
            }}
          >
            {node.label}
          </span>
        </div>
        <div
          style={{
            fontSize: 10,
            color: C.textSecondary,
            lineHeight: 1.4,
            marginBottom: 6,
          }}
        >
          {node.category}
        </div>
        <div
          style={{
            display: "flex",
            gap: 8,
            fontSize: 9,
            color: C.textSecondary,
          }}
        >
          {inboundCount > 0 && (
            <span
              style={{
                background: C.subtleBg,
                padding: "2px 6px",
                borderRadius: 4,
              }}
            >
              ← {inboundCount} in
            </span>
          )}
          {outboundCount > 0 && (
            <span
              style={{
                background: C.subtleBg,
                padding: "2px 6px",
                borderRadius: 4,
              }}
            >
              {outboundCount} out →
            </span>
          )}
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <div>
          <h2
            style={{
              fontSize: 22,
              fontWeight: 800,
              color: C.textPrimary,
              margin: 0,
            }}
          >
            Platform Architecture
          </h2>
          <p
            style={{ fontSize: 13, color: C.textSecondary, margin: "4px 0 0" }}
          >
            Data flows, dependencies, and system connections across{" "}
            {CONFIG.platform}
          </p>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {["map", "flows", "audit"].map((mode) => (
            <button
              key={mode}
              onClick={() => setViewMode(mode)}
              style={{
                padding: "8px 16px",
                borderRadius: 8,
                fontSize: 12,
                fontWeight: 600,
                border: viewMode === mode ? "none" : `1px solid ${C.border}`,
                background: viewMode === mode ? C.gold : "transparent",
                color: viewMode === mode ? C.navy : C.textSecondary,
                cursor: "pointer",
                textTransform: "capitalize",
              }}
            >
              {mode === "map"
                ? "Architecture Map"
                : mode === "flows"
                  ? "Data Flows"
                  : "Data Audit Log"}
            </button>
          ))}
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(5, 1fr)",
          gap: 12,
        }}
      >
        <KPI
          label="Data Sources"
          value="10"
          sub="External Systems"
          color="blue"
        />
        <KPI
          label="Core Data Tables"
          value="6"
          sub="Master Records"
          color="gold"
        />
        <KPI
          label="Platform Modules"
          value="11"
          sub="Functional Areas"
          color="green"
        />
        <KPI
          label="Data Flows"
          value={String(DATA_FLOWS.length)}
          sub="Active Connections"
          color="purple"
        />
        <KPI
          label="Output Channels"
          value="5"
          sub="Deliverable Types"
          color="blue"
        />
      </div>

      {viewMode === "map" && (
        <div style={{ display: "flex", gap: 20 }}>
          <div style={{ flex: 1 }}>
            <SectionCard
              title="Layer 1 — External Data Sources"
              subtitle="Integrations feeding into the platform"
            >
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(5, 1fr)",
                  gap: 10,
                }}
              >
                {sourceNodes.map((n) => renderNodeCard(n, "compact"))}
              </div>
            </SectionCard>

            <div
              style={{
                textAlign: "center",
                padding: "8px 0",
                color: C.textSecondary,
                fontSize: 20,
                letterSpacing: 8,
              }}
            >
              ↓ ↓ ↓ ↓ ↓ ↓
            </div>

            <SectionCard
              title="Layer 2 — Core Data Layer"
              subtitle="Normalized master data powering all modules"
            >
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(3, 1fr)",
                  gap: 12,
                }}
              >
                {dataNodes.map((n) => renderNodeCard(n))}
              </div>
            </SectionCard>

            <div
              style={{
                textAlign: "center",
                padding: "8px 0",
                color: C.textSecondary,
                fontSize: 20,
                letterSpacing: 8,
              }}
            >
              ↓ ↓ ↓ ↓ ↓ ↓
            </div>

            <SectionCard
              title="Layer 3 — Platform Modules"
              subtitle="Functional areas processing and displaying data"
            >
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(4, 1fr)",
                  gap: 12,
                }}
              >
                {moduleNodes.map((n) => renderNodeCard(n))}
              </div>
            </SectionCard>

            <div
              style={{
                textAlign: "center",
                padding: "8px 0",
                color: C.textSecondary,
                fontSize: 20,
                letterSpacing: 8,
              }}
            >
              ↓ ↓ ↓ ↓ ↓ ↓
            </div>

            <SectionCard
              title="Layer 4 — Outputs & Deliverables"
              subtitle="Reports, distributions, and external deliverables"
            >
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(5, 1fr)",
                  gap: 10,
                }}
              >
                {outputNodes.map((n) => renderNodeCard(n, "compact"))}
              </div>
            </SectionCard>
          </div>

          {selectedModule && (
            <div style={{ width: 340, flexShrink: 0 }}>
              <div
                style={{
                  background: C.cardBg,
                  border: `1px solid ${C.border}`,
                  borderRadius: 12,
                  padding: "20px",
                  position: "sticky",
                  top: 20,
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10,
                    marginBottom: 12,
                  }}
                >
                  <div
                    style={{
                      width: 12,
                      height: 12,
                      borderRadius: "50%",
                      background: getTypeColor(selectedModule.type).border,
                    }}
                  />
                  <span
                    style={{
                      fontSize: 16,
                      fontWeight: 800,
                      color: C.textPrimary,
                    }}
                  >
                    {selectedModule.label}
                  </span>
                </div>
                <Badge
                  text={selectedModule.type.toUpperCase()}
                  color={
                    selectedModule.type === "source"
                      ? "blue"
                      : selectedModule.type === "data"
                        ? "gold"
                        : selectedModule.type === "module"
                          ? "green"
                          : "purple"
                  }
                />
                <div
                  style={{
                    fontSize: 12,
                    color: C.textSecondary,
                    margin: "12px 0",
                    lineHeight: 1.6,
                  }}
                >
                  {selectedModule.desc}
                </div>
                <div
                  style={{
                    fontSize: 11,
                    color: C.textSecondary,
                    marginBottom: 4,
                  }}
                >
                  <strong>Category:</strong> {selectedModule.category}
                </div>
                <div
                  style={{
                    fontSize: 11,
                    color: C.textSecondary,
                    marginBottom: 12,
                  }}
                >
                  <strong>Status:</strong>{" "}
                  <span
                    style={{ color: "var(--ds-success-text)", fontWeight: 600 }}
                  >
                    {selectedModule.status}
                  </span>
                </div>

                {nodeFlows.inbound.length > 0 && (
                  <div style={{ marginBottom: 16 }}>
                    <div
                      style={{
                        fontSize: 11,
                        fontWeight: 700,
                        color: C.textSecondary,
                        textTransform: "uppercase",
                        letterSpacing: 0.5,
                        marginBottom: 8,
                      }}
                    >
                      Precedents ({nodeFlows.inbound.length})
                    </div>
                    {nodeFlows.inbound.map((flow, idx) => {
                      const source = PLATFORM_MODULES.find(
                        (m) => m.id === flow.from,
                      );
                      return (
                        <div
                          key={idx}
                          onClick={() => setSelectedNode(flow.from)}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 8,
                            padding: "8px 10px",
                            borderRadius: 6,
                            marginBottom: 4,
                            background: C.subtleBg,
                            cursor: "pointer",
                            transition: "all 0.15s",
                            border: `1px solid transparent`,
                          }}
                        >
                          <div
                            style={{
                              width: 6,
                              height: 6,
                              borderRadius: "50%",
                              background: getFlowColor(flow.type),
                            }}
                          />
                          <div style={{ flex: 1 }}>
                            <div
                              style={{
                                fontSize: 11,
                                fontWeight: 600,
                                color: C.textPrimary,
                              }}
                            >
                              {source?.label}
                            </div>
                            <div
                              style={{ fontSize: 10, color: C.textSecondary }}
                            >
                              {flow.label}
                            </div>
                          </div>
                          <span
                            style={{ fontSize: 10, color: C.textSecondary }}
                          >
                            ←
                          </span>
                        </div>
                      );
                    })}
                  </div>
                )}

                {nodeFlows.outbound.length > 0 && (
                  <div>
                    <div
                      style={{
                        fontSize: 11,
                        fontWeight: 700,
                        color: C.textSecondary,
                        textTransform: "uppercase",
                        letterSpacing: 0.5,
                        marginBottom: 8,
                      }}
                    >
                      Dependents ({nodeFlows.outbound.length})
                    </div>
                    {nodeFlows.outbound.map((flow, idx) => {
                      const target = PLATFORM_MODULES.find(
                        (m) => m.id === flow.to,
                      );
                      return (
                        <div
                          key={idx}
                          onClick={() => setSelectedNode(flow.to)}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 8,
                            padding: "8px 10px",
                            borderRadius: 6,
                            marginBottom: 4,
                            background: C.subtleBg,
                            cursor: "pointer",
                            transition: "all 0.15s",
                            border: `1px solid transparent`,
                          }}
                        >
                          <div
                            style={{
                              width: 6,
                              height: 6,
                              borderRadius: "50%",
                              background: getFlowColor(flow.type),
                            }}
                          />
                          <div style={{ flex: 1 }}>
                            <div
                              style={{
                                fontSize: 11,
                                fontWeight: 600,
                                color: C.textPrimary,
                              }}
                            >
                              {target?.label}
                            </div>
                            <div
                              style={{ fontSize: 10, color: C.textSecondary }}
                            >
                              {flow.label}
                            </div>
                          </div>
                          <span
                            style={{ fontSize: 10, color: C.textSecondary }}
                          >
                            →
                          </span>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      {viewMode === "flows" && (
        <SectionCard
          title="All Data Flows"
          subtitle={`${DATA_FLOWS.length} active connections across the platform`}
        >
          <div
            style={{
              display: "flex",
              gap: 8,
              marginBottom: 16,
              flexWrap: "wrap",
            }}
          >
            {["all", "ingest", "process", "cross", "output"].map((type) => (
              <button
                key={type}
                onClick={() => setFilterCategory(type)}
                style={{
                  padding: "6px 14px",
                  borderRadius: 20,
                  fontSize: 11,
                  fontWeight: 600,
                  border:
                    filterCategory === type ? "none" : `1px solid ${C.border}`,
                  background: filterCategory === type ? C.gold : "transparent",
                  color: filterCategory === type ? C.navy : C.textSecondary,
                  cursor: "pointer",
                }}
              >
                {type === "all"
                  ? "All Flows"
                  : type === "ingest"
                    ? "Source → Data"
                    : type === "process"
                      ? "Data → Module"
                      : type === "cross"
                        ? "Cross-Module"
                        : "Module → Output"}
              </button>
            ))}
          </div>
          <MiniTable
            headers={["Source", "Target", "Data Flow", "Type", "Status"]}
            rows={(filterCategory === "all"
              ? DATA_FLOWS
              : DATA_FLOWS.filter((f) => f.type === filterCategory)
            ).map((flow) => {
              const from = PLATFORM_MODULES.find((m) => m.id === flow.from);
              const to = PLATFORM_MODULES.find((m) => m.id === flow.to);
              return [
                from?.label || flow.from,
                to?.label || flow.to,
                flow.label,
                flow.type.charAt(0).toUpperCase() + flow.type.slice(1),
                "Active",
              ];
            })}
          />
        </SectionCard>
      )}

      {viewMode === "audit" && (
        <SectionCard
          title="Data Audit Log"
          subtitle="Recent data operations, syncs, and transformations"
        >
          <MiniTable
            headers={[
              "Timestamp",
              "Module",
              "Action",
              "User",
              "Detail",
              "Status",
            ]}
            rows={AUDIT_LOG_ENTRIES.map((e) => [
              e.timestamp.split(" ")[1].slice(0, 5) +
                " " +
                e.timestamp.split(" ")[0].slice(5),
              e.module,
              e.action,
              e.user,
              e.detail.length > 60 ? e.detail.slice(0, 57) + "..." : e.detail,
              e.status === "success" ? "✓ Success" : "⚠ Warning",
            ])}
          />
        </SectionCard>
      )}
    </div>
  );
}

