                  doc: "📘",
                  docx: "📘",
                  xls: "📗",
                  xlsx: "📗",
                  ppt: "📙",
                  pptx: "📙",
                  jpg: "🖼",
                  jpeg: "🖼",
                  png: "🖼",
                  gif: "🖼",
                  zip: "📦",
                  csv: "📊",
                  txt: "📄",
