function ScheduleMeetingFromTemplate({ template, onScheduled }) {
  const [busy, setBusy] = React.useState(false);
  const [msg, setMsg] = React.useState(null);
  const defaultDate = (() => {
    const d = new Date();
    d.setDate(d.getDate() + (d.getDay() === 5 ? 3 : d.getDay() === 6 ? 2 : 1));
    d.setHours(10, 0, 0, 0);
    return d.toISOString().slice(0, 16);
  })();
  const [when, setWhen] = React.useState(defaultDate);

  const handleSchedule = async () => {
    setBusy(true);
    setMsg(null);
    try {
      const startsAt = new Date(when).toISOString();
      const endsAt = new Date(
        new Date(when).getTime() + (template.duration || 60) * 60 * 1000,
      ).toISOString();
      const { meeting, error } = await sbCreateMeeting({
        title: template.name,
        meetingType: template.type || template.name,
        templateId: template.id,
        startsAt,
        endsAt,
        isVirtual: true,
        attendees: (template.defaultAttendees || []).map((name) => ({
          name,
          status: "invited",
        })),
        agenda: (template.agenda || []).map((item, i) => ({
          order: i + 1,
          item,
        })),
      });
      if (error) {
        setMsg({
          kind: "error",
          text: "Failed to schedule: " + (error.message || "unknown error"),
        });
      } else {
        setMsg({
          kind: "success",
          text: "Meeting scheduled — id " + meeting.id.slice(0, 8),
        });
        setTimeout(() => onScheduled?.(), 1200);
      }
    } catch (err) {
      setMsg({ kind: "error", text: err.message });
    }
    setBusy(false);
  };

  return React.createElement(
    "div",
    {
      style: {
        marginTop: 18,
        padding: 14,
        borderRadius: 10,
        background: C.subtleBg,
        border: `1px solid ${C.border}`,
        display: "flex",
        flexDirection: "column",
        gap: 10,
      },
    },
    React.createElement(
      "div",
      { style: { fontSize: 12, fontWeight: 700, color: C.textPrimary } },
      "Schedule This Meeting",
    ),
    React.createElement(
      "div",
      {
        style: {
          display: "flex",
          gap: 10,
          alignItems: "center",
          flexWrap: "wrap",
        },
      },
      React.createElement("input", {
        type: "datetime-local",
        value: when,
        onChange: (e) => setWhen(e.target.value),
        style: {
          padding: "8px 10px",
          borderRadius: 6,
          border: `1px solid ${C.border}`,
          fontSize: 12,
          color: C.textPrimary,
          background: C.white,
        },
      }),
      React.createElement(
        "button",
        {
          onClick: handleSchedule,
          disabled: busy,
          style: {
            padding: "8px 18px",
            borderRadius: 6,
            border: "none",
            background: busy ? C.border : C.green,
            color: "#fff",
            cursor: busy ? "not-allowed" : "pointer",
            fontSize: 12,
            fontWeight: 700,
          },
        },
        busy ? "Scheduling…" : "Schedule",
      ),
    ),
    msg &&
      React.createElement(
        "div",
        {
          style: {
            fontSize: 11,
            padding: "6px 10px",
            borderRadius: 6,
            background:
              msg.kind === "success"
                ? "var(--ds-success-bg)"
                : "var(--ds-danger-bg)",
            color:
              msg.kind === "success"
                ? "var(--ds-success-text)"
                : "var(--ds-danger-text)",
          },
        },
        msg.text,
      ),
  );
}

