function DealRoomPage() {
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [docFilter, setDocFilter] = useState("all");

  if (selectedRoom) {
    const room = selectedRoom;
    const categories = [...new Set(room.documents.map((d) => d.category))];
    const filteredDocs =
      docFilter === "all"
        ? room.documents
        : room.documents.filter((d) => d.category === docFilter);

    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        <button
          onClick={() => setSelectedRoom(null)}
          style={{
            background: "none",
            border: "none",
            cursor: "pointer",
            color: C.accent,
            fontSize: 12,
            fontWeight: 600,
            textAlign: "left",
            padding: 0,
          }}
        >
          ← Back to Deal Rooms
        </button>

        <div
          style={{
            padding: 20,
            borderRadius: 12,
            background: `linear-gradient(135deg, ${alpha(C.navy, 6.3)}, ${alpha(C.accent, 2.4)})`,
            border: `1px solid ${alpha(C.accent, 12.5)}`,
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "start",
            }}
          >
            <div>
              <div
                style={{ fontSize: 22, fontWeight: 800, color: C.textPrimary }}
              >
                {room.dealName}
              </div>
              <div
                style={{ fontSize: 12, color: C.textSecondary, marginTop: 4 }}
              >
                Phase: {room.phase} · Last activity: {room.lastActivity}
              </div>
            </div>
            <Badge text={room.status} color="green" />
          </div>
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: 12,
          }}
        >
          {[
            {
              label: "Documents",
              value: room.documents.length,
              color: C.accent,
            },
            {
              label: "DD Complete",
              value: `${room.ddItems.complete}/${room.ddItems.total}`,
              color: C.green,
            },
            {
              label: "In Progress",
              value: room.ddItems.inProgress,
              color: C.amber,
            },
            {
              label: "Not Started",
              value: room.ddItems.notStarted,
              color: C.red,
            },
          ].map((s, i) => (
            <div
              key={i}
              style={{
                padding: "14px 16px",
                borderRadius: 10,
                background: C.cardBg,
                border: `1px solid ${C.border}`,
                textAlign: "center",
              }}
            >
              <div style={{ fontSize: 22, fontWeight: 800, color: s.color }}>
                {s.value}
              </div>
              <div
                style={{
                  fontSize: 10,
                  color: C.textSecondary,
                  fontWeight: 600,
                }}
              >
                {s.label}
              </div>
            </div>
          ))}
        </div>

        <SectionCard title="Deal Timeline">
          <div style={{ display: "flex", gap: 0, alignItems: "center" }}>
            {room.timeline.map((t, i) => (
              <div
                key={i}
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  position: "relative",
                }}
              >
                {i > 0 && (
                  <div
                    style={{
                      position: "absolute",
                      left: "-50%",
                      top: 10,
                      width: "100%",
                      height: 2,
                      background: t.status === "complete" ? C.green : C.border,
                      zIndex: 0,
                    }}
                  />
                )}
                <div
                  style={{
                    width: 20,
                    height: 20,
                    borderRadius: "50%",
                    background:
                      t.status === "complete"
                        ? C.green
                        : t.status === "upcoming"
                          ? C.amber
                          : C.subtleBg,
                    border: `2px solid ${t.status === "complete" ? C.green : t.status === "upcoming" ? C.amber : C.border}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 10,
                    color: "#fff",
                    zIndex: 1,
                    position: "relative",
                  }}
                >
                  {t.status === "complete" ? "✓" : ""}
                </div>
                <div
                  style={{
                    fontSize: 9,
                    fontWeight: 600,
                    color: t.status === "upcoming" ? C.amber : C.textSecondary,
                    marginTop: 6,
                    textAlign: "center",
                  }}
                >
                  {t.event}
                </div>
                <div style={{ fontSize: 8, color: C.textSecondary }}>
                  {t.date}
                </div>
              </div>
            ))}
          </div>
        </SectionCard>

        <SectionCard
          title="Document Repository"
          subtitle={`${room.documents.length} files`}
        >
          <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
            <button
              onClick={() => setDocFilter("all")}
              style={{
                padding: "4px 10px",
                borderRadius: 16,
                fontSize: 10,
                fontWeight: 600,
                cursor: "pointer",
                background:
                  docFilter === "all" ? "var(--ds-accent-fill)" : C.subtleBg,
                color: docFilter === "all" ? "#fff" : C.textSecondary,
                border: `1px solid ${docFilter === "all" ? "var(--ds-accent-fill)" : C.border}`,
              }}
            >
              All
            </button>
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setDocFilter(cat)}
                style={{
                  padding: "4px 10px",
                  borderRadius: 16,
                  fontSize: 10,
                  fontWeight: 600,
                  cursor: "pointer",
                  background:
                    docFilter === cat ? "var(--ds-accent-fill)" : C.subtleBg,
                  color: docFilter === cat ? "#fff" : C.textSecondary,
                  border: `1px solid ${docFilter === cat ? "var(--ds-accent-fill)" : C.border}`,
                }}
              >
                {cat}
              </button>
            ))}
          </div>
          {filteredDocs.map((doc, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 12,
                padding: "10px 12px",
                borderRadius: 8,
                background: i % 2 === 0 ? C.subtleBg : "transparent",
                marginBottom: 2,
              }}
            >
              <span style={{ fontSize: 16 }}>
                {doc.type === "PDF" ? "📄" : doc.type === "XLSX" ? "📊" : "📁"}
              </span>
              <div style={{ flex: 1 }}>
                <div
                  style={{
                    fontSize: 12,
                    fontWeight: 600,
                    color: C.textPrimary,
                  }}
                >
                  {doc.name}
                </div>
                <div style={{ fontSize: 10, color: C.textSecondary }}>
                  {doc.type} · {doc.size} · {doc.uploaded}
                </div>
              </div>
              <Badge
                text={doc.status}
                color={
                  doc.status === "final"
                    ? "green"
                    : doc.status === "review"
                      ? "amber"
                      : "gray"
                }
              />
              <Badge text={doc.category} color="blue" />
            </div>
          ))}
        </SectionCard>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div>
        <h2
          style={{
            fontSize: 22,
            fontWeight: 800,
            color: C.textPrimary,
            margin: 0,
          }}
        >
          Virtual Deal Rooms
        </h2>
        <p style={{ fontSize: 13, color: C.textSecondary, margin: "4px 0 0" }}>
          Secure data rooms for acquisitions and dispositions — documents,
          timelines, DD tracking, and team collaboration
        </p>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        {DEAL_ROOMS.map((room) => (
          <div
            key={room.id}
            onClick={() => setSelectedRoom(room)}
            style={{
              padding: 20,
              borderRadius: 12,
              cursor: "pointer",
              background: C.cardBg,
              border: `1px solid ${C.border}`,
              transition: "all 0.2s",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                marginBottom: 12,
              }}
            >
              <div>
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: C.textPrimary,
                  }}
                >
                  {room.dealName}
                </div>
                <div style={{ fontSize: 11, color: C.textSecondary }}>
                  {room.phase} · {room.lastActivity}
                </div>
              </div>
              <Badge text={room.status} color="green" />
            </div>
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 8,
                marginBottom: 12,
              }}
            >
              <div
                style={{
                  textAlign: "center",
                  padding: "8px 0",
                  borderRadius: 6,
                  background: C.subtleBg,
                }}
              >
                <div
                  style={{
                    fontSize: 16,
                    fontWeight: 700,
                    color: C.textPrimary,
                  }}
                >
                  {room.documents.length}
                </div>
                <div style={{ fontSize: 9, color: C.textSecondary }}>
                  Documents
                </div>
              </div>
              <div
                style={{
                  textAlign: "center",
                  padding: "8px 0",
                  borderRadius: 6,
                  background: C.subtleBg,
                }}
              >
                <div style={{ fontSize: 16, fontWeight: 700, color: C.green }}>
                  {Math.round(
                    (room.ddItems.complete / room.ddItems.total) * 100,
                  )}
                  %
                </div>
                <div style={{ fontSize: 9, color: C.textSecondary }}>
                  DD Complete
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

