function MarketCompsPage() {
  const [typeFilter, setTypeFilter] = useState("all");
  const [sortBy, setSortBy] = useState("saleDate");
  const types = [
    "all",
    "Office",
    "Industrial",
    "Multifamily",
    "Retail",
    "Mixed-Use",
  ];

  const filtered = (
    typeFilter === "all"
      ? MARKET_COMPS
      : MARKET_COMPS.filter((c) => c.type === typeFilter)
  ).sort((a, b) =>
    sortBy === "saleDate"
      ? b.saleDate.localeCompare(a.saleDate)
      : sortBy === "capRate"
        ? a.capRate - b.capRate
        : b.salePrice - a.salePrice,
  );

  const avgCapRate = meanOrDash(
    filtered,
    (c) => c.capRate,
    (n) => n.toFixed(1) + "%",
  );
  const avgPSF = meanOrDash(
    filtered,
    (c) => c.pricePSF,
    (n) => "$" + Math.round(n),
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div>
        <h2
          style={{
            fontSize: 22,
            fontWeight: 800,
            color: C.textPrimary,
            margin: 0,
          }}
        >
          Market Comps Engine
        </h2>
        <p style={{ fontSize: 13, color: C.textSecondary, margin: "4px 0 0" }}>
          Transaction comparables database — recent sales, pricing trends, and
          competitive benchmarking
        </p>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: 12,
        }}
      >
        {[
          { label: "Total Comps", value: MARKET_COMPS.length, color: C.accent },
          { label: "Avg Cap Rate", value: avgCapRate, color: C.green },
          { label: "Avg Price/SF", value: avgPSF, color: C.textPrimary },
          {
            label: "Total Volume",
            value:
              "$" +
              (
                MARKET_COMPS.reduce((s, c) => s + c.salePrice, 0) / 1000000000
              ).toFixed(2) +
              "B",
            color: C.accent,
          },
        ].map((k, i) => (
          <div
            key={i}
            style={{
              padding: "14px 16px",
              borderRadius: 10,
              background: C.cardBg,
              border: `1px solid ${C.border}`,
              textAlign: "center",
            }}
          >
            <div style={{ fontSize: 22, fontWeight: 800, color: k.color }}>
              {k.value}
            </div>
            <div
              style={{ fontSize: 10, color: C.textSecondary, fontWeight: 600 }}
            >
              {k.label}
            </div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 6, justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 6 }}>
          {types.map((t) => (
            <button
              key={t}
              onClick={() => setTypeFilter(t)}
              style={{
                padding: "5px 12px",
                borderRadius: 20,
                fontSize: 10,
                fontWeight: 600,
                cursor: "pointer",
                background:
                  typeFilter === t ? "var(--ds-accent-fill)" : C.subtleBg,
                color: typeFilter === t ? "#fff" : C.textSecondary,
                border: `1px solid ${typeFilter === t ? "var(--ds-accent-fill)" : C.border}`,
              }}
            >
              {t}
            </button>
          ))}
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {[
            { key: "saleDate", label: "Recent" },
            { key: "capRate", label: "Cap Rate" },
            { key: "salePrice", label: "Price" },
          ].map((s) => (
            <button
              key={s.key}
              onClick={() => setSortBy(s.key)}
              style={{
                padding: "5px 10px",
                borderRadius: 6,
                fontSize: 10,
                fontWeight: 600,
                cursor: "pointer",
                background: sortBy === s.key ? C.accent : C.subtleBg,
                color: sortBy === s.key ? "#fff" : C.textSecondary,
                border: `1px solid ${sortBy === s.key ? C.accent : C.border}`,
              }}
            >
              Sort: {s.label}
            </button>
          ))}
        </div>
      </div>

      <div
        style={{
          background: C.cardBg,
          borderRadius: 12,
          border: `1px solid ${C.border}`,
          overflow: "hidden",
        }}
      >
        <table
          style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}
        >
          <thead>
            <tr style={{ background: C.tableHeaderBg }}>
              {[
                "Property",
                "Type",
                "Submarket",
                "SF",
                "Sale Date",
                "Price",
                "Cap Rate",
                "$/SF",
                "Buyer",
                "Source",
              ].map((h, i) => (
                <th
                  key={i}
                  style={{
                    padding: "10px 12px",
                    color: C.textSecondary,
                    fontWeight: 700,
                    fontSize: 10,
                    textAlign: i === 0 ? "left" : "center",
                    textTransform: "uppercase",
                    letterSpacing: 0.5,
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((c, i) => (
              <tr
                key={c.id}
                style={{
                  borderBottom: `1px solid ${C.border}`,
                  background: i % 2 === 0 ? "transparent" : C.subtleBg,
                }}
              >
                <td
                  style={{
                    padding: "10px 12px",
                    fontWeight: 600,
                    color: C.textPrimary,
                  }}
                >
                  {c.name}
                </td>
                <td style={{ textAlign: "center" }}>
                  <Badge
                    text={c.type}
                    color={
                      c.type === "Office"
                        ? "blue"
                        : c.type === "Industrial"
                          ? "green"
                          : c.type === "Multifamily"
                            ? "purple"
                            : "amber"
                    }
                  />
                </td>
                <td
                  style={{
                    textAlign: "center",
                    fontSize: 11,
                    color: C.textSecondary,
                  }}
                >
                  {c.submarket}
                </td>
                <td style={{ textAlign: "center", color: C.textPrimary }}>
                  {(c.sf / 1000).toFixed(0)}K
                </td>
                <td style={{ textAlign: "center", color: C.textSecondary }}>
                  {c.saleDate}
                </td>
                <td
                  style={{
                    textAlign: "center",
                    fontWeight: 700,
                    color: C.textPrimary,
                  }}
                >
                  ${(c.salePrice / 1000000).toFixed(1)}M
                </td>
                <td
                  style={{
                    textAlign: "center",
                    fontWeight: 700,
                    color:
                      c.capRate <= 5.5
                        ? C.green
                        : c.capRate <= 6.5
                          ? C.amber
                          : C.red,
                  }}
                >
                  {c.capRate}%
                </td>
                <td style={{ textAlign: "center", color: C.textPrimary }}>
                  ${c.pricePSF}
                </td>
                <td
                  style={{
                    textAlign: "center",
                    fontSize: 11,
                    fontWeight: 500,
                    color:
                      c.buyer === "Valiance (Under LOI)"
                        ? C.accent
                        : C.textSecondary,
                  }}
                >
                  {c.buyer}
                </td>
                <td
                  style={{
                    textAlign: "center",
                    fontSize: 10,
                    color: C.textSecondary,
                  }}
                >
                  {c.source}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <SectionCard title="Cap Rate by Property Type">
        <ResponsiveContainer width="100%" height={200}>
          <BarChart
            data={types
              .filter((t) => t !== "all")
              .map((t) => {
                const comps = MARKET_COMPS.filter((c) => c.type === t);
                return {
                  type: t,
                  avgCapRate:
                    comps.length > 0
                      ? +(
                          comps.reduce((s, c) => s + c.capRate, 0) /
                          comps.length
                        ).toFixed(1)
                      : 0,
                  count: comps.length,
                };
              })}
          >
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} />
            <XAxis
              dataKey="type"
              tick={{ fontSize: 10, fill: C.textSecondary }}
            />
            <YAxis
              domain={[4, 7.5]}
              tick={{ fontSize: 10, fill: C.textSecondary }}
            />
            <Tooltip formatter={(v) => `${v}%`} />
            <Bar dataKey="avgCapRate" fill={C.accent} radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </SectionCard>
    </div>
  );
}

