function CapitalStackPage({ filterProperty }) {
  const [selectedProperty, setSelectedProperty] = useState(0);
  const [showRefi, setShowRefi] = useState(false);
  const stacks = filterProperty
    ? CAPITAL_STACKS.filter((s) => s.property === filterProperty)
    : CAPITAL_STACKS;
  const stack = stacks[selectedProperty];

  if (!stack) {
    return React.createElement(
      "div",
      { style: { display: "flex", flexDirection: "column", gap: 24 } },
      React.createElement(
        SectionCard,
        {
          title: "Capital Stack Visualizer",
          subtitle: "Interactive debt & equity layering across the portfolio",
        },
        React.createElement(
          "div",
          {
            style: {
              padding: 32,
              textAlign: "center",
              color: C.textSecondary,
              fontSize: 13,
              lineHeight: 1.6,
            },
          },
          "No capital stack recorded for this property yet. Layers appear here once debt and equity tranches have been recorded.",
        ),
      ),
    );
  }

  return React.createElement(
    "div",
    { style: { display: "flex", flexDirection: "column", gap: 24 } },
    React.createElement(
      SectionCard,
      {
        title: "Capital Stack Visualizer",
        subtitle: "Interactive debt & equity layering across the portfolio",
      },
      !filterProperty &&
        React.createElement(
          "div",
          {
            style: {
              display: "flex",
              gap: 12,
              flexWrap: "wrap",
              marginBottom: 20,
            },
          },
          stacks.map((s, i) =>
            React.createElement(
              "button",
              {
                key: i,
                onClick: () => {
                  setSelectedProperty(i);
                  setShowRefi(false);
                },
                style: {
                  padding: "8px 16px",
                  borderRadius: 8,
                  border: `1px solid ${i === selectedProperty ? C.accent : C.border}`,
                  background:
                    i === selectedProperty
                      ? `${alpha(C.accent, 12.5)}`
                      : C.cardBg,
                  color: C.textPrimary,
                  cursor: "pointer",
                  fontSize: 13,
                  fontWeight: i === selectedProperty ? 600 : 400,
                },
              },
              s.property,
            ),
          ),
        ),
      React.createElement(
        "div",
        {
          style: { display: "grid", gridTemplateColumns: "300px 1fr", gap: 24 },
        },
        React.createElement(
          "div",
          {
            style: {
              display: "flex",
              flexDirection: "column",
              borderRadius: 12,
              overflow: "hidden",
              border: `1px solid ${C.border}`,
            },
          },
          [...stack.layers].reverse().map((layer, i) =>
            React.createElement(
              "div",
              {
                key: i,
                onClick: () =>
                  setShowRefi(showRefi === layer.type ? false : layer.type),
                style: {
                  background: layer.color,
                  padding: "14px 16px",
                  minHeight: Math.max(layer.pct * 3, 40),
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  cursor: "pointer",
                  transition: "all 0.2s",
                  opacity: showRefi && showRefi !== layer.type ? 0.6 : 1,
                },
              },
              React.createElement(
                "span",
                { style: { color: "#fff", fontWeight: 600, fontSize: 13 } },
                layer.type,
              ),
              React.createElement(
                "span",
                { style: { color: "rgba(255,255,255,0.8)", fontSize: 12 } },
                `${fmt(layer.amount)} (${layer.pct}%)`,
              ),
            ),
          ),
        ),
        React.createElement(
          "div",
          null,
          React.createElement(
            "div",
            {
              style: {
                display: "grid",
                gridTemplateColumns: "repeat(4, 1fr)",
                gap: 12,
                marginBottom: 20,
              },
            },
            React.createElement(KPI, {
              label: "LTV",
              value: `${stack.metrics.ltv}%`,
              color:
                stack.metrics.ltv > 70
                  ? "var(--ds-danger-text)"
                  : "var(--ds-success-text)",
            }),
            React.createElement(KPI, {
              label: "DSCR",
              value: `${stack.metrics.dscr}x`,
              color:
                stack.metrics.dscr < 1.25
                  ? "var(--ds-danger-text)"
                  : "var(--ds-success-text)",
            }),
            React.createElement(KPI, {
              label: "Debt Yield",
              value: `${stack.metrics.debtYield}%`,
              color: "var(--ds-accent)",
            }),
            React.createElement(KPI, {
              label: "Equity Multiple",
              value: `${stack.metrics.equityMultiple}x`,
              color: "var(--ds-ai)",
            }),
          ),
          React.createElement(MiniTable, {
            headers: ["Layer", "Provider", "Amount", "Rate", "Maturity"],
            rows: stack.layers.map((l) => [
              l.type,
              l.provider,
              fmt(l.amount),
              l.rate,
              l.maturity,
            ]),
          }),
          React.createElement(
            "div",
            { style: { marginTop: 16 } },
            React.createElement(
              "button",
              {
                onClick: () => setShowRefi(!showRefi),
                style: {
                  padding: "8px 16px",
                  borderRadius: 8,
                  border: `1px solid ${C.accent}`,
                  background: showRefi
                    ? `${alpha(C.accent, 12.5)}`
                    : "transparent",
                  color: C.accent,
                  cursor: "pointer",
                  fontSize: 13,
                },
              },
              showRefi ? "Hide Refi Scenarios" : "Model Refinancing Scenarios",
            ),
          ),
        ),
      ),
      showRefi &&
        React.createElement(
          "div",
          { style: { marginTop: 24 } },
          React.createElement(
            "h4",
            { style: { color: C.textPrimary, marginBottom: 12, fontSize: 14 } },
            "Refinancing Scenario Comparison",
          ),
          REFI_SCENARIOS.length
            ? React.createElement(MiniTable, {
                headers: [
                  "Scenario",
                  "Rate",
                  "LTV",
                  "I/O Period",
                  "DSCR",
                  "Annual Debt Service",
                ],
                rows: REFI_SCENARIOS.map((s) => [
                  s.label,
                  s.rate,
                  `${s.ltv}%`,
                  `${s.io} yrs`,
                  `${s.dscr}x`,
                  fmtFull(s.annualDS),
                ]),
              })
            : React.createElement(
                "div",
                {
                  style: {
                    color: C.textSecondary,
                    fontSize: 13,
                    lineHeight: 1.6,
                    maxWidth: 720,
                  },
                },
                "Refinancing scenarios compare current terms against market-rate, bridge and agency alternatives on rate, LTV, interest-only period, DSCR and annual debt service. They are computed from this property's executed loan terms and a live rate feed; neither is connected, so no comparison is shown rather than one built from defaults.",
              ),
        ),
    ),
  );
}

