function ICPackagePage() {
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [generating, setGenerating] = useState(false);
  const [progress, setProgress] = useState(0);

  const startGenerate = (tmpl) => {
    setSelectedTemplate(tmpl);
    setGenerating(true);
    setProgress(0);
    let p = 0;
    const iv = setInterval(() => {
      p += Math.random() * 15 + 5;
      if (p >= 100) {
        p = 100;
        clearInterval(iv);
        setTimeout(() => setGenerating(false), 500);
      }
      setProgress(Math.min(100, Math.round(p)));
    }, 400);
  };

  return React.createElement(
    "div",
    { style: { display: "flex", flexDirection: "column", gap: 24 } },
    React.createElement(
      SectionCard,
      {
        title: "IC Package Generator",
        subtitle:
          "Auto-generate institutional-grade investment committee packages",
      },
      React.createElement(
        "div",
        {
          style: {
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: 16,
          },
        },
        IC_TEMPLATES.map((tmpl) =>
          React.createElement(
            "div",
            {
              key: tmpl.id,
              style: {
                padding: 20,
                borderRadius: 12,
                border: `1px solid ${C.border}`,
                background: C.cardBg,
              },
            },
            React.createElement(
              "div",
              {
                style: {
                  fontWeight: 600,
                  color: C.textPrimary,
                  fontSize: 14,
                  marginBottom: 6,
                },
              },
              tmpl.label,
            ),
            React.createElement(
              "div",
              {
                style: {
                  fontSize: 12,
                  color: C.textSecondary,
                  marginBottom: 12,
                },
              },
              `${tmpl.sections.length} sections · Est. ${tmpl.estTime}`,
            ),
            React.createElement(
              "div",
              {
                style: {
                  fontSize: 11,
                  color: C.textSecondary,
                  marginBottom: 12,
                },
              },
              tmpl.sections.join(" → "),
            ),
            React.createElement(
              "button",
              {
                onClick: () => startGenerate(tmpl),
                style: {
                  width: "100%",
                  padding: "8px 0",
                  borderRadius: 8,
                  border: `1px solid ${C.accent}`,
                  background: `${alpha(C.accent, 8.2)}`,
                  color: C.accent,
                  cursor: "pointer",
                  fontSize: 12,
                  fontWeight: 600,
                },
              },
              "Generate Package",
            ),
          ),
        ),
      ),
    ),
    generating &&
      selectedTemplate &&
      React.createElement(
        SectionCard,
        {
          title: `Generating: ${selectedTemplate.label}`,
          status: "in-progress",
        },
        React.createElement(
          "div",
          { style: { marginBottom: 12 } },
          React.createElement(
            "div",
            {
              style: {
                height: 8,
                background: `${alpha(C.border, 18.8)}`,
                borderRadius: 4,
                overflow: "hidden",
              },
            },
            React.createElement("div", {
              style: {
                width: `${progress}%`,
                height: "100%",
                background: C.accent,
                borderRadius: 4,
                transition: "width 0.3s",
              },
            }),
          ),
          React.createElement(
            "div",
            { style: { fontSize: 12, color: C.textSecondary, marginTop: 6 } },
            `${progress}% — ${progress < 30 ? "Gathering data..." : progress < 60 ? "Running agent analysis..." : progress < 90 ? "Compiling sections..." : "Finalizing package..."}`,
          ),
        ),
        React.createElement(
          "div",
          { style: { display: "flex", gap: 8, flexWrap: "wrap" } },
          selectedTemplate.sections.map((s, i) => {
            const sectionProgress =
              (progress / 100) * selectedTemplate.sections.length;
            const isDone = i < sectionProgress - 1;
            const isActive = i >= sectionProgress - 1 && i < sectionProgress;
            return React.createElement(
              "span",
              {
                key: i,
                style: {
                  padding: "4px 10px",
                  borderRadius: 6,
                  fontSize: 11,
                  border: `1px solid ${isDone ? "var(--ds-success-text)" : isActive ? C.accent : C.border}40`,
                  color: isDone
                    ? "var(--ds-success-text)"
                    : isActive
                      ? C.accent
                      : C.textSecondary,
                  background: isDone
                    ? "color-mix(in srgb, var(--ds-success-text) 6.3%, transparent)"
                    : isActive
                      ? `${alpha(C.accent, 6.3)}`
                      : "transparent",
                },
              },
              `${isDone ? "✓ " : isActive ? "◉ " : ""}${s}`,
            );
          }),
        ),
      ),
    !generating &&
      selectedTemplate &&
      React.createElement(
        SectionCard,
        {
          title: "Package Preview",
          subtitle: `${selectedTemplate.label} — Ready for review`,
        },
        React.createElement(
          "div",
          {
            style: {
              padding: 16,
              borderRadius: 10,
              background: `${alpha(C.accent, 3.1)}`,
              border: `1px solid ${alpha(C.accent, 12.5)}`,
              marginBottom: 16,
            },
          },
          React.createElement(
            "div",
            {
              style: {
                fontSize: 13,
                color: C.textPrimary,
                fontWeight: 600,
                marginBottom: 4,
              },
            },
            "Package generated successfully",
          ),
          React.createElement(
            "div",
            { style: { fontSize: 12, color: C.textSecondary } },
            `${selectedTemplate.sections.length} sections compiled by ${selectedTemplate.agents.length} agents. Ready for IC review.`,
          ),
        ),
        selectedTemplate.sections.map((s, i) =>
          React.createElement(
            "div",
            {
              key: i,
              style: {
                display: "flex",
                alignItems: "center",
                gap: 12,
                padding: "10px 0",
                borderBottom: `1px solid ${alpha(C.border, 8.2)}`,
              },
            },
            React.createElement(
              "span",
              {
                style: {
                  width: 28,
                  height: 28,
                  borderRadius: "50%",
                  background: `${alpha(C.accent, 8.2)}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 12,
                  color: C.accent,
                  fontWeight: 600,
                },
              },
              i + 1,
            ),
            React.createElement(
              "span",
              { style: { flex: 1, fontSize: 13, color: C.textPrimary } },
              s,
            ),
            React.createElement(Badge, {
              text: "Complete",
              color: "var(--ds-success-text)",
            }),
          ),
        ),
        React.createElement(
          "div",
          { style: { display: "flex", gap: 12, marginTop: 16 } },
          React.createElement(
            "button",
            {
              onClick: () => {
                const btn = document.querySelector("[data-ic-export]");
                if (btn) {
                  btn.textContent = "Exporting...";
                }
                try {
                  generateHTMLReport({
                    title: `IC Package — ${selectedTemplate.label}`,
                    subtitle: `Investment Committee Materials • ${new Date().toLocaleDateString()}`,
                    sections: [
                      {
                        type: "metrics",
                        title: "Package Overview",
                        items: [
                          { label: "Template", value: selectedTemplate.label },
                          {
                            label: "Sections",
                            value: String(selectedTemplate.sections.length),
                          },
                          {
                            label: "Agents",
                            value: String(selectedTemplate.agents.length),
                          },
                          {
                            label: "Generated",
                            value: new Date().toLocaleString(),
                          },
                        ],
                      },
                      {
                        type: "table",
                        title: "Sections Included",
                        headers: ["#", "Section", "Status"],
                        rows: selectedTemplate.sections.map((s, i) => [
                          String(i + 1),
                          s,
                          "Complete",
                        ]),
                      },
                    ],
                  });
                } catch (err) {
                  console.error("IC PDF export error:", err);
                }
                if (btn) {
                  setTimeout(() => {
                    btn.textContent = "✓ PDF Exported";
                    setTimeout(() => {
                      btn.textContent = "Export to PDF";
                    }, 2000);
                  }, 800);
                }
              },
              "data-ic-export": "true",
              style: {
                padding: "8px 20px",
                borderRadius: 8,
                background: C.accent,
                color: "#fff",
                border: "none",
                cursor: "pointer",
                fontSize: 12,
                fontWeight: 600,
                transition: "all 0.2s",
              },
            },
            "Export to PDF",
          ),
          React.createElement(
            "button",
            {
              onClick: () => {
                const btn = document.querySelector("[data-ic-send]");
                if (btn) {
                  btn.textContent = "Sending...";
                }
                try {
                  const subject = encodeURIComponent(
                    `IC Package: ${selectedTemplate.label}`,
                  );
                  const body = encodeURIComponent(
                    `Please review the attached IC package.\n\nTemplate: ${selectedTemplate.label}\nSections: ${selectedTemplate.sections.join(", ")}\nGenerated: ${new Date().toLocaleString()}`,
                  );
                  window.open(
                    `mailto:?subject=${subject}&body=${body}`,
                    "_self",
                  );
                } catch (err) {
                  console.error("IC send error:", err);
                }
                if (btn) {
                  setTimeout(() => {
                    btn.textContent = "✓ Sent to IC";
                    setTimeout(() => {
                      btn.textContent = "Send to IC Members";
                    }, 2000);
                  }, 800);
                }
              },
              "data-ic-send": "true",
              style: {
                padding: "8px 20px",
                borderRadius: 8,
                background: "transparent",
                color: C.accent,
                border: `1px solid ${C.accent}`,
                cursor: "pointer",
                fontSize: 12,
                transition: "all 0.2s",
              },
            },
            "Send to IC Members",
          ),
          React.createElement(
            "button",
            {
              onClick: () => setSelectedTemplate(null),
              style: {
                padding: "8px 20px",
                borderRadius: 8,
                background: "transparent",
                color: C.textSecondary,
                border: `1px solid ${C.border}`,
                cursor: "pointer",
                fontSize: 12,
              },
            },
            "New Package",
          ),
        ),
      ),
    React.createElement(
      SectionCard,
      {
        title: "Recent Packages",
        subtitle: "Previously generated IC materials",
      },
      React.createElement(MiniTable, {
        headers: [
          "Package Type",
          "Property / Scope",
          "Date",
          "Status",
          "IC Votes",
          "Prepared By",
        ],
        rows: IC_RECENT_PACKAGES.map((p) => [
          p.template,
          p.property,
          p.date,
          p.status,
          p.votes,
          p.preparedBy,
        ]),
      }),
    ),
  );
}

