function LiveRentRollWorkspace({ property, C, userProfile }) {
  const role = userProfile ? userProfile.role : null;
  const canAdjust =
    !!userProfile &&
    (userProfile.is_admin === true ||
      role === "gp" ||
      role === "gp_admin" ||
      role === "admin");

  const [adjustSeed, setAdjustSeed] = React.useState(null);
  const [rollRefresh, setRollRefresh] = React.useState(0);
  const [inlineWrites, setInlineWrites] = React.useState(0);
  const [versionsOpen, setVersionsOpen] = React.useState(false);
  const adjustmentsRef = React.useRef(null);

  const scrollToAdjustments = () => {
    const node = adjustmentsRef.current;
    if (node && typeof node.scrollIntoView === "function") {
      node.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  const openBlankAdjustment = () => {
    setAdjustSeed((prev) => ({
      leaseId: null,
      adjustmentId: null,
      token: (prev ? prev.token : 0) + 1,
    }));
    scrollToAdjustments();
  };
  const openAdjustmentForLease = (row) => {
    const leaseId = row ? row.leaseId : null;
    const adjustmentId =
      row && row.adjustmentId != null ? row.adjustmentId : null;
    setAdjustSeed((prev) => ({
      leaseId,
      adjustmentId,
      token: (prev ? prev.token : 0) + 1,
    }));
    scrollToAdjustments();
  };

  const sectionHeading = (title, note) =>
    React.createElement(
      "div",
      { style: { marginBottom: 4 } },
      React.createElement(
        "div",
        {
          style: { fontSize: 15, fontWeight: 700, color: C.textPrimary },
        },
        title,
      ),
      note
        ? React.createElement(
            "div",
            {
              style: {
                fontSize: 12,
                color: C.textSecondary,
                marginTop: 2,
                lineHeight: 1.5,
              },
            },
            note,
          )
        : null,
    );

  const adjustmentsSection = !canAdjust
    ? null
    : React.createElement(
        RoleGate,
        { allowedRoles: ["gp", "admin"], userProfile },
        React.createElement(
          "div",
          {
            ref: adjustmentsRef,
            style: { borderTop: `1px solid ${C.border}`, paddingTop: 18 },
          },
          React.createElement(
            "div",
            {
              style: {
                maxWidth: 1040,
                margin: "0 auto",
                padding: "0 16px",
                display: "flex",
                alignItems: "flex-start",
                justifyContent: "space-between",
                gap: 12,
              },
            },
            sectionHeading(
              "Adjustments",
              "Corrections layered on the roll above — rent-controlled month-to-month tenants treated as occupied, master-lease groups, off-Entrata leases. Saving one re-reads the roll, so the figures at the top of this page are the figures these adjustments produce.",
            ),
            React.createElement(
              "button",
              {
                type: "button",
                onClick: openBlankAdjustment,
                style: {
                  font: "inherit",
                  fontSize: 12,
                  fontWeight: 600,
                  padding: "6px 12px",
                  color: "#fff",
                  background: C.accent,
                  border: "none",
                  borderRadius: 8,
                  cursor: "pointer",
                  whiteSpace: "nowrap",
                },
              },
              "Add adjustment",
            ),
          ),
          React.createElement(RentRollAdjustmentsPropertyView, {
            property,
            C,
            userProfile,
            showIntro: false,
            showOverlayPreview: false,
            newAdjustmentSeed: adjustSeed,
            onAdjustmentsChanged: () => setRollRefresh((n) => n + 1),
            reloadToken: inlineWrites,
          }),
        ),
      );

  const versionsSection = !canAdjust
    ? null
    : React.createElement(
        RoleGate,
        { allowedRoles: ["gp", "admin"], userProfile },
        React.createElement(
          "div",
          { style: { borderTop: `1px solid ${C.border}`, paddingTop: 18 } },
          React.createElement(
            "button",
            {
              type: "button",
              onClick: () => setVersionsOpen((v) => !v),
              "aria-expanded": versionsOpen,
              style: {
                font: "inherit",
                display: "flex",
                alignItems: "center",
                gap: 8,
                width: "100%",
                textAlign: "left",
                padding: "0 20px",
                background: "transparent",
                border: "none",
                cursor: "pointer",
              },
            },
            React.createElement(
              "span",
              {
                "aria-hidden": "true",
                style: { fontSize: 11, color: C.textSecondary },
              },
              versionsOpen ? "▾" : "▸",
            ),
            sectionHeading(
              "Version History",
              versionsOpen
                ? "Dated copies of this roll. Each one is frozen at capture and is not affected by the controls above."
                : "Dated copies of this roll, frozen at capture.",
            ),
          ),
          versionsOpen
            ? React.createElement(RentRollVersionsPanel, {
                propertyId: property?.id || null,
                propertyName: property ? property.name : null,
                C,
                userProfile,
              })
            : null,
        ),
      );

  return React.createElement(
    "div",
    {
      style: {
        display: "flex",
        flexDirection: "column",
        gap: 18,
        paddingBottom: 24,
      },
    },
    React.createElement(LiveRentRollTab, {
      property,
      onAdjustLease: canAdjust ? openAdjustmentForLease : null,
      refreshToken: rollRefresh,
      inlineEdit:
        canAdjust && property?.id
          ? {
              propertyId: property.id,
              onSaved: () => {
                setRollRefresh((n) => n + 1);
                setInlineWrites((n) => n + 1);
              },
            }
          : null,
    }),
    adjustmentsSection,
    versionsSection,
  );
}

const BUDGET_CODE_WORKSPACE_LABELS = [
  "Budget Consolidation",
  "Variance Analysis",
  "Quarterly Reporting",
];

const VARIANCE_ANALYSIS_DESTINATION = {
  key: "propertyVariance",
  roles: ["gp"],
  surfaceKey: MODULE_WORKSPACE_SURFACE_KEYS.varianceAnalysis,
};

const QUARTERLY_REPORTING_VIEW_ROLES = ["gp"];

function moduleWorkspaceViewsFor(
  sectionLabel,
  {
    role,
    userProfile,
    budgetCode,
    editorDirtyRef,
    hiddenKeys = null,
    statementsSeed = null,
    onStatementsSeedConsumed = null,
  },
) {
  const curate = (views) =>
    hiddenKeys
      ? views.filter(
          (v) => !isModuleViewHidden(hiddenKeys, sectionLabel, v.key),
        )
      : views;
  if (sectionLabel === "Budget Consolidation") {
    const gate = {
      propertyCode: budgetCode ? budgetCode.code : null,
      propertyCodeLoading: budgetCode ? budgetCode.loading : false,
      propertyCodeError: budgetCode ? budgetCode.error : null,
    };
    const budgetRenders = {
      analysis: () =>
        React.createElement(PropertyBudgetAnalysisTab, {
          ...gate,
          userProfile,
        }),
      editor: () =>
        React.createElement(PropertyBudgetEditorTab, {
          ...gate,
          userProfile,
          dirtyRef: editorDirtyRef,
        }),
      writeback: () =>
        React.createElement(PropertyBudgetWritebackTab, {
          ...gate,
          userProfile,
        }),
    };
    return (moduleWorkspaceViewMeta("Budget Consolidation") || [])
      .filter((v) => budgetRenders[v.key])
      .map((v) => ({
        key: v.key,
        label: v.label,
        render: budgetRenders[v.key],
      }));
  }
  if (sectionLabel === "Variance Analysis") {
    const gate = {
      propertyCode: budgetCode ? budgetCode.code : null,
      propertyCodeLoading: budgetCode ? budgetCode.loading : false,
      propertyCodeError: budgetCode ? budgetCode.error : null,
    };
    const varianceRenders = {
      variance: () => React.createElement(PropertyBudgetVarianceTab, gate),
      pyVariance: () => React.createElement(PropertyPriorYearVarianceTab, gate),
      uwVariance: () => React.createElement(PropertyUwVarianceTab, gate),
    };
    return curate(
      (moduleWorkspaceViewMeta("Variance Analysis") || [])
        .filter((v) => varianceRenders[v.key])
        .map((v) => ({
          key: v.key,
          label: v.label,
          render: varianceRenders[v.key],
        })),
    );
  }
  if (sectionLabel === "Quarterly Reporting") {
    if (!(role === "admin" || QUARTERLY_REPORTING_VIEW_ROLES.includes(role)))
      return null;
    const gate = {
      propertyCode: budgetCode ? budgetCode.code : null,
      propertyCodeLoading: budgetCode ? budgetCode.loading : false,
      propertyCodeError: budgetCode ? budgetCode.error : null,
    };
    const quarterlyRenders = {
      underwriting: (property) =>
        React.createElement(PropertyUnderwritingBlock, {
          propertyName: property ? property.name : null,
        }),
      financialStatements: () =>
        React.createElement(PropertyFinancialStatementsTab, {
          C,
          ...gate,
          initialAsOfYm: statementsSeed?.asOfYm || "",
          initialFromYm: statementsSeed?.fromYm || "",
          initialToYm: statementsSeed?.toYm || "",
          onSeedConsumed: onStatementsSeedConsumed,
        }),
      apiReportBuilder: (property) =>
        React.createElement(CustomReportsTab, {
          propertyName: property ? property.name : null,
        }),
      fileStorage: (property) =>
        React.createElement(PropertyFileStorage, {
          propertyName: property ? property.name : null,
        }),
    };
    return curate(
      (moduleWorkspaceViewMeta("Quarterly Reporting") || [])
        .filter((v) => quarterlyRenders[v.key])
        .map((v) => ({
          key: v.key,
          label: v.label,
          render: quarterlyRenders[v.key],
        })),
    );
  }
  if (sectionLabel !== "Live Rent Rolls") return null;
  const rentRollRenders = {
    liveRentRoll: (property) =>
      React.createElement(LiveRentRollWorkspace, { property, C, userProfile }),
  };
  const rentRollMeta = moduleWorkspaceViewMeta("Live Rent Rolls") || [];
  const rentRollViewsFor = (keys) =>
    rentRollMeta
      .filter((v) => keys.includes(v.key) && rentRollRenders[v.key])
      .map((v) => ({
        key: v.key,
        label: v.label,
        render: rentRollRenders[v.key],
      }));
  return [
    ...rentRollViewsFor(["liveRentRoll"]),
    ...(TENANT_CRM_SURFACE_HIDDEN
      ? []
      : [
          {
            key: "rentRoll",
            label: "Rent Roll",
            render: (property) =>
              React.createElement(TenantCRMPage, {
                filterProperty: property ? property.name : null,
              }),
          },
        ]),
  ];
}

function CustomReportsTab({ propertyName }) {
  const property = useMemo(
    () => (PROPERTIES || []).find((p) => p.name === propertyName) || null,
    [propertyName],
  );

  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [composer, setComposer] = useState(null);
  const [runner, setRunner] = useState(null);
  const [orgId, setOrgIdState] = useState(null);
  const [userProfileId, setUserProfileIdState] = useState(null);

  const displayOrderRef = useRef(new Map());
  const captureDisplayOrder = (rows) => {
    const next = new Map();
    rows.forEach((r, i) => {
      if (r?.id) next.set(r.id, i);
    });
    displayOrderRef.current = next;
  };
  const applyDisplayOrder = (rows) => {
    const prior = displayOrderRef.current;
    if (!prior || prior.size === 0) {
      captureDisplayOrder(rows);
      return rows;
    }
    const known = [];
    const fresh = [];
    for (const r of rows) {
      if (r?.id && prior.has(r.id)) known.push(r);
      else fresh.push(r);
    }
    known.sort((a, b) => (prior.get(a.id) ?? 0) - (prior.get(b.id) ?? 0));
    const reordered = [...fresh, ...known];
    captureDisplayOrder(reordered);
    return reordered;
  };

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { session } = await getSession();
        if (session?.user) {
          const { profile } = await getUserProfile(session.user.id);
          if (!cancelled && profile) {
            if (profile.org_id) setOrgIdState(profile.org_id);
            if (profile.id) setUserProfileIdState(profile.id);
          }
        }
      } catch (e) {}
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const reload = useCallback(
    async ({ preserveOrder = false } = {}) => {
      if (!property?.id) {
        setReports([]);
        setLoading(false);
        return;
      }
      setLoading(true);
      setError(null);
      try {
        const rows = await fetchCustomReportsForProperty(property.id);
        if (preserveOrder) {
          setReports(applyDisplayOrder(rows));
        } else {
          displayOrderRef.current = new Map();
          captureDisplayOrder(rows);
          setReports(rows);
        }
      } catch (e) {
        setError(e?.message || String(e));
        setReports([]);
      } finally {
        setLoading(false);
      }
    },
    [property?.id],
  );

  useEffect(() => {
    reload();
  }, [reload]);

  if (!property) {
    return React.createElement(
      "div",
      { style: { padding: 32, color: C.textSecondary, fontSize: 14 } },
      "Property not found.",
    );
  }
  if (!property.entrataPropertyId) {
    return React.createElement(
      "div",
      { style: { padding: 32 } },
      React.createElement(
        "div",
        {
          style: {
            fontSize: 15,
            color: C.textPrimary,
            fontWeight: 600,
            marginBottom: 8,
          },
        },
        "Entrata not mapped",
      ),
      React.createElement(
        "div",
        { style: { fontSize: 13, color: C.textSecondary, lineHeight: 1.6 } },
        "API Report Builder pulls live data from this property's Entrata account. Set the property's Entrata ID on the property edit form before composing a report. Once the Entrata ID is mapped, you can browse the ",
        getEntrataApis().length,
        " catalogued endpoints here and save replayable report chains.",
      ),
    );
  }

  const handleRun = async (report) => {
    setRunner({
      report,
      status: "running",
      running: true,
      payload: null,
      error: null,
    });
    try {
      const res = await authedFunctionFetch(
        "/.netlify/functions/entrata-execute-report",
        { report_id: report.id },
      );
      const body = await res.json().catch(() => null);
      if (!res.ok) {
        setRunner({
          report,
          status: "error",
          running: false,
          payload: null,
          error: body?.error || `HTTP ${res.status}`,
        });
      } else {
        setRunner({
          report,
          status: body?.status || "success",
          running: false,
          payload: body,
          error: null,
        });
        reload({ preserveOrder: true });
      }
    } catch (e) {
      setRunner({
        report,
        status: "error",
        running: false,
        payload: null,
        error: e?.message || String(e),
      });
    }
  };

  const handleDelete = async (report) => {
    if (!window.confirm(`Delete "${report.name}"? This can't be undone.`))
      return;
    try {
      await deleteCustomReport(report.id);
      reload();
    } catch (e) {
      setError(e?.message || String(e));
    }
  };

  const handleEdit = (report) => setComposer({ mode: "edit", report });

  const handleSaved = () => {
    setComposer(null);
    reload();
  };

  return React.createElement(
    "div",
    {
      style: { padding: 24, display: "flex", flexDirection: "column", gap: 20 },
    },
    React.createElement(
      "div",
      {
        style: {
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          gap: 16,
        },
      },
      React.createElement(
        "div",
        null,
        React.createElement(
          "div",
          {
            style: {
              fontSize: 18,
              fontWeight: 700,
              color: C.textPrimary,
              marginBottom: 4,
            },
          },
          "API Report Builder",
        ),
        React.createElement(
          "div",
          {
            style: {
              fontSize: 12,
              color: C.textSecondary,
              lineHeight: 1.5,
              maxWidth: 720,
            },
          },
          "Compose a chain of Entrata API calls into a named report, save it, and replay against this property's live data. Reports are scoped to ",
          React.createElement("strong", null, propertyName),
          " and visible to every member of your org.",
        ),
      ),
      React.createElement(
        "div",
        { style: { display: "flex", gap: 8 } },
        React.createElement(
          "button",
          {
            onClick: () => reload(),
            disabled: loading,
            title:
              "Re-sort by most-recently-updated. Resyncs the card order to the server.",
            style: {
              padding: "10px 14px",
              borderRadius: 6,
              border: `1px solid ${C.border}`,
              background: C.cardBg,
              color: C.textPrimary,
              fontSize: 12,
              fontWeight: 600,
              cursor: loading ? "default" : "pointer",
              opacity: loading ? 0.6 : 1,
            },
          },
          "Refresh",
        ),
        React.createElement(
          "button",
          {
            onClick: () => setComposer({ mode: "new" }),
            disabled: loading,
            style: {
              padding: "10px 16px",
              borderRadius: 6,
              border: "none",
              background: C.gold,
              color: C.navy,
              fontSize: 13,
              fontWeight: 700,
              cursor: loading ? "default" : "pointer",
              opacity: loading ? 0.6 : 1,
            },
          },
          "New custom report",
        ),
      ),
    ),

    error &&
      React.createElement(
        "div",
        {
          style: {
            padding: 12,
            background: "rgba(220,53,69,0.08)",
            border: `1px solid rgba(220,53,69,0.2)`,
            borderRadius: 6,
            color: "var(--ds-danger-text)",
            fontSize: 12,
          },
        },
        "Failed to load reports: ",
        error,
      ),

    loading
      ? React.createElement(
          "div",
          {
            style: {
              padding: 40,
              textAlign: "center",
              color: C.textSecondary,
              fontSize: 13,
            },
          },
          "Loading reports…",
        )
      : reports.length === 0
        ? React.createElement(
            "div",
            {
              style: {
                padding: 32,
                border: `1px dashed ${C.border}`,
                borderRadius: 8,
                color: C.textSecondary,
                fontSize: 13,
                textAlign: "center",
                lineHeight: 1.6,
              },
            },
            React.createElement(
              "div",
              {
                style: {
                  fontWeight: 600,
                  color: C.textPrimary,
                  marginBottom: 6,
                },
              },
              "No custom reports yet.",
            ),
            "Build one from the ",
            getEntrataApis().length,
            " catalogued Entrata APIs to pull live property data on demand. Once saved, reports replay with one click and surface the latest values for ",
            propertyName,
            ".",
            React.createElement(
              "div",
              { style: { marginTop: 16 } },
              React.createElement(
                "button",
                {
                  onClick: () => setComposer({ mode: "new" }),
                  style: {
                    padding: "8px 14px",
                    borderRadius: 6,
                    border: "none",
                    background: C.gold,
                    color: C.navy,
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: "pointer",
                  },
                },
                "Build your first report",
              ),
            ),
          )
        : React.createElement(
            "div",
            {
              style: {
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(360px, 1fr))",
                gap: 16,
              },
            },
            reports.map((r) =>
              React.createElement(SavedReportCard, {
                key: r.id,
                report: r,
                onRun: () => handleRun(r),
                onEdit: () => handleEdit(r),
                onDelete: () => handleDelete(r),
              }),
            ),
          ),

    composer &&
      React.createElement(CustomReportComposer, {
        mode: composer.mode,
        existingReport: composer.report || null,
        property,
        orgId,
        userProfileId,
        onClose: () => setComposer(null),
        onSaved: handleSaved,
      }),

    runner &&
      React.createElement(CustomReportRunner, {
        runner,
        onClose: () => setRunner(null),
      }),
  );
}

function SavedReportCard({ report, onRun, onEdit, onDelete }) {
  const lastRun = report.last_executed_at
    ? new Date(report.last_executed_at)
    : null;
  const lastRunLabel = lastRun ? lastRun.toLocaleString() : "Never run";
  const status = report.last_execution_status;
  const statusColor =
    status === "success"
      ? "#0F8F47"
      : status === "partial"
        ? "var(--ds-warning-text)"
        : status === "error"
          ? "var(--ds-danger-text)"
          : C.textSecondary;
  const stepCount = Array.isArray(report.endpoint_chain?.steps)
    ? report.endpoint_chain.steps.length
    : 0;
  const rowCountTotal = Array.isArray(report.result_summary?.steps)
    ? report.result_summary.steps.reduce(
        (sum, s) => sum + (s.row_count || 0),
        0,
      )
    : null;

  return React.createElement(
    "div",
    {
      style: {
        padding: 16,
        background: C.cardBg,
        border: `1px solid ${C.border}`,
        borderRadius: 8,
        display: "flex",
        flexDirection: "column",
        gap: 10,
        boxShadow: C.cardShadow,
      },
    },
    React.createElement(
      "div",
      {
        style: {
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
          gap: 12,
        },
      },
      React.createElement(
        "div",
        { style: { flex: 1, minWidth: 0 } },
        React.createElement(
          "div",
          {
            style: {
              fontSize: 14,
              fontWeight: 700,
              color: C.textPrimary,
              marginBottom: 2,
            },
          },
          report.name,
        ),
        report.description &&
          React.createElement(
            "div",
            {
              style: {
                fontSize: 12,
                color: C.textSecondary,
                lineHeight: 1.4,
                whiteSpace: "pre-wrap",
              },
            },
            report.description,
          ),
      ),
      React.createElement(
        "span",
        {
          style: {
            fontSize: 10,
            fontWeight: 700,
            textTransform: "uppercase",
            letterSpacing: 0.5,
            color: statusColor,
            whiteSpace: "nowrap",
          },
        },
        status || "unrun",
      ),
    ),
    React.createElement(
      "div",
      {
        style: {
          fontSize: 11,
          color: C.textSecondary,
          display: "flex",
          gap: 12,
          flexWrap: "wrap",
        },
      },
      React.createElement(
        "span",
        null,
        stepCount,
        " step",
        stepCount === 1 ? "" : "s",
      ),
      rowCountTotal != null &&
        React.createElement(
          "span",
          null,
          rowCountTotal,
          " row",
          rowCountTotal === 1 ? "" : "s",
        ),
      React.createElement("span", null, "Last run: ", lastRunLabel),
    ),
    React.createElement(
      "div",
      { style: { display: "flex", gap: 8, marginTop: 4 } },
      React.createElement(
        "button",
        { onClick: onRun, style: cstrBtnPrimary() },
        "Run",
      ),
      React.createElement(
        "button",
        { onClick: onEdit, style: cstrBtnSecondary() },
        "Edit",
      ),
      React.createElement(
        "button",
        { onClick: onDelete, style: cstrBtnDanger() },
        "Delete",
      ),
    ),
  );
}

