function renderCellInlineContent({
  descriptor,
  isExpanded,
  onToggle,
  atOrPastDepthCap,
}) {
  const { mode, label, value } = descriptor;

  if (mode === "null" || mode === "primitive") {
    return formatPrimitiveCell(value);
  }
  if (mode === "array-empty") {
    return React.createElement(EmptyArrayBadge);
  }
  if (mode === "array-primitives") {
    return formatPrimitivesArrayPreview(value);
  }
  if (atOrPastDepthCap) {
    return React.createElement(ViewRawJsonEscape, {
      value,
      label: `${label} (depth cap reached — view raw)`,
    });
  }
  return React.createElement(
    "button",
    {
      type: "button",
      onClick: onToggle,
      "aria-expanded": isExpanded,
      style: {
        fontSize: 11,
        color: C.textPrimary,
        background: "transparent",
        border: "none",
        cursor: "pointer",
        padding: 0,
        fontFamily: "inherit",
        textAlign: "left",
      },
      title: isExpanded ? "Collapse nested table" : "Expand into nested table",
    },
    `${isExpanded ? "▼" : "▶"} ${label}`,
  );
}

function NestedTableRow({ row, rowIdx, colHeaders, depth, maxDepth }) {
  const [expandedCols, setExpandedCols] = React.useState({});
  const toggleCol = (col) =>
    setExpandedCols((prev) => ({ ...prev, [col]: !prev[col] }));

  const isPrimitiveRow =
    row === null ||
    row === undefined ||
    typeof row !== "object" ||
    Array.isArray(row);
  if (isPrimitiveRow) {
    return React.createElement(
      "tr",
      {
        style: { background: rowIdx % 2 ? C.subtleBg : "transparent" },
      },
      React.createElement(
        "td",
        {
          colSpan: colHeaders.length,
          style: {
            padding: "5px 8px",
            color: C.textPrimary,
            fontSize: 11,
            fontStyle: Array.isArray(row) ? "italic" : "normal",
          },
        },
        Array.isArray(row)
          ? formatPrimitivesArrayPreview(row)
          : formatPrimitiveCell(row),
      ),
    );
  }

  const cells = colHeaders.map((h) => {
    const value = row[h];
    return { col: h, descriptor: describeDrillDownValue(value) };
  });

  const nextDepth = depth + 1;
  const childAtCap = nextDepth >= maxDepth;
  const cellAtCap = depth >= maxDepth;

  const parentRow = React.createElement(
    "tr",
    {
      style: { background: rowIdx % 2 ? C.subtleBg : "transparent" },
    },
    cells.map(({ col, descriptor }) =>
      React.createElement(
        "td",
        {
          key: col,
          style: {
            padding: "5px 8px",
            color: C.textPrimary,
            fontSize: 11,
            whiteSpace: "nowrap",
            maxWidth: 240,
            overflow: "hidden",
            textOverflow: "ellipsis",
            verticalAlign: "top",
          },
        },
        renderCellInlineContent({
          descriptor,
          isExpanded: !!expandedCols[col],
          onToggle: () => toggleCol(col),
          atOrPastDepthCap: cellAtCap,
        }),
      ),
    ),
  );

  const childRows = cells
    .filter(
      ({ col, descriptor }) =>
        expandedCols[col] && isDrillable(descriptor.mode),
    )
    .map(({ col, descriptor }) => {
      const childTableRows =
        descriptor.mode === "object"
          ? objectToKeyValueRows(descriptor.value)
          : descriptor.value;

      const innerContent = childAtCap
        ? React.createElement(ViewRawJsonEscape, {
            value: descriptor.value,
            label: `Depth cap (${maxDepth}) reached — view raw JSON`,
          })
        : React.createElement(
            "div",
            { style: { overflow: "auto", maxHeight: 360 } },
            React.createElement(NestedTable, {
              rows: childTableRows,
              depth: nextDepth,
              maxDepth,
            }),
          );

      return React.createElement(
        "tr",
        { key: `child-${col}` },
        React.createElement(
          "td",
          {
            colSpan: colHeaders.length,
            style: {
              padding: 10,
              background: C.subtleBg,
              borderTop: `1px solid ${C.border}`,
              borderBottom: `1px solid ${C.border}`,
            },
          },
          React.createElement(
            "div",
            {
              style: {
                fontSize: 10,
                color: C.textSecondary,
                marginBottom: 6,
                display: "flex",
                alignItems: "center",
                gap: 6,
                flexWrap: "wrap",
              },
            },
            "↳ ",
            React.createElement(
              "span",
              {
                style: {
                  fontFamily: "ui-monospace,Menlo,monospace",
                  color: C.textPrimary,
                },
              },
              col,
            ),
            React.createElement(
              "span",
              {
                style: {
                  fontSize: 9,
                  fontWeight: 700,
                  textTransform: "uppercase",
                  letterSpacing: 0.4,
                  padding: "1px 6px",
                  borderRadius: 8,
                  background: C.cardBg,
                  border: `1px solid ${C.border}`,
                  color: C.textSecondary,
                  fontFamily: "ui-monospace,Menlo,monospace",
                },
                title: `Nesting depth ${nextDepth} of ${maxDepth} (max drill-down depth)`,
              },
              `depth ${nextDepth} / ${maxDepth}`,
            ),
          ),
          innerContent,
        ),
      );
    });

  return React.createElement(React.Fragment, null, parentRow, ...childRows);
}

function NestedTable({ rows, depth, maxDepth }) {
  const data = Array.isArray(rows) ? rows : [];

  if (data.length === 0) {
    return React.createElement(
      "div",
      {
        style: { fontSize: 11, color: C.textSecondary, padding: 8 },
      },
      "No rows.",
    );
  }

  const colHeaders = getColumnHeaders(data);
  const sliced = data.slice(0, NESTED_ROW_CAP);

  if (colHeaders.length === 0) {
    return React.createElement(
      "table",
      {
        style: { width: "100%", borderCollapse: "collapse", fontSize: 11 },
      },
      React.createElement(
        "tbody",
        null,
        sliced.map((v, i) =>
          React.createElement(
            "tr",
            {
              key: i,
              style: { background: i % 2 ? C.subtleBg : "transparent" },
            },
            React.createElement(
              "td",
              {
                style: {
                  padding: "5px 8px",
                  color: C.textPrimary,
                  fontSize: 11,
                },
              },
              formatPrimitiveCell(v),
            ),
          ),
        ),
      ),
    );
  }

  return React.createElement(
    React.Fragment,
    null,
    React.createElement(
      "table",
      {
        style: { width: "100%", borderCollapse: "collapse", fontSize: 11 },
      },
      React.createElement(
        "thead",
        null,
        React.createElement(
          "tr",
          null,
          colHeaders.map((h) =>
            React.createElement(
              "th",
              {
                key: h,
                style: {
                  padding: "6px 8px",
                  textAlign: "left",
                  borderBottom: `1px solid ${C.border}`,
                  color: C.textSecondary,
                  fontWeight: 600,
                  whiteSpace: "nowrap",
                },
              },
              h,
            ),
          ),
        ),
      ),
      React.createElement(
        "tbody",
        null,
        sliced.map((row, rowIdx) =>
          React.createElement(NestedTableRow, {
            key: rowIdx,
            row,
            rowIdx,
            colHeaders,
            depth,
            maxDepth,
          }),
        ),
      ),
    ),
    data.length > NESTED_ROW_CAP &&
      React.createElement(
        "div",
        {
          style: { fontSize: 11, color: C.textSecondary, padding: "6px 8px" },
        },
        `Showing ${NESTED_ROW_CAP} of ${data.length} rows. `,
        React.createElement(ViewRawJsonEscape, {
          value: data,
          label: `+${data.length - NESTED_ROW_CAP} more (view raw JSON for all rows)`,
        }),
      ),
  );
}

