  const calculateSectionCompletion = useCallback(
    (sectionKey) => {
      const data = clientData[sectionKey];
      if (!data) return 0;

      let filled = 0;
      let total = 0;

      if (Array.isArray(data)) {
        data.forEach((item) => {
          Object.values(item).forEach((val) => {
            total++;
            if (val && (typeof val === "string" ? val.trim() : val !== false))
              filled++;
          });
        });
      } else {
        Object.entries(data).forEach(([k, v]) => {
          total++;
          if (v && (typeof v === "string" ? v.trim() : v !== false)) filled++;
        });
      }

      return total > 0 ? Math.round((filled / total) * 100) : 0;
    },
    [clientData],
  );

