  React.useEffect(() => {
    if (!dataReady) return;
    console.log("[Realtime] Setting up subscriptions...");
    const realtimeTables = [
      "properties",
      "tenants",
      "work_orders",
      "distributions",
      "alerts",
      "investors",
      "capital_calls",
      "funds",
      "operating_budgets",
    ];
    let cancelled = false;

    const applyReload = async () => {
      if (cancelled) return;
      const isDemoMode =
        typeof window !== "undefined" &&
        window.localStorage?.getItem("demoMode") === "1";
      const pickData = (fromDb, fixture) => {
        if (Array.isArray(fromDb) && fromDb.length) return fromDb;
        return isDemoMode ? fixture : [];
      };
      try {
        const d = await reloadAllData();
        if (cancelled) return;
        FUND_DATA = pickData(d.funds, FUND_DATA);
        if (d.properties?.length) PROPERTIES = d.properties;
        PIPELINE = pickData(d.pipeline, PIPELINE);
        TENANTS = pickData(d.tenants, TENANTS);
        WORK_ORDERS = pickData(d.workOrders, WORK_ORDERS);
        DISTRIBUTIONS = pickData(d.distributions, DISTRIBUTIONS);
        INVESTORS = pickData(d.investors, INVESTORS);
        CAPITAL_CALLS = pickData(d.capitalCalls, CAPITAL_CALLS);
        ALERTS = pickData(d.alerts, ALERTS);
        OPERATING_BUDGETS = pickData(d.operatingBudgets, OPERATING_BUDGETS);
        ACTIVITY_FEED = pickData(d.activityFeed, ACTIVITY_FEED);
        setFormVersion((v) => v + 1);
        setLastDataSync(
          new Date().toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: true,
          }),
        );
      } catch (err) {
        console.error("[Realtime] Reload failed:", err);
      }
    };

    const scheduler = createReloadScheduler({ onReload: applyReload });

    const unsub = subscribeToAll(realtimeTables, (payload) => {
      console.log("[Realtime]", payload.event, "on", payload.table);
      scheduler.schedule();
    });

    return () => {
      cancelled = true;
      scheduler.dispose();
      if (unsub) unsub();
    };
  }, [dataReady]);

