          if (workspaceViews) {
            const wsSel =
              workspaceSelection &&
              workspaceSelection.module === landingSection.label
                ? workspaceSelection
                : null;
            const wsProperty = wsSel ? workspaceProperty : null;
            return (
              <ModuleWorkspacePage
                section={landingSection}
                C={C}
                propertyItems={propertySwitcherItems}
                views={workspaceViews}
                property={wsProperty}
                selectedPropertyKey={wsSel ? wsSel.propertyKey : null}
                activeViewKey={wsSel ? wsSel.view : null}
                initialDestinationKey={landingDestinationKey}
                copyLinkPath={withBasePath(copyLinkPath, DEEP_LINK_BASE_PATH)}
                onSelectProperty={(key, dest) => {
                  if (!confirmLeaveWorkspaceEditor()) return;
                  setWorkspaceSelection({
                    module: landingSection.label,
                    propertyKey: key,
                    view:
                      (dest && (dest.view || dest.key)) ||
                      (wsSel && wsSel.view) ||
                      null,
                  });
                }}
                onSelectView={(viewKey) => {
                  if (!wsSel) return;
                  if (viewKey !== wsSel.view && !confirmLeaveWorkspaceEditor())
                    return;
                  setWorkspaceSelection({ ...wsSel, view: viewKey });
                }}
                onBackToLanding={() => {
                  if (!confirmLeaveWorkspaceEditor()) return;
                  setWorkspaceSelection(null);
                }}
              />
            );
          }
          return (
            <SectionLandingPage
              section={landingSection}
              C={C}
              propertyItems={propertySwitcherItems}
              onNavigate={(key) => {
                setActiveSectionLanding(null);
                setActiveTab(key);
              }}
            />
          );
